insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'open-a-blocked-account', $seed${"slug":"open-a-blocked-account","title":{"en":"Open a blocked account","ne":"ब्लक्ड खाता खोल्नुहोस्","hi":"ब्लॉक्ड अकाउंट खोलें"},"term":{"term":"Sperrkonto"},"stage":"before","readingMinutes":6,"lastVerified":"2026-11-05","summary":{"what":{"en":"A German account that holds the money for your first year. Each month only a fixed amount is paid out to you. It is the usual proof that you can pay for your studies.","ne":"तपाईंको पहिलो वर्षको पैसा राख्ने जर्मन खाता। हरेक महिना एउटा तोकिएको रकम मात्र तपाईंलाई दिइन्छ। पढाइको खर्च धान्न सक्छु भन्ने सामान्य प्रमाण यही हो।","hi":"एक जर्मन खाता जिसमें आपके पहले साल का पैसा रहता है। हर महीने केवल एक तय रकम आपको मिलती है। यह इस बात का आम सबूत है कि आप पढ़ाई का खर्च उठा सकते हैं।"},"when":{"en":"Before you apply for the visa — the embassy wants the confirmation with your application.","ne":"भिसाको आवेदन दिनुअघि — दूतावासले आवेदनसँगै पुष्टि-पत्र माग्छ।","hi":"वीज़ा आवेदन से पहले — दूतावास आवेदन के साथ पुष्टि-पत्र मांगता है।"},"deadline":{"en":"Before your visa appointment","ne":"भिसा अपोइन्टमेन्टभन्दा पहिले","hi":"वीज़ा अपॉइंटमेंट से पहले"}},"steps":[{"title":{"en":"Check the amount for your year","ne":"आफ्नो वर्षको रकम जाँच्नुहोस्","hi":"अपने साल की रकम जांचें"},"body":{"en":"For 2026 students must show €11,904 for one year — that is €992 a month. The amount usually changes each year, so check the embassy page before you transfer.","ne":"२०२६ का लागि विद्यार्थीले एक वर्षका लागि €११,९०४ देखाउनुपर्छ — अर्थात् महिनामा €९९२। यो रकम प्रायः हरेक वर्ष बदलिन्छ, त्यसैले पैसा पठाउनुअघि दूतावासको पेज जाँच्नुहोस्।","hi":"2026 के लिए छात्रों को एक साल के लिए €11,904 दिखाने होते हैं — यानी हर महीने €992। यह रकम आमतौर पर हर साल बदलती है, इसलिए पैसा भेजने से पहले दूतावास का पेज देखें।"},"cost":{"en":"€11,904 for 12 months","ne":"१२ महिनाका लागि €११,९०४","hi":"12 महीनों के लिए €11,904"}},{"title":{"en":"Choose a provider","ne":"प्रदायक छान्नुहोस्","hi":"प्रदाता चुनें"},"body":{"en":"Blocked accounts are opened online with a provider. Fees differ by more than €100 in the first year — compare them. We list providers by fees, not by commission.","ne":"ब्लक्ड खाता कुनै प्रदायकमार्फत अनलाइन खोलिन्छ। पहिलो वर्षमा शुल्कमा €१०० भन्दा बढी फरक हुन्छ — तुलना गर्नुहोस्। हामी प्रदायकहरूलाई कमिसन होइन, शुल्कका आधारमा देखाउँछौं।","hi":"ब्लॉक्ड अकाउंट किसी प्रदाता के साथ ऑनलाइन खोला जाता है। पहले साल में फ़ीस में €100 से ज़्यादा का अंतर होता है — तुलना करें। हम प्रदाताओं को कमीशन से नहीं, फ़ीस के आधार पर दिखाते हैं।"}},{"title":{"en":"Fill in the application and verify your identity","ne":"आवेदन भर्नुहोस् र आफ्नो पहिचान पुष्टि गर्नुहोस्","hi":"आवेदन भरें और अपनी पहचान सत्यापित करें"},"body":{"en":"You enter your passport details and verify your identity online, usually by video call. Then you receive the account details for the transfer.","ne":"तपाईं राहदानीको विवरण भर्नुहुन्छ र प्रायः भिडियो कलमार्फत अनलाइन पहिचान पुष्टि गर्नुहुन्छ। त्यसपछि पैसा पठाउने खाता विवरण पाउनुहुन्छ।","hi":"आप पासपोर्ट का विवरण भरते हैं और आमतौर पर वीडियो कॉल से ऑनलाइन पहचान सत्यापित करते हैं। फिर आपको पैसा भेजने के लिए खाते का विवरण मिलता है।"},"documents":[{"en":"Passport","ne":"राहदानी","hi":"पासपोर्ट"},{"en":"Admission letter (if you have it)","ne":"भर्ना पत्र (छ भने)","hi":"प्रवेश पत्र (अगर हो)"}]},{"title":{"en":"Transfer the money from an account in your name","ne":"आफ्नै नामको खाताबाट पैसा पठाउनुहोस्","hi":"अपने नाम के खाते से पैसा भेजें"},"body":{"en":"Send the full amount plus any buffer the provider asks for. International transfers take a few working days. Keep the bank receipt.","ne":"पूरा रकम र प्रदायकले माग्ने थप रकम पठाउनुहोस्। अन्तर्राष्ट्रिय ट्रान्सफरमा केही कार्यदिन लाग्छ। बैंकको रसिद राख्नुहोस्।","hi":"पूरी रकम और प्रदाता जो अतिरिक्त राशि मांगे, भेजें। अंतरराष्ट्रीय ट्रांसफ़र में कुछ कार्यदिवस लगते हैं। बैंक की रसीद रखें।"},"wait":{"en":"A few working days","ne":"केही कार्यदिन","hi":"कुछ कार्यदिवस"}},{"title":{"en":"Download the blocking confirmation","ne":"ब्लक पुष्टि-पत्र डाउनलोड गर्नुहोस्","hi":"ब्लॉकिंग पुष्टि-पत्र डाउनलोड करें"},"body":{"en":"When the money has arrived, the provider sends a confirmation. Bring it to your visa appointment. In Germany you need it again for your residence permit.","ne":"पैसा पुगेपछि प्रदायकले पुष्टि-पत्र पठाउँछ। यसलाई भिसा अपोइन्टमेन्टमा लैजानुहोस्। जर्मनीमा आवास अनुमतिपत्रका लागि फेरि चाहिन्छ।","hi":"पैसा पहुंचने पर प्रदाता पुष्टि-पत्र भेजता है। इसे वीज़ा अपॉइंटमेंट पर ले जाएं। जर्मनी में निवास परमिट के लिए यह फिर से चाहिए।"},"term":{"term":"Sperrbestätigung"}}],"documents":[{"en":"Passport","ne":"राहदानी","hi":"पासपोर्ट"},{"en":"Admission letter from the university","ne":"विश्वविद्यालयको भर्ना पत्र","hi":"विश्वविद्यालय का प्रवेश पत्र"},{"en":"Proof of the transfer","ne":"पैसा पठाएको प्रमाण","hi":"पैसा भेजने का सबूत"}],"callouts":[{"kind":"tip","text":{"en":"Germany’s missions in Nepal and India also accept other proofs in some cases, such as a scholarship or a formal obligation letter from someone in Germany (Verpflichtungserklärung). Check your embassy’s checklist.","ne":"नेपाल र भारतका जर्मन नियोगहरूले केही अवस्थामा छात्रवृत्ति वा जर्मनीमा बस्ने कसैको औपचारिक जिम्मेवारी पत्र (Verpflichtungserklärung) जस्ता अन्य प्रमाण पनि स्वीकार्छन्। आफ्नो दूतावासको चेकलिस्ट हेर्नुहोस्।","hi":"नेपाल और भारत में जर्मन मिशन कुछ मामलों में दूसरे सबूत भी मानते हैं, जैसे छात्रवृत्ति या जर्मनी में रहने वाले किसी व्यक्ति का औपचारिक दायित्व पत्र (Verpflichtungserklärung)। अपने दूतावास की चेकलिस्ट देखें।"}},{"kind":"mistake","text":{"en":"Don’t pay a “visa agent” to open the account for you. You can open it yourself online, and it must be in your own name.","ne":"खाता खोलिदिन “भिसा एजेन्ट”लाई पैसा नतिर्नुहोस्। तपाईं आफैं अनलाइन खोल्न सक्नुहुन्छ, र खाता तपाईंकै नाममा हुनुपर्छ।","hi":"अकाउंट खुलवाने के लिए किसी “वीज़ा एजेंट” को पैसे न दें। आप इसे खुद ऑनलाइन खोल सकते हैं, और यह आपके ही नाम पर होना चाहिए।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"tool","title":{"en":"Compare blocked accounts","ne":"ब्लक्ड खाताहरू तुलना गर्नुहोस्","hi":"ब्लॉक्ड अकाउंट की तुलना करें"},"href":"/tools/compare/blocked-accounts"},{"kind":"guide","title":{"en":"Apply for your student visa","ne":"विद्यार्थी भिसाका लागि आवेदन दिनुहोस्","hi":"स्टूडेंट वीज़ा के लिए आवेदन करें"},"href":"/guides/apply-for-student-visa"}],"sources":[{"title":"Federal Foreign Office — Opening a blocked account","url":"https://maskat.diplo.de/om-de/service/05-visaeinreise/2164012-2164012"},{"title":"German Embassy Kathmandu — Study visa","url":"https://kathmandu.diplo.de/np-en/service/01-visaeinreise/2225320-2225320"},{"title":"German Missions in India — National visa FAQs","url":"https://india.diplo.de/in-en/service/2546328-2546328"}],"compareLink":{"label":{"en":"Compare providers","ne":"प्रदायकहरू तुलना गर्नुहोस्","hi":"प्रदाताओं की तुलना करें"},"href":"/tools/compare/blocked-accounts"}}$seed$::jsonb, 0) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'apply-for-student-visa', $seed${"slug":"apply-for-student-visa","title":{"en":"Apply for your student visa","ne":"विद्यार्थी भिसाका लागि आवेदन दिनुहोस्","hi":"स्टूडेंट वीज़ा के लिए आवेदन करें"},"term":{"term":"Visum zu Studienzwecken"},"stage":"before","readingMinutes":8,"lastVerified":"2026-11-05","summary":{"what":{"en":"A national visa (type D) that lets you enter Germany to study. In Germany you then turn it into a residence permit.","ne":"जर्मनीमा पढ्न प्रवेश गर्न दिने राष्ट्रिय भिसा (टाइप D)। जर्मनी पुगेपछि यसलाई आवास अनुमतिपत्रमा बदल्नुहुन्छ।","hi":"एक राष्ट्रीय वीज़ा (टाइप D) जिससे आप पढ़ाई के लिए जर्मनी आ सकते हैं। जर्मनी में आप इसे निवास परमिट में बदलते हैं।"},"when":{"en":"As soon as you have your admission letter. Appointments can be booked out for weeks.","ne":"भर्ना पत्र पाउनेबित्तिकै। अपोइन्टमेन्ट हप्तौंसम्म भरिएको हुन सक्छ।","hi":"जैसे ही आपको प्रवेश पत्र मिले। अपॉइंटमेंट कई हफ़्तों तक भरे हो सकते हैं।"},"deadline":{"en":"Well before your semester starts","ne":"सेमेस्टर सुरु हुनुभन्दा धेरै अगाडि","hi":"सेमेस्टर शुरू होने से काफ़ी पहले"}},"steps":[{"title":{"en":"Download your embassy’s checklist","ne":"आफ्नो दूतावासको चेकलिस्ट डाउनलोड गर्नुहोस्","hi":"अपने दूतावास की चेकलिस्ट डाउनलोड करें"},"body":{"en":"Nepal: German Embassy Kathmandu. India: the German mission for your state, with applications through VFS Global. Each publishes its own checklist — follow it exactly, including the order of documents.","ne":"नेपाल: काठमाडौंस्थित जर्मन दूतावास। भारत: तपाईंको राज्यको जर्मन नियोग, आवेदन VFS Global मार्फत। हरेकले आफ्नै चेकलिस्ट प्रकाशित गर्छ — कागजातको क्रमसहित ठ्याक्कै पालना गर्नुहोस्।","hi":"नेपाल: काठमांडू स्थित जर्मन दूतावास। भारत: आपके राज्य का जर्मन मिशन, आवेदन VFS Global के ज़रिए। हर मिशन अपनी चेकलिस्ट प्रकाशित करता है — दस्तावेज़ों के क्रम सहित उसका ठीक-ठीक पालन करें।"}},{"title":{"en":"India only: get your APS certificate","ne":"भारत मात्र: APS प्रमाणपत्र लिनुहोस्","hi":"केवल भारत: APS प्रमाणपत्र लें"},"body":{"en":"Students from India need a certificate from the Academic Evaluation Centre (APS) before they can apply. It takes time, so start early.","ne":"भारतका विद्यार्थीलाई आवेदन दिनुअघि Academic Evaluation Centre (APS) को प्रमाणपत्र चाहिन्छ। यसमा समय लाग्छ, त्यसैले चाँडै सुरु गर्नुहोस्।","hi":"भारत के छात्रों को आवेदन से पहले Academic Evaluation Centre (APS) का प्रमाणपत्र चाहिए। इसमें समय लगता है, इसलिए जल्दी शुरू करें।"},"term":{"term":"APS-Zertifikat"}},{"title":{"en":"Prepare proof of money and insurance","ne":"पैसा र बीमाको प्रमाण तयार गर्नुहोस्","hi":"पैसे और बीमा का सबूत तैयार करें"},"body":{"en":"Usually a blocked account confirmation (€11,904 for 2026). You also need travel health insurance that covers you until your German health insurance starts.","ne":"प्रायः ब्लक्ड खाताको पुष्टि-पत्र (२०२६ का लागि €११,९०४)। जर्मन स्वास्थ्य बीमा सुरु नहुँदासम्मको यात्रा स्वास्थ्य बीमा पनि चाहिन्छ।","hi":"आमतौर पर ब्लॉक्ड अकाउंट का पुष्टि-पत्र (2026 के लिए €11,904)। जर्मन स्वास्थ्य बीमा शुरू होने तक के लिए यात्रा स्वास्थ्य बीमा भी चाहिए।"}},{"title":{"en":"Book the appointment yourself","ne":"अपोइन्टमेन्ट आफैं बुक गर्नुहोस्","hi":"अपॉइंटमेंट खुद बुक करें"},"body":{"en":"Appointments are booked online and are free. Nobody can sell you a faster appointment — the embassies warn about agents who claim this.","ne":"अपोइन्टमेन्ट अनलाइन बुक गरिन्छ र निःशुल्क हुन्छ। कसैले पनि छिटो अपोइन्टमेन्ट बेच्न सक्दैन — दूतावासहरूले यस्तो दाबी गर्ने एजेन्टबारे चेतावनी दिएका छन्।","hi":"अपॉइंटमेंट ऑनलाइन बुक होते हैं और मुफ़्त हैं। कोई भी आपको जल्दी अपॉइंटमेंट नहीं बेच सकता — दूतावास ऐसे दावे करने वाले एजेंटों से सावधान करते हैं।"},"cost":{"en":"Appointment: free · visa fee: €75 in local currency","ne":"अपोइन्टमेन्ट: निःशुल्क · भिसा शुल्क: स्थानीय मुद्रामा €७५","hi":"अपॉइंटमेंट: मुफ़्त · वीज़ा फ़ीस: स्थानीय मुद्रा में €75"}},{"title":{"en":"Hand in your application and wait","ne":"आवेदन बुझाउनुहोस् र पर्खनुहोस्","hi":"आवेदन जमा करें और इंतज़ार करें"},"body":{"en":"You give your fingerprints and documents. The foreigners’ office in your German city may have to agree, which takes several weeks. Don’t book a flight you can’t change.","ne":"तपाईं औंठाछाप र कागजात दिनुहुन्छ। तपाईंको जर्मन सहरको विदेशी कार्यालयले सहमति दिनुपर्ने हुन सक्छ, जसमा केही हप्ता लाग्छ। परिवर्तन गर्न नमिल्ने उडान टिकट नकिन्नुहोस्।","hi":"आप उंगलियों के निशान और दस्तावेज़ देते हैं। आपके जर्मन शहर के विदेशी कार्यालय की सहमति लग सकती है, जिसमें कई हफ़्ते लगते हैं। ऐसी फ़्लाइट न बुक करें जिसे बदला न जा सके।"},"wait":{"en":"Several weeks","ne":"केही हप्ता","hi":"कई हफ़्ते"}}],"documents":[{"en":"Passport (valid long enough, with empty pages)","ne":"राहदानी (पर्याप्त म्याद र खाली पानासहित)","hi":"पासपोर्ट (पर्याप्त वैधता और खाली पन्नों के साथ)"},{"en":"Completed visa application form","ne":"भरिएको भिसा आवेदन फारम","hi":"भरा हुआ वीज़ा आवेदन फ़ॉर्म"},{"en":"Admission letter from the German university","ne":"जर्मन विश्वविद्यालयको भर्ना पत्र","hi":"जर्मन विश्वविद्यालय का प्रवेश पत्र"},{"en":"Proof of money, e.g. blocked account confirmation","ne":"पैसाको प्रमाण, जस्तै ब्लक्ड खाता पुष्टि-पत्र","hi":"पैसे का सबूत, जैसे ब्लॉक्ड अकाउंट पुष्टि-पत्र"},{"en":"Travel health insurance","ne":"यात्रा स्वास्थ्य बीमा","hi":"यात्रा स्वास्थ्य बीमा"},{"en":"Certificates and language certificate (as on the checklist)","ne":"शैक्षिक प्रमाणपत्र र भाषा प्रमाणपत्र (चेकलिस्टअनुसार)","hi":"शैक्षिक प्रमाणपत्र और भाषा प्रमाणपत्र (चेकलिस्ट के अनुसार)"},{"en":"India: APS certificate","ne":"भारत: APS प्रमाणपत्र","hi":"भारत: APS प्रमाणपत्र"}],"callouts":[{"kind":"warning","text":{"en":"Fake documents lead to refusal and can lead to a ban on entering Germany. No agent can guarantee a visa.","ne":"नक्कली कागजातले भिसा अस्वीकृत हुन्छ र जर्मनी प्रवेशमा प्रतिबन्ध पनि लाग्न सक्छ। कुनै पनि एजेन्टले भिसाको ग्यारेन्टी दिन सक्दैन।","hi":"नकली दस्तावेज़ों से वीज़ा अस्वीकार होता है और जर्मनी आने पर रोक भी लग सकती है। कोई भी एजेंट वीज़ा की गारंटी नहीं दे सकता।"}},{"kind":"tip","text":{"en":"India: the German missions accept language certificates such as IELTS, TOEFL, Goethe, telc or TestDaF — Duolingo is not accepted.","ne":"भारत: जर्मन नियोगहरूले IELTS, TOEFL, Goethe, telc वा TestDaF जस्ता भाषा प्रमाणपत्र स्वीकार्छन् — Duolingo स्वीकार्दैनन्।","hi":"भारत: जर्मन मिशन IELTS, TOEFL, Goethe, telc या TestDaF जैसे भाषा प्रमाणपत्र मानते हैं — Duolingo नहीं माना जाता।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Open a blocked account","ne":"ब्लक्ड खाता खोल्नुहोस्","hi":"ब्लॉक्ड अकाउंट खोलें"},"href":"/guides/open-a-blocked-account"},{"kind":"guide","title":{"en":"Get health insurance","ne":"स्वास्थ्य बीमा लिनुहोस्","hi":"स्वास्थ्य बीमा लें"},"href":"/guides/get-health-insurance"}],"sources":[{"title":"German Embassy Kathmandu — Study visa","url":"https://kathmandu.diplo.de/np-en/service/01-visaeinreise/2225320-2225320"},{"title":"German Embassy Kathmandu — Student visa checklist (PDF)","url":"https://kathmandu.diplo.de/resource/blob/1788692/b9b4dfbe10df74e88aa11e36364d9721/student-visa-checklist-data.pdf"},{"title":"German Embassy Kathmandu — Do I need an appointment?","url":"https://kathmandu.diplo.de/np-en/service/01-visaeinreise/2314484-2314484"},{"title":"German Missions in India — Studies","url":"https://india.diplo.de/in-en/service/2756350-2756350"},{"title":"German Missions in India — Student visa checklist (PDF)","url":"https://india.diplo.de/resource/blob/2667080/85ccf154e38cd7c5c36721503a49774c/infostudents-data.pdf"},{"title":"German Consulate General Mumbai — Beware of fraud","url":"https://india.diplo.de/in-en/ueber-uns/mumbai/beware-of-fraud-1988568"}]}$seed$::jsonb, 10) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'get-health-insurance', $seed${"slug":"get-health-insurance","title":{"en":"Get health insurance","ne":"स्वास्थ्य बीमा लिनुहोस्","hi":"स्वास्थ्य बीमा लें"},"term":{"term":"Krankenversicherung"},"stage":"before","readingMinutes":5,"lastVerified":"2026-11-05","summary":{"what":{"en":"Health insurance is compulsory in Germany. You need travel insurance for the visa and the first days, then a German health insurance for your studies.","ne":"जर्मनीमा स्वास्थ्य बीमा अनिवार्य छ। भिसा र सुरुका दिनका लागि यात्रा बीमा, त्यसपछि पढाइका लागि जर्मन स्वास्थ्य बीमा चाहिन्छ।","hi":"जर्मनी में स्वास्थ्य बीमा अनिवार्य है। वीज़ा और शुरुआती दिनों के लिए यात्रा बीमा, फिर पढ़ाई के लिए जर्मन स्वास्थ्य बीमा चाहिए।"},"when":{"en":"Travel insurance before the visa appointment. German insurance before you enrol.","ne":"भिसा अपोइन्टमेन्टअघि यात्रा बीमा। भर्ना हुनुअघि जर्मन बीमा।","hi":"वीज़ा अपॉइंटमेंट से पहले यात्रा बीमा। दाख़िले से पहले जर्मन बीमा।"},"deadline":{"en":"Before enrolment","ne":"भर्ना हुनुअघि","hi":"दाख़िले से पहले"}},"steps":[{"title":{"en":"Buy travel health insurance for the start","ne":"सुरुका लागि यात्रा स्वास्थ्य बीमा किन्नुहोस्","hi":"शुरुआत के लिए यात्रा स्वास्थ्य बीमा खरीदें"},"body":{"en":"The embassy needs it for the visa. It must cover you from arrival until your German insurance starts — the German missions in India ask for the first 90 days.","ne":"भिसाका लागि दूतावासलाई यो चाहिन्छ। आइपुगेदेखि जर्मन बीमा सुरु नहुँदासम्म यसले कभर गर्नुपर्छ — भारतका जर्मन नियोगहरूले पहिलो ९० दिन माग्छन्।","hi":"वीज़ा के लिए दूतावास को यह चाहिए। यह पहुंचने से लेकर जर्मन बीमा शुरू होने तक कवर करे — भारत में जर्मन मिशन पहले 90 दिन मांगते हैं।"},"term":{"term":"Reisekrankenversicherung"}},{"title":{"en":"Choose a statutory health insurance fund","ne":"सरकारी स्वास्थ्य बीमा कोष छान्नुहोस्","hi":"वैधानिक स्वास्थ्य बीमा कोष चुनें"},"body":{"en":"Students under 30 are usually insured in statutory insurance at the student rate. All funds pay the same base rate; they differ in the additional contribution and extras. Travel insurance is not accepted for enrolment.","ne":"३० वर्षमुनिका विद्यार्थी प्रायः विद्यार्थी दरमा सरकारी बीमामा बीमित हुन्छन्। सबै कोषको आधार दर उस्तै हुन्छ; अतिरिक्त योगदान र सुविधामा फरक हुन्छ। भर्नाका लागि यात्रा बीमा मान्य हुँदैन।","hi":"30 साल से कम उम्र के छात्र आमतौर पर छात्र दर पर वैधानिक बीमा में बीमित होते हैं। सभी कोषों की मूल दर एक जैसी है; अंतर अतिरिक्त योगदान और सुविधाओं में है। दाख़िले के लिए यात्रा बीमा मान्य नहीं है।"},"term":{"term":"gesetzliche Krankenkasse"},"cost":{"en":"About €140–150 a month in 2026 (incl. care insurance)","ne":"२०२६ मा महिनाको करिब €१४०–१५० (हेरचाह बीमासहित)","hi":"2026 में हर महीने लगभग €140–150 (देखभाल बीमा सहित)"}},{"title":{"en":"Apply online and give your German address later","ne":"अनलाइन आवेदन दिनुहोस्, जर्मन ठेगाना पछि दिनुहोस्","hi":"ऑनलाइन आवेदन करें, जर्मन पता बाद में दें"},"body":{"en":"Most funds let you apply online with your passport and admission letter. Insurance starts at the beginning of the semester at the latest.","ne":"धेरैजसो कोषले राहदानी र भर्ना पत्र लिएर अनलाइन आवेदन दिन दिन्छन्। बीमा बढीमा सेमेस्टर सुरु हुँदा सुरु हुन्छ।","hi":"ज़्यादातर कोष पासपोर्ट और प्रवेश पत्र के साथ ऑनलाइन आवेदन करने देते हैं। बीमा ज़्यादा से ज़्यादा सेमेस्टर की शुरुआत से शुरू होता है।"}},{"title":{"en":"Private insurance? Get it exempted first","ne":"निजी बीमा? पहिले छुट लिनुहोस्","hi":"निजी बीमा? पहले छूट लें"},"body":{"en":"If you want private insurance, a statutory fund must first confirm your exemption from compulsory insurance. The decision usually applies for your whole studies and can’t be reversed.","ne":"निजी बीमा चाहनुहुन्छ भने पहिले कुनै सरकारी कोषले अनिवार्य बीमाबाट छुट पुष्टि गर्नुपर्छ। यो निर्णय प्रायः पूरा पढाइभर लागू हुन्छ र फिर्ता लिन मिल्दैन।","hi":"अगर आप निजी बीमा चाहते हैं, तो पहले किसी वैधानिक कोष को अनिवार्य बीमा से आपकी छूट की पुष्टि करनी होगी। यह फ़ैसला आमतौर पर पूरी पढ़ाई के लिए लागू होता है और बदला नहीं जा सकता।"},"term":{"term":"Befreiung von der Versicherungspflicht"}}],"documents":[{"en":"Passport","ne":"राहदानी","hi":"पासपोर्ट"},{"en":"Admission letter","ne":"भर्ना पत्र","hi":"प्रवेश पत्र"},{"en":"Passport photo for the health card","ne":"स्वास्थ्य कार्डका लागि राहदानी साइजको फोटो","hi":"हेल्थ कार्ड के लिए पासपोर्ट साइज़ फ़ोटो"}],"callouts":[{"kind":"tip","text":{"en":"The 2026 student rate is €87.38 plus your fund’s additional contribution, plus care insurance (€30.78 under 23, €35.91 from 23 without children). Example: TK costs €141.16 under 23.","ne":"२०२६ को विद्यार्थी दर €८७.३८ र तपाईंको कोषको अतिरिक्त योगदान, साथै हेरचाह बीमा (२३ वर्षमुनि €३०.७८, २३ वर्षदेखि सन्तान नभएमा €३५.९१) हो। उदाहरण: TK मा २३ वर्षमुनि €१४१.१६।","hi":"2026 की छात्र दर €87.38 और आपके कोष का अतिरिक्त योगदान, साथ में देखभाल बीमा (23 से कम उम्र पर €30.78, 23 से ऊपर बिना बच्चों के €35.91) है। उदाहरण: TK में 23 से कम उम्र पर €141.16।"}},{"kind":"mistake","text":{"en":"Don’t rely on travel insurance after arrival — Leipzig University does not accept it for enrolment.","ne":"आइपुगेपछि यात्रा बीमामा भर नपर्नुहोस् — लाइपजिग विश्वविद्यालयले भर्नाका लागि यसलाई मान्दैन।","hi":"पहुंचने के बाद यात्रा बीमा पर निर्भर न रहें — लाइपज़िग विश्वविद्यालय दाख़िले के लिए इसे नहीं मानता।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Activate your health insurance","ne":"स्वास्थ्य बीमा सक्रिय गर्नुहोस्","hi":"स्वास्थ्य बीमा सक्रिय करें"},"href":"/guides/activate-health-insurance"},{"kind":"tool","title":{"en":"Plan your monthly budget","ne":"मासिक बजेट योजना बनाउनुहोस्","hi":"मासिक बजट की योजना बनाएं"},"href":"/tools/budget"}],"sources":[{"title":"GKV-Spitzenverband — Contribution figures 2026 (PDF)","url":"https://www.gkv-spitzenverband.de/media/dokumente/presse/zahlen_und_grafiken/20260101_Faktenblatt_Rechengroessen_Beitragsrecht.pdf"},{"title":"Techniker Krankenkasse — Contribution for students","url":"https://www.tk.de/techniker/versicherung/gut-versichert-in-jeder-lebenslage/versichert-als-studierende/krankenversicherung-und-studium/beitrag-studierende-2131472"},{"title":"Leipzig University — Health insurance guide for international students (PDF)","url":"https://www.uni-leipzig.de/fileadmin/ul/Dokumente/230222_SI_Ratgeber_Krankenversicherung_en.pdf"},{"title":"German Missions in India — Student visa checklist (PDF)","url":"https://india.diplo.de/resource/blob/2667080/85ccf154e38cd7c5c36721503a49774c/infostudents-data.pdf"}]}$seed$::jsonb, 20) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'register-your-address', $seed${"slug":"register-your-address","title":{"en":"Register your address","ne":"आफ्नो ठेगाना दर्ता गर्नुहोस्","hi":"अपना पता पंजीकृत करें"},"term":{"term":"Anmeldung"},"stage":"first30","city":"leipzig","readingMinutes":6,"lastVerified":"2026-11-05","summary":{"what":{"en":"Telling the city where you live. You get a registration certificate that the bank, the foreigners’ office and many others ask for.","ne":"तपाईं कहाँ बस्नुहुन्छ भनेर सहरलाई जानकारी दिनु। तपाईंले दर्ता प्रमाणपत्र पाउनुहुन्छ, जुन बैंक, विदेशी कार्यालय र अरू धेरैले माग्छन्।","hi":"शहर को बताना कि आप कहाँ रहते हैं। आपको पंजीकरण प्रमाणपत्र मिलता है, जिसे बैंक, विदेशी कार्यालय और कई दूसरे मांगते हैं।"},"when":{"en":"Every time you move into a new flat in Germany.","ne":"जर्मनीमा हरेक पटक नयाँ फ्ल्याटमा सर्दा।","hi":"जर्मनी में हर बार नए फ़्लैट में जाने पर।"},"deadline":{"en":"Within 2 weeks of moving in","ne":"सरेको २ हप्ताभित्र","hi":"शिफ़्ट होने के 2 हफ़्ते के अंदर"}},"steps":[{"title":{"en":"Get the landlord’s confirmation","ne":"घरधनीको पुष्टि-पत्र लिनुहोस्","hi":"मकान मालिक का पुष्टि-पत्र लें"},"body":{"en":"Your landlord (or the Studentenwerk for a dorm) confirms in writing that you moved in. Your rental contract is not enough. You can use the city’s form. If you don’t have it yet, you can register anyway and hand it in later.","ne":"तपाईंको घरधनी (छात्रावास भए Studentenwerk) ले तपाईं सर्नुभएको लिखित पुष्टि दिन्छ। भाडा सम्झौता मात्र पुग्दैन। सहरको फारम प्रयोग गर्न सकिन्छ। अहिलेसम्म छैन भने पनि दर्ता गर्न सक्नुहुन्छ र पछि बुझाउन सक्नुहुन्छ।","hi":"आपका मकान मालिक (हॉस्टल हो तो Studentenwerk) लिखित में पुष्टि करता है कि आप रहने आए हैं। किराया अनुबंध काफ़ी नहीं है। आप शहर का फ़ॉर्म इस्तेमाल कर सकते हैं। अभी नहीं है तो भी पंजीकरण कर सकते हैं और बाद में जमा कर सकते हैं।"},"term":{"term":"Wohnungsgeberbestätigung"}},{"title":{"en":"Book an appointment at a Bürgerbüro","ne":"Bürgerbüro मा अपोइन्टमेन्ट बुक गर्नुहोस्","hi":"Bürgerbüro में अपॉइंटमेंट बुक करें"},"body":{"en":"Book on the city’s appointment website or call 115. Any Bürgerbüro in Leipzig can register you. New slots are released every day at 8:00 — at Otto-Schill-Straße also at 12:00.","ne":"सहरको अपोइन्टमेन्ट वेबसाइटमा बुक गर्नुहोस् वा ११५ मा फोन गर्नुहोस्। लाइपजिगको जुनसुकै Bürgerbüro ले दर्ता गर्न सक्छ। नयाँ समय हरेक दिन बिहान ८:०० बजे खुल्छ — Otto-Schill-Straße मा दिउँसो १२:०० बजे पनि।","hi":"शहर की अपॉइंटमेंट वेबसाइट पर बुक करें या 115 पर कॉल करें। लाइपज़िग का कोई भी Bürgerbüro पंजीकरण कर सकता है। नए स्लॉट हर दिन सुबह 8:00 बजे खुलते हैं — Otto-Schill-Straße में दोपहर 12:00 बजे भी।"},"where":{"en":"Any Bürgerbüro, e.g. Otto-Schill-Straße 2, 04109 Leipzig","ne":"जुनसुकै Bürgerbüro, जस्तै Otto-Schill-Straße 2, 04109 Leipzig","hi":"कोई भी Bürgerbüro, जैसे Otto-Schill-Straße 2, 04109 Leipzig"},"cost":{"en":"Free","ne":"निःशुल्क","hi":"मुफ़्त"}},{"title":{"en":"Fill in the registration form","ne":"दर्ता फारम भर्नुहोस्","hi":"पंजीकरण फ़ॉर्म भरें"},"body":{"en":"Fill in the registration form before the appointment — it saves time. Each adult registers; you can register family members who move in with you at the same time.","ne":"अपोइन्टमेन्टअघि दर्ता फारम भर्नुहोस् — समय बच्छ। हरेक वयस्कले दर्ता गर्छ; सँगै सर्ने परिवारका सदस्यलाई एकैपटक दर्ता गर्न सकिन्छ।","hi":"अपॉइंटमेंट से पहले पंजीकरण फ़ॉर्म भर लें — समय बचता है। हर वयस्क पंजीकरण करता है; साथ में आने वाले परिवार के सदस्यों का एक साथ पंजीकरण हो सकता है।"},"term":{"term":"Meldeformular"}},{"title":{"en":"Go to the appointment","ne":"अपोइन्टमेन्टमा जानुहोस्","hi":"अपॉइंटमेंट पर जाएं"},"body":{"en":"Bring your original passport. You leave with the registration certificate. Keep it safe and make copies.","ne":"सक्कली राहदानी लैजानुहोस्। तपाईं दर्ता प्रमाणपत्र लिएर निस्कनुहुन्छ। सुरक्षित राख्नुहोस् र प्रतिलिपि बनाउनुहोस्।","hi":"असली पासपोर्ट साथ ले जाएं। आप पंजीकरण प्रमाणपत्र लेकर निकलते हैं। इसे संभालकर रखें और कॉपी बनाएं।"},"term":{"term":"Meldebescheinigung"},"wait":{"en":"Usually done in one visit","ne":"प्रायः एकै भेटमा सकिन्छ","hi":"आमतौर पर एक ही बार में हो जाता है"}}],"documents":[{"en":"Passport with visa","ne":"भिसासहितको राहदानी","hi":"वीज़ा सहित पासपोर्ट"},{"en":"Landlord’s confirmation (Wohnungsgeberbestätigung)","ne":"घरधनीको पुष्टि-पत्र (Wohnungsgeberbestätigung)","hi":"मकान मालिक का पुष्टि-पत्र (Wohnungsgeberbestätigung)"},{"en":"Registration form, filled in","ne":"भरिएको दर्ता फारम","hi":"भरा हुआ पंजीकरण फ़ॉर्म"}],"callouts":[{"kind":"tip","text":{"en":"No free slot? Check the booking page right at 8:00 in the morning, when new slots are released.","ne":"खाली समय छैन? बिहान ठीक ८:०० बजे बुकिङ पेज हेर्नुहोस्, त्यही बेला नयाँ समय खुल्छ।","hi":"कोई स्लॉट खाली नहीं? सुबह ठीक 8:00 बजे बुकिंग पेज देखें, तभी नए स्लॉट खुलते हैं।"}},{"kind":"mistake","text":{"en":"Waiting for a slot doesn’t pause the 2 weeks. Book on day one, even if the appointment is later.","ne":"समय पर्खँदा २ हप्ताको अवधि रोकिँदैन। अपोइन्टमेन्ट पछि भए पनि पहिलो दिनमै बुक गर्नुहोस्।","hi":"स्लॉट का इंतज़ार 2 हफ़्ते की अवधि को नहीं रोकता। अपॉइंटमेंट बाद का हो तब भी पहले दिन ही बुक करें।"}},{"kind":"warning","text":{"en":"Moving again? Register the new address within 2 weeks too. When you leave Germany, deregister.","ne":"फेरि सर्दै हुनुहुन्छ? नयाँ ठेगाना पनि २ हप्ताभित्र दर्ता गर्नुहोस्। जर्मनी छोड्दा दर्ता खारेज गर्नुहोस्।","hi":"फिर से शिफ़्ट हो रहे हैं? नया पता भी 2 हफ़्ते के अंदर पंजीकृत करें। जर्मनी छोड़ते समय पंजीकरण रद्द करें।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Open a bank account","ne":"बैंक खाता खोल्नुहोस्","hi":"बैंक खाता खोलें"},"href":"/guides/open-a-bank-account"},{"kind":"guide","title":{"en":"Get your tax ID","ne":"आफ्नो कर आईडी लिनुहोस्","hi":"अपनी टैक्स आईडी पाएं"},"href":"/guides/get-your-tax-id"}],"actions":[{"label":{"en":"Book an appointment online","ne":"अनलाइन अपोइन्टमेन्ट बुक गर्नुहोस्","hi":"ऑनलाइन अपॉइंटमेंट बुक करें"},"url":"https://terminvereinbarung.leipzig.de"},{"label":{"en":"Landlord’s confirmation form","ne":"घरधनीको पुष्टि-पत्र फारम","hi":"मकान मालिक पुष्टि-पत्र फ़ॉर्म"},"url":"https://www.leipzig.de/service-portal/formulare/formular/wohnungsgeberbestaetigung-bmg/download"}],"sources":[{"title":"Stadt Leipzig — Wohnung an- oder ummelden","url":"https://www.leipzig.de/service-portal/dienstleistung/wohnung-an-oder-ummelden-5333e768c725b/"},{"title":"City of Leipzig — Registering a place of residence","url":"https://english.leipzig.de/construction-and-residence/residence/registering-or-changing-registration-of-residence"},{"title":"Stadt Leipzig — Wohnungsgeberbestätigung (form)","url":"https://www.leipzig.de/service-portal/formulare/formular/wohnungsgeberbestaetigung-bmg/download"},{"title":"Stadt Leipzig — Bürgerbüro Otto-Schill-Straße","url":"https://www.leipzig.de/service-portal/dienststelle/buergeramt-stadthaus-10007011"},{"title":"Stadt Leipzig — Appointment booking (Terminvereinbarung)","url":"https://terminvereinbarung.leipzig.de"},{"title":"Federal Registration Act § 17 — Registering and deregistering","url":"https://www.gesetze-im-internet.de/bmg/__17.html"}]}$seed$::jsonb, 30) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'enrol-at-university', $seed${"slug":"enrol-at-university","title":{"en":"Enrol at university","ne":"विश्वविद्यालयमा भर्ना हुनुहोस्","hi":"विश्वविद्यालय में दाख़िला लें"},"term":{"term":"Immatrikulation"},"stage":"first30","city":"leipzig","readingMinutes":5,"lastVerified":"2026-11-05","summary":{"what":{"en":"Becoming a registered student. You need the enrolment certificate for your residence permit, your health insurance and your semester ticket.","ne":"दर्ता भएको विद्यार्थी बन्नु। आवास अनुमतिपत्र, स्वास्थ्य बीमा र सेमेस्टर टिकटका लागि भर्ना प्रमाणपत्र चाहिन्छ।","hi":"पंजीकृत छात्र बनना। निवास परमिट, स्वास्थ्य बीमा और सेमेस्टर टिकट के लिए दाख़िला प्रमाणपत्र चाहिए।"},"when":{"en":"After you accept your admission — by the date in your admission letter.","ne":"भर्ना स्वीकार गरेपछि — भर्ना पत्रमा लेखिएको मितिसम्म।","hi":"प्रवेश स्वीकार करने के बाद — प्रवेश पत्र में लिखी तारीख तक।"},"deadline":{"en":"Date in your admission letter","ne":"भर्ना पत्रमा लेखिएको मिति","hi":"प्रवेश पत्र में लिखी तारीख"}},"steps":[{"title":{"en":"Get your health insurance reported","ne":"स्वास्थ्य बीमाको सूचना पठाउन लगाउनुहोस्","hi":"स्वास्थ्य बीमा की सूचना भिजवाएं"},"body":{"en":"Your German health insurance fund reports your insurance to the university electronically. Ask your fund to send the report to Leipzig University.","ne":"तपाईंको जर्मन स्वास्थ्य बीमा कोषले विश्वविद्यालयलाई इलेक्ट्रोनिक रूपमा बीमाको सूचना पठाउँछ। लाइपजिग विश्वविद्यालयमा सूचना पठाउन आफ्नो कोषलाई भन्नुहोस्।","hi":"आपका जर्मन स्वास्थ्य बीमा कोष विश्वविद्यालय को इलेक्ट्रॉनिक रूप से बीमा की सूचना भेजता है। अपने कोष से लाइपज़िग विश्वविद्यालय को सूचना भेजने को कहें।"}},{"title":{"en":"Pay the semester fee","ne":"सेमेस्टर शुल्क तिर्नुहोस्","hi":"सेमेस्टर फ़ीस भरें"},"body":{"en":"At Leipzig University the fee is €332.30 for the winter semester 2026/27. It includes the Deutschland-Semesterticket (€226.80) and the Studentenwerk fee. There is no tuition fee for most programmes.","ne":"लाइपजिग विश्वविद्यालयमा २०२६/२७ जाडो सेमेस्टरका लागि शुल्क €३३२.३० छ। यसमा Deutschland-Semesterticket (€२२६.८०) र Studentenwerk शुल्क समावेश छ। धेरैजसो कार्यक्रममा ट्युसन शुल्क छैन।","hi":"लाइपज़िग विश्वविद्यालय में शीतकालीन सेमेस्टर 2026/27 की फ़ीस €332.30 है। इसमें Deutschland-Semesterticket (€226.80) और Studentenwerk फ़ीस शामिल है। ज़्यादातर कोर्स में ट्यूशन फ़ीस नहीं है।"},"term":{"term":"Semesterbeitrag"},"cost":{"en":"€332.30 per semester","ne":"प्रति सेमेस्टर €३३२.३०","hi":"प्रति सेमेस्टर €332.30"}},{"title":{"en":"Complete enrolment","ne":"भर्ना पूरा गर्नुहोस्","hi":"दाख़िला पूरा करें"},"body":{"en":"Follow the steps in your admission letter and the university portal. You then download your enrolment certificate and get your student card.","ne":"भर्ना पत्र र विश्वविद्यालय पोर्टलमा दिइएका चरण पालना गर्नुहोस्। त्यसपछि भर्ना प्रमाणपत्र डाउनलोड गर्नुहुन्छ र विद्यार्थी कार्ड पाउनुहुन्छ।","hi":"प्रवेश पत्र और विश्वविद्यालय पोर्टल में दिए चरणों का पालन करें। फिर आप दाख़िला प्रमाणपत्र डाउनलोड करते हैं और छात्र कार्ड पाते हैं।"},"term":{"term":"Immatrikulationsbescheinigung"}},{"title":{"en":"Activate your semester ticket","ne":"सेमेस्टर टिकट सक्रिय गर्नुहोस्","hi":"सेमेस्टर टिकट सक्रिय करें"},"body":{"en":"Activate the Deutschland-Semesterticket in the LeipzigMOVE app each semester. It is valid on local and regional transport across Germany.","ne":"हरेक सेमेस्टर LeipzigMOVE एपमा Deutschland-Semesterticket सक्रिय गर्नुहोस्। यो जर्मनीभरका स्थानीय र क्षेत्रीय यातायातमा चल्छ।","hi":"हर सेमेस्टर LeipzigMOVE ऐप में Deutschland-Semesterticket सक्रिय करें। यह पूरे जर्मनी में स्थानीय और क्षेत्रीय परिवहन में मान्य है।"}},{"title":{"en":"Re-register every semester","ne":"हरेक सेमेस्टर पुनः दर्ता गर्नुहोस्","hi":"हर सेमेस्टर फिर से पंजीकरण करें"},"body":{"en":"You stay enrolled by paying the next semester fee in the re-registration period. If you miss it, you can be removed from the university.","ne":"पुनः दर्ता अवधिमा अर्को सेमेस्टरको शुल्क तिरेर भर्ना कायम रहन्छ। छुटाउनुभयो भने विश्वविद्यालयबाट हटाइन सक्नुहुन्छ।","hi":"दोबारा पंजीकरण की अवधि में अगले सेमेस्टर की फ़ीस भरकर आपका दाख़िला बना रहता है। चूक गए तो विश्वविद्यालय से नाम कट सकता है।"},"term":{"term":"Rückmeldung"}}],"documents":[{"en":"Admission letter","ne":"भर्ना पत्र","hi":"प्रवेश पत्र"},{"en":"Passport with visa","ne":"भिसासहितको राहदानी","hi":"वीज़ा सहित पासपोर्ट"},{"en":"Health insurance (reported electronically)","ne":"स्वास्थ्य बीमा (इलेक्ट्रोनिक सूचना)","hi":"स्वास्थ्य बीमा (इलेक्ट्रॉनिक सूचना)"},{"en":"Proof of paying the semester fee","ne":"सेमेस्टर शुल्क तिरेको प्रमाण","hi":"सेमेस्टर फ़ीस भरने का सबूत"}],"callouts":[{"kind":"tip","text":{"en":"Not at Leipzig University? Other universities in Leipzig (e.g. HTWK) have their own fees and steps — check your admission letter.","ne":"लाइपजिग विश्वविद्यालयमा हुनुहुन्न? लाइपजिगका अन्य विश्वविद्यालय (जस्तै HTWK) को आफ्नै शुल्क र प्रक्रिया छ — भर्ना पत्र हेर्नुहोस्।","hi":"लाइपज़िग विश्वविद्यालय में नहीं हैं? लाइपज़िग के दूसरे विश्वविद्यालयों (जैसे HTWK) की अपनी फ़ीस और प्रक्रिया है — प्रवेश पत्र देखें।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Activate your health insurance","ne":"स्वास्थ्य बीमा सक्रिय गर्नुहोस्","hi":"स्वास्थ्य बीमा सक्रिय करें"},"href":"/guides/activate-health-insurance"},{"kind":"guide","title":{"en":"Book your residence-permit appointment","ne":"आवास अनुमतिपत्रको अपोइन्टमेन्ट बुक गर्नुहोस्","hi":"निवास परमिट की अपॉइंटमेंट बुक करें"},"href":"/guides/book-residence-permit-appointment"}],"sources":[{"title":"Leipzig University — Re-enrolment and semester fee","url":"https://www.uni-leipzig.de/en/studying/current-students/study-affairs/re-enrolment-and-semester-fee"},{"title":"Leipzig University — Overview of semester fees (PDF)","url":"https://www.uni-leipzig.de/fileadmin/ul/Dokumente/260413_StudSek_%C3%9Cbersicht_Semesterbeitr%C3%A4ge.pdf"},{"title":"Leipzig University — Starting your studies and living in Leipzig","url":"https://www.uni-leipzig.de/international/studieren-an-der-universitaet-leipzig/studienstart-und-leben-in-leipzig"},{"title":"Leipzig University — Health insurance guide for international students (PDF)","url":"https://www.uni-leipzig.de/fileadmin/ul/Dokumente/230222_SI_Ratgeber_Krankenversicherung_en.pdf"},{"title":"Studentenwerk Leipzig — Price increase for the semester ticket (PDF)","url":"https://www.studentenwerk-leipzig.de/ext/uploads/2026/02/26-02-12-Preiserhoehung-fuer-Deutschland-Semesterticket-und-Co.-%E2%80%93-studentische-Mobilitaet-in-Leipzig-wird-teurer.pdf"}]}$seed$::jsonb, 40) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'book-residence-permit-appointment', $seed${"slug":"book-residence-permit-appointment","title":{"en":"Apply for your residence permit","ne":"आवास अनुमतिपत्रका लागि आवेदन दिनुहोस्","hi":"निवास परमिट के लिए आवेदन करें"},"term":{"term":"Aufenthaltserlaubnis"},"stage":"first30","city":"leipzig","readingMinutes":7,"lastVerified":"2026-11-05","updatedRecently":true,"summary":{"what":{"en":"Your visa is only for the start. In Leipzig you apply online to the foreigners’ office for a residence permit for your studies.","ne":"तपाईंको भिसा सुरुका लागि मात्र हो। लाइपजिगमा पढाइका लागि आवास अनुमतिपत्र विदेशी कार्यालयमा अनलाइन आवेदन दिनुहुन्छ।","hi":"आपका वीज़ा केवल शुरुआत के लिए है। लाइपज़िग में पढ़ाई के निवास परमिट के लिए आप विदेशी कार्यालय में ऑनलाइन आवेदन करते हैं।"},"when":{"en":"As soon as you are registered and enrolled — at the latest before your visa ends.","ne":"ठेगाना दर्ता र भर्ना भएपछि तुरुन्तै — बढीमा भिसाको म्याद सकिनुअघि।","hi":"पता पंजीकरण और दाख़िले के तुरंत बाद — ज़्यादा से ज़्यादा वीज़ा ख़त्म होने से पहले।"},"deadline":{"en":"Before your visa ends","ne":"भिसाको म्याद सकिनुअघि","hi":"वीज़ा ख़त्म होने से पहले"}},"steps":[{"title":{"en":"Collect your documents as PDFs","ne":"कागजातहरू PDF मा तयार गर्नुहोस्","hi":"दस्तावेज़ PDF में तैयार करें"},"body":{"en":"You upload everything in the online application. Scan each document clearly — you also need the signed “Belehrung” form from the city’s website.","ne":"तपाईं अनलाइन आवेदनमा सबै अपलोड गर्नुहुन्छ। हरेक कागजात स्पष्ट स्क्यान गर्नुहोस् — सहरको वेबसाइटबाट हस्ताक्षर गरिएको “Belehrung” फारम पनि चाहिन्छ।","hi":"आप ऑनलाइन आवेदन में सब कुछ अपलोड करते हैं। हर दस्तावेज़ साफ़ स्कैन करें — शहर की वेबसाइट से हस्ताक्षरित “Belehrung” फ़ॉर्म भी चाहिए।"}},{"title":{"en":"Apply online","ne":"अनलाइन आवेदन दिनुहोस्","hi":"ऑनलाइन आवेदन करें"},"body":{"en":"Leipzig handles residence permits for studies fully online. You don’t book an appointment first — you send the online application.","ne":"लाइपजिगले पढाइका लागि आवास अनुमतिपत्र पूर्ण रूपमा अनलाइन प्रक्रिया गर्छ। पहिले अपोइन्टमेन्ट बुक गर्नु पर्दैन — अनलाइन आवेदन पठाउनुहुन्छ।","hi":"लाइपज़िग पढ़ाई के निवास परमिट की प्रक्रिया पूरी तरह ऑनलाइन करता है। पहले अपॉइंटमेंट बुक नहीं करना होता — आप ऑनलाइन आवेदन भेजते हैं।"},"where":{"en":"Ausländerbehörde Leipzig, Technisches Rathaus, Prager Straße 126–128, 04317 Leipzig","ne":"Ausländerbehörde Leipzig, Technisches Rathaus, Prager Straße 126–128, 04317 Leipzig","hi":"Ausländerbehörde Leipzig, Technisches Rathaus, Prager Straße 126–128, 04317 Leipzig"}},{"title":{"en":"Wait for the email invitation","ne":"इमेल निमन्त्रणा पर्खनुहोस्","hi":"ईमेल निमंत्रण का इंतज़ार करें"},"body":{"en":"When your application is checked, the office invites you by email to give your fingerprints and photo. Until the permit is ready you can get a certificate that lets you stay (Fiktionsbescheinigung).","ne":"आवेदन जाँचेपछि कार्यालयले औंठाछाप र फोटोका लागि इमेलबाट बोलाउँछ। अनुमतिपत्र तयार नहुँदासम्म बस्न दिने प्रमाणपत्र (Fiktionsbescheinigung) पाउन सक्नुहुन्छ।","hi":"आवेदन जांचने के बाद कार्यालय उंगलियों के निशान और फ़ोटो के लिए ईमेल से बुलाता है। परमिट तैयार होने तक आपको रहने की अनुमति देने वाला प्रमाणपत्र (Fiktionsbescheinigung) मिल सकता है।"},"term":{"term":"Fiktionsbescheinigung"},"wait":{"en":"About 4–6 weeks until the invitation","ne":"निमन्त्रणासम्म करिब ४–६ हप्ता","hi":"निमंत्रण तक लगभग 4–6 हफ़्ते"}},{"title":{"en":"Pay and collect your card","ne":"शुल्क तिर्नुहोस् र कार्ड लिनुहोस्","hi":"फ़ीस भरें और कार्ड लें"},"body":{"en":"The permit is an electronic card (eAT). It is produced in Berlin and takes a few more weeks. You collect it in person.","ne":"अनुमतिपत्र इलेक्ट्रोनिक कार्ड (eAT) हो। यो बर्लिनमा बनाइन्छ र थप केही हप्ता लाग्छ। तपाईं आफैं गएर लिनुहुन्छ।","hi":"परमिट एक इलेक्ट्रॉनिक कार्ड (eAT) है। यह बर्लिन में बनता है और कुछ और हफ़्ते लगते हैं। आप इसे ख़ुद जाकर लेते हैं।"},"term":{"term":"elektronischer Aufenthaltstitel"},"cost":{"en":"€100 (waived with a public scholarship)","ne":"€१०० (सरकारी छात्रवृत्ति भए छुट)","hi":"€100 (सरकारी छात्रवृत्ति पर माफ़)"}}],"documents":[{"en":"Passport and visa (copy)","ne":"राहदानी र भिसा (प्रतिलिपि)","hi":"पासपोर्ट और वीज़ा (कॉपी)"},{"en":"Rental contract","ne":"भाडा सम्झौता","hi":"किराया अनुबंध"},{"en":"Proof of health insurance","ne":"स्वास्थ्य बीमाको प्रमाण","hi":"स्वास्थ्य बीमा का सबूत"},{"en":"Enrolment certificate","ne":"भर्ना प्रमाणपत्र","hi":"दाख़िला प्रमाणपत्र"},{"en":"Proof of money: €992 a month (e.g. blocked account)","ne":"पैसाको प्रमाण: महिनामा €९९२ (जस्तै ब्लक्ड खाता)","hi":"पैसे का सबूत: हर महीने €992 (जैसे ब्लॉक्ड अकाउंट)"},{"en":"Signed “Belehrung” form","ne":"हस्ताक्षर गरिएको “Belehrung” फारम","hi":"हस्ताक्षरित “Belehrung” फ़ॉर्म"}],"callouts":[{"kind":"warning","text":{"en":"Apply before your visa ends. If you apply in time, you may stay while the office decides.","ne":"भिसाको म्याद सकिनुअघि आवेदन दिनुहोस्। समयमै आवेदन दिनुभयो भने कार्यालयले निर्णय नगरुन्जेल बस्न पाउनुहुन्छ।","hi":"वीज़ा ख़त्म होने से पहले आवेदन करें। समय पर आवेदन करने पर कार्यालय के फ़ैसले तक आप रह सकते हैं।"}},{"kind":"tip","text":{"en":"Questions? The foreigners’ office phone is 0341 123-3310. The Welcome Centre at Otto-Schill-Straße 2 also helps for free.","ne":"प्रश्न छन्? विदेशी कार्यालयको फोन ०३४१ १२३-३३१० हो। Otto-Schill-Straße 2 को Welcome Centre ले पनि निःशुल्क सहयोग गर्छ।","hi":"सवाल हैं? विदेशी कार्यालय का फ़ोन 0341 123-3310 है। Otto-Schill-Straße 2 का Welcome Centre भी मुफ़्त मदद करता है।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Register your address","ne":"आफ्नो ठेगाना दर्ता गर्नुहोस्","hi":"अपना पता पंजीकृत करें"},"href":"/guides/register-your-address"},{"kind":"guide","title":{"en":"Extend your residence permit","ne":"आवास अनुमतिपत्र नवीकरण गर्नुहोस्","hi":"निवास परमिट बढ़वाएं"},"href":"/guides/extend-your-residence-permit"}],"actions":[{"label":{"en":"Apply online","ne":"अनलाइन आवेदन दिनुहोस्","hi":"ऑनलाइन आवेदन करें"},"url":"https://www.leipzig.de/service-portal/formulare/onlineantrag-aufenthalt-zu-ausbildung-studium-berufsanerkennung"}],"sources":[{"title":"Stadt Leipzig — Aufenthaltserlaubnis zum Studium beantragen","url":"https://www.leipzig.de/service-portal/dienstleistung/aufenthaltserlaubnis-zum-studium-beantragen-5f1ae6c5debf6"},{"title":"City of Leipzig — Residence permit for a study course","url":"https://english.leipzig.de/youth-family-and-community/foreign-nationals-and-migrants/foreigners-authority/residence-for-training-and-study-purposes/residence-permit-for-a-study-course"},{"title":"Stadt Leipzig — Online application: residence for study and training","url":"https://www.leipzig.de/service-portal/formulare/onlineantrag-aufenthalt-zu-ausbildung-studium-berufsanerkennung"},{"title":"City of Leipzig — Foreigners’ Authority","url":"https://english.leipzig.de/youth-family-and-community/foreign-nationals-and-migrants/foreigners-authority"}]}$seed$::jsonb, 50) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'activate-health-insurance', $seed${"slug":"activate-health-insurance","title":{"en":"Activate your health insurance","ne":"स्वास्थ्य बीमा सक्रिय गर्नुहोस्","hi":"स्वास्थ्य बीमा सक्रिय करें"},"term":{"term":"Gesundheitskarte"},"stage":"first30","readingMinutes":4,"lastVerified":"2026-11-05","summary":{"what":{"en":"Finishing your membership with the German health insurance fund, so you get your health card and can see a doctor.","ne":"जर्मन स्वास्थ्य बीमा कोषमा सदस्यता पूरा गर्नु, ताकि स्वास्थ्य कार्ड पाउनुहोस् र डाक्टरकहाँ जान सक्नुहोस्।","hi":"जर्मन स्वास्थ्य बीमा कोष में सदस्यता पूरी करना, ताकि आपको हेल्थ कार्ड मिले और आप डॉक्टर के पास जा सकें।"},"when":{"en":"In your first days, before enrolment.","ne":"सुरुका दिनमै, भर्ना हुनुअघि।","hi":"शुरुआती दिनों में, दाख़िले से पहले।"},"deadline":{"en":"Before enrolment","ne":"भर्ना हुनुअघि","hi":"दाख़िले से पहले"}},"steps":[{"title":{"en":"Send your German address and enrolment details","ne":"जर्मन ठेगाना र भर्ना विवरण पठाउनुहोस्","hi":"जर्मन पता और दाख़िले का विवरण भेजें"},"body":{"en":"Give your fund your new address, your university and your bank account for the monthly payment.","ne":"कोषलाई नयाँ ठेगाना, विश्वविद्यालय र मासिक भुक्तानीका लागि बैंक खाता दिनुहोस्।","hi":"कोष को अपना नया पता, विश्वविद्यालय और मासिक भुगतान के लिए बैंक खाता दें।"}},{"title":{"en":"Upload a photo for your health card","ne":"स्वास्थ्य कार्डका लागि फोटो अपलोड गर्नुहोस्","hi":"हेल्थ कार्ड के लिए फ़ोटो अपलोड करें"},"body":{"en":"The card arrives by post. Show it at every doctor’s visit. Until it arrives, ask your fund for a confirmation you can show.","ne":"कार्ड हुलाकबाट आउँछ। हरेक पटक डाक्टरकहाँ देखाउनुहोस्। कार्ड नआउँदासम्म देखाउन मिल्ने पुष्टि-पत्र कोषसँग माग्नुहोस्।","hi":"कार्ड डाक से आता है। हर बार डॉक्टर के पास इसे दिखाएं। कार्ड आने तक दिखाने लायक पुष्टि-पत्र अपने कोष से मांगें।"},"term":{"term":"elektronische Gesundheitskarte"}},{"title":{"en":"Make sure the fund reports you to the university","ne":"कोषले विश्वविद्यालयलाई सूचना पठाएको सुनिश्चित गर्नुहोस्","hi":"सुनिश्चित करें कि कोष विश्वविद्यालय को सूचना भेजे"},"body":{"en":"Universities receive insurance confirmations electronically. Without it you can’t enrol or re-register.","ne":"विश्वविद्यालयले बीमाको पुष्टि इलेक्ट्रोनिक रूपमा पाउँछ। यो बिना भर्ना वा पुनः दर्ता हुन सक्दैन।","hi":"विश्वविद्यालय को बीमा की पुष्टि इलेक्ट्रॉनिक रूप से मिलती है। इसके बिना दाख़िला या दोबारा पंजीकरण नहीं हो सकता।"}}],"documents":[{"en":"Passport","ne":"राहदानी","hi":"पासपोर्ट"},{"en":"Registration certificate or rental contract","ne":"दर्ता प्रमाणपत्र वा भाडा सम्झौता","hi":"पंजीकरण प्रमाणपत्र या किराया अनुबंध"},{"en":"Admission letter","ne":"भर्ना पत्र","hi":"प्रवेश पत्र"},{"en":"Photo","ne":"फोटो","hi":"फ़ोटो"}],"callouts":[{"kind":"tip","text":{"en":"Turning 30 or finishing your studies changes your rate. Tell your fund in time.","ne":"३० वर्ष पुग्दा वा पढाइ सकिँदा तपाईंको दर बदलिन्छ। समयमै कोषलाई जानकारी दिनुहोस्।","hi":"30 साल के होने या पढ़ाई ख़त्म होने पर आपकी दर बदलती है। समय पर कोष को बताएं।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Find a family doctor","ne":"पारिवारिक डाक्टर खोज्नुहोस्","hi":"फ़ैमिली डॉक्टर खोजें"},"href":"/guides/find-a-family-doctor"},{"kind":"guide","title":{"en":"Get health insurance","ne":"स्वास्थ्य बीमा लिनुहोस्","hi":"स्वास्थ्य बीमा लें"},"href":"/guides/get-health-insurance"}],"sources":[{"title":"Leipzig University — Health insurance guide for international students (PDF)","url":"https://www.uni-leipzig.de/fileadmin/ul/Dokumente/230222_SI_Ratgeber_Krankenversicherung_en.pdf"},{"title":"Techniker Krankenkasse — Contribution for students","url":"https://www.tk.de/techniker/versicherung/gut-versichert-in-jeder-lebenslage/versichert-als-studierende/krankenversicherung-und-studium/beitrag-studierende-2131472"},{"title":"GKV-Spitzenverband — Contribution figures 2026 (PDF)","url":"https://www.gkv-spitzenverband.de/media/dokumente/presse/zahlen_und_grafiken/20260101_Faktenblatt_Rechengroessen_Beitragsrecht.pdf"}]}$seed$::jsonb, 60) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'find-housing-leipzig', $seed${"slug":"find-housing-leipzig","title":{"en":"Find a room in Leipzig","ne":"लाइपजिगमा कोठा खोज्नुहोस्","hi":"लाइपज़िग में कमरा खोजें"},"term":{"term":"Wohnungssuche"},"stage":"before","city":"leipzig","readingMinutes":6,"lastVerified":"2026-11-05","summary":{"what":{"en":"Options are a Studentenwerk dorm, a shared flat (WG) or your own flat. Leipzig is cheaper than most German cities, but good rooms go fast.","ne":"विकल्पहरू: Studentenwerk छात्रावास, साझा फ्ल्याट (WG) वा आफ्नै फ्ल्याट। लाइपजिग धेरैजसो जर्मन सहरभन्दा सस्तो छ, तर राम्रा कोठा छिटै सकिन्छन्।","hi":"विकल्प हैं: Studentenwerk हॉस्टल, साझा फ़्लैट (WG) या अपना फ़्लैट। लाइपज़िग ज़्यादातर जर्मन शहरों से सस्ता है, लेकिन अच्छे कमरे जल्दी चले जाते हैं।"},"when":{"en":"Start as soon as you have your admission.","ne":"भर्ना पाउनेबित्तिकै सुरु गर्नुहोस्।","hi":"प्रवेश मिलते ही शुरू करें।"},"deadline":{"en":"Before you travel","ne":"यात्रा गर्नुअघि","hi":"यात्रा से पहले"}},"steps":[{"title":{"en":"Apply for a Studentenwerk dorm","ne":"Studentenwerk छात्रावासका लागि आवेदन दिनुहोस्","hi":"Studentenwerk हॉस्टल के लिए आवेदन करें"},"body":{"en":"Apply online. Rents are all-inclusive: about €215–325 for a room in a shared flat and €295–435 for a single apartment. The deposit is €450.","ne":"अनलाइन आवेदन दिनुहोस्। भाडामा सबै समावेश हुन्छ: साझा फ्ल्याटको कोठा करिब €२१५–३२५ र एकल अपार्टमेन्ट €२९५–४३५। धरौटी €४५० हो।","hi":"ऑनलाइन आवेदन करें। किराए में सब कुछ शामिल है: साझा फ़्लैट का कमरा लगभग €215–325 और अकेले का अपार्टमेंट €295–435। जमानत राशि €450 है।"},"cost":{"en":"€215–435 a month · deposit €450","ne":"महिनामा €२१५–४३५ · धरौटी €४५०","hi":"हर महीने €215–435 · जमानत €450"},"term":{"term":"Wohnheim"}},{"title":{"en":"Look for a shared flat","ne":"साझा फ्ल्याट खोज्नुहोस्","hi":"साझा फ़्लैट खोजें"},"body":{"en":"Most students live in a WG. Compare the “warm rent” (with heating and service charges). Leipzig’s average asking rent for new contracts was about €9.26 per m² (2024, before heating).","ne":"धेरैजसो विद्यार्थी WG मा बस्छन्। “वार्म भाडा” (तताउने र सेवा शुल्कसहित) तुलना गर्नुहोस्। नयाँ सम्झौताको लागि लाइपजिगको औसत माग गरिएको भाडा करिब €९.२६ प्रति वर्गमिटर (२०२४, तताउने बाहेक) थियो।","hi":"ज़्यादातर छात्र WG में रहते हैं। “वार्म किराया” (हीटिंग और सेवा शुल्क सहित) की तुलना करें। नए अनुबंधों के लिए लाइपज़िग का औसत मांगा गया किराया लगभग €9.26 प्रति वर्ग मीटर (2024, हीटिंग के बिना) था।"},"term":{"term":"Wohngemeinschaft (WG)"}},{"title":{"en":"View the room and read the contract","ne":"कोठा हेर्नुहोस् र सम्झौता पढ्नुहोस्","hi":"कमरा देखें और अनुबंध पढ़ें"},"body":{"en":"Pay nothing before you have seen the room (in person or by live video) and signed a contract. The deposit may be at most three months’ cold rent and you may pay it in three instalments.","ne":"कोठा हेर्नु (आफैं वा प्रत्यक्ष भिडियोमार्फत) र सम्झौतामा हस्ताक्षर गर्नुअघि केही नतिर्नुहोस्। धरौटी बढीमा तीन महिनाको कोल्ड भाडा हुन सक्छ र तीन किस्तामा तिर्न पाइन्छ।","hi":"कमरा देखने (ख़ुद या लाइव वीडियो से) और अनुबंध पर हस्ताक्षर से पहले कुछ भी न भरें। जमानत ज़्यादा से ज़्यादा तीन महीने का कोल्ड किराया हो सकती है और आप इसे तीन किस्तों में दे सकते हैं।"},"term":{"term":"Mietvertrag"}},{"title":{"en":"Get the landlord’s confirmation","ne":"घरधनीको पुष्टि-पत्र लिनुहोस्","hi":"मकान मालिक का पुष्टि-पत्र लें"},"body":{"en":"When you move in, ask for the Wohnungsgeberbestätigung — you need it to register your address within 2 weeks.","ne":"सर्दा Wohnungsgeberbestätigung माग्नुहोस् — २ हप्ताभित्र ठेगाना दर्ता गर्न यो चाहिन्छ।","hi":"शिफ़्ट होते समय Wohnungsgeberbestätigung मांगें — 2 हफ़्ते में पता पंजीकृत करने के लिए यह चाहिए।"}}],"documents":[{"en":"Passport","ne":"राहदानी","hi":"पासपोर्ट"},{"en":"Admission letter or enrolment certificate","ne":"भर्ना पत्र वा भर्ना प्रमाणपत्र","hi":"प्रवेश पत्र या दाख़िला प्रमाणपत्र"},{"en":"Proof of money (e.g. blocked account)","ne":"पैसाको प्रमाण (जस्तै ब्लक्ड खाता)","hi":"पैसे का सबूत (जैसे ब्लॉक्ड अकाउंट)"}],"callouts":[{"kind":"warning","text":{"en":"A “landlord abroad” who wants money before a viewing is a common scam. If you have paid, ask your bank to recall the transfer right away and report it to the police.","ne":"हेर्नुअघि पैसा माग्ने “विदेशमा रहेको घरधनी” सामान्य ठगी हो। तिरिसक्नुभएको छ भने तुरुन्तै बैंकलाई ट्रान्सफर फिर्ता गर्न भन्नुहोस् र प्रहरीलाई खबर गर्नुहोस्।","hi":"देखने से पहले पैसा मांगने वाला “विदेश में रहने वाला मकान मालिक” आम धोखा है। अगर भुगतान कर दिया है, तो तुरंत बैंक से ट्रांसफ़र वापस मंगाने को कहें और पुलिस में शिकायत करें।"}},{"kind":"tip","text":{"en":"Problems with your landlord? The Mieterverein Leipzig checks contracts and bills for members (€84 a year).","ne":"घरधनीसँग समस्या? Mieterverein Leipzig ले सदस्यका लागि सम्झौता र बिल जाँच्छ (वर्षको €८४)।","hi":"मकान मालिक से समस्या? Mieterverein Leipzig सदस्यों के लिए अनुबंध और बिल जांचता है (साल के €84)।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Register your address","ne":"आफ्नो ठेगाना दर्ता गर्नुहोस्","hi":"अपना पता पंजीकृत करें"},"href":"/guides/register-your-address"},{"kind":"tool","title":{"en":"Plan your monthly budget","ne":"मासिक बजेट योजना बनाउनुहोस्","hi":"मासिक बजट की योजना बनाएं"},"href":"/tools/budget"}],"actions":[{"label":{"en":"Apply for a dorm room","ne":"छात्रावासका लागि आवेदन दिनुहोस्","hi":"हॉस्टल के लिए आवेदन करें"},"url":"https://www.studentenwerk-leipzig.de/en/housing/dormitory-application/"}],"sources":[{"title":"Studentenwerk Leipzig — Information for new applicants (housing)","url":"https://www.studentenwerk-leipzig.de/en/housing/information-new-applicants/"},{"title":"Studentenwerk Leipzig — Questions & answers about student housing","url":"https://www.studentenwerk-leipzig.de/en/housing/questions-answers/"},{"title":"Studentenwerk Leipzig — Dormitory application","url":"https://www.studentenwerk-leipzig.de/en/housing/dormitory-application/"},{"title":"Stadt Leipzig — Monitoringbericht Wohnen 2025","url":"https://www.leipzig.de/newsarchiv/news/monitoringbericht-wohnen-2025-nachfrage-waechst-neubau-nimmt-zu"},{"title":"German Civil Code § 551 — Rent deposit","url":"https://www.gesetze-im-internet.de/bgb/__551.html"},{"title":"Verbraucherzentrale — Spotting fake flat listings","url":"https://www.verbraucherzentrale.de/wissen/vertraege-reklamation/abzocke/fakewohnungen-im-internet-so-erkennen-sie-falsche-immobilienanzeigen-27576"},{"title":"Polizei — Advance-payment fraud online","url":"https://www.polizei-beratung.de/themen-und-tipps/sicher-handeln/onlinebetrug-maschen/vorkassebetrug/"}]}$seed$::jsonb, 70) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'open-a-bank-account', $seed${"slug":"open-a-bank-account","title":{"en":"Open a bank account","ne":"बैंक खाता खोल्नुहोस्","hi":"बैंक खाता खोलें"},"term":{"term":"Girokonto"},"stage":"first30","readingMinutes":5,"lastVerified":"2026-11-05","summary":{"what":{"en":"A normal current account for rent, salary and payments. Your blocked account pays your monthly money into it.","ne":"भाडा, तलब र भुक्तानीका लागि सामान्य चल्ती खाता। ब्लक्ड खाताले मासिक पैसा यसैमा पठाउँछ।","hi":"किराया, वेतन और भुगतान के लिए एक सामान्य चालू खाता। आपका ब्लॉक्ड अकाउंट हर महीने का पैसा इसी में भेजता है।"},"when":{"en":"In your first weeks, ideally right after registering your address.","ne":"पहिलो हप्ताहरूमा, सम्भव भए ठेगाना दर्तापछि तुरुन्तै।","hi":"पहले हफ़्तों में, हो सके तो पता पंजीकरण के तुरंत बाद।"},"deadline":{"en":"Before your first rent payment","ne":"पहिलो भाडा तिर्नुअघि","hi":"पहला किराया देने से पहले"}},"steps":[{"title":{"en":"Decide: branch bank or online bank","ne":"शाखा बैंक कि अनलाइन बैंक, निर्णय गर्नुहोस्","hi":"तय करें: शाखा बैंक या ऑनलाइन बैंक"},"body":{"en":"A branch bank such as Sparkasse Leipzig offers advice in person and free student accounts up to age 26. Online banks such as N26 or ING are opened in an app, often in English.","ne":"Sparkasse Leipzig जस्ता शाखा बैंकले आमनेसामने सल्लाह र २६ वर्षसम्म निःशुल्क विद्यार्थी खाता दिन्छ। N26 वा ING जस्ता अनलाइन बैंक एपमै खोलिन्छ, प्रायः अंग्रेजीमा।","hi":"Sparkasse Leipzig जैसा शाखा बैंक आमने-सामने सलाह और 26 साल तक मुफ़्त छात्र खाता देता है। N26 या ING जैसे ऑनलाइन बैंक ऐप में खुलते हैं, अक्सर अंग्रेज़ी में।"}},{"title":{"en":"Compare the real costs","ne":"वास्तविक खर्च तुलना गर्नुहोस्","hi":"असली ख़र्च की तुलना करें"},"body":{"en":"Look at the monthly fee after the student period, cash withdrawals and card fees. ING, for example, is free under 28 or with €1,000 incoming a month, otherwise €4.90.","ne":"विद्यार्थी अवधिपछिको मासिक शुल्क, नगद झिक्ने र कार्ड शुल्क हेर्नुहोस्। जस्तै ING, २८ वर्षमुनि वा महिनामा €१,००० आउने भए निःशुल्क, नत्र €४.९०।","hi":"छात्र अवधि के बाद की मासिक फ़ीस, नकद निकासी और कार्ड फ़ीस देखें। जैसे ING, 28 से कम उम्र या हर महीने €1,000 आने पर मुफ़्त, वरना €4.90।"}},{"title":{"en":"Verify your identity","ne":"आफ्नो पहिचान पुष्टि गर्नुहोस्","hi":"अपनी पहचान सत्यापित करें"},"body":{"en":"At a branch you show your passport. Online banks use a video call. Most banks ask for your German address; many also for the registration certificate.","ne":"शाखामा राहदानी देखाउनुहुन्छ। अनलाइन बैंकले भिडियो कल प्रयोग गर्छ। धेरैजसो बैंकले जर्मन ठेगाना र धेरैले दर्ता प्रमाणपत्र पनि माग्छन्।","hi":"शाखा में आप पासपोर्ट दिखाते हैं। ऑनलाइन बैंक वीडियो कॉल का उपयोग करते हैं। ज़्यादातर बैंक जर्मन पता मांगते हैं; कई पंजीकरण प्रमाणपत्र भी।"},"cost":{"en":"Student accounts: often €0","ne":"विद्यार्थी खाता: प्रायः €०","hi":"छात्र खाते: अक्सर €0"}},{"title":{"en":"Connect it to your blocked account","ne":"ब्लक्ड खातासँग जोड्नुहोस्","hi":"ब्लॉक्ड अकाउंट से जोड़ें"},"body":{"en":"Give your blocked-account provider your new IBAN so the monthly payouts start. Give it to your landlord and employer too.","ne":"मासिक भुक्तानी सुरु होस् भनेर ब्लक्ड खाता प्रदायकलाई नयाँ IBAN दिनुहोस्। घरधनी र रोजगारदातालाई पनि दिनुहोस्।","hi":"हर महीने का भुगतान शुरू हो, इसके लिए ब्लॉक्ड अकाउंट प्रदाता को नया IBAN दें। मकान मालिक और नियोक्ता को भी दें।"}}],"documents":[{"en":"Passport with visa or residence permit","ne":"भिसा वा आवास अनुमतिपत्रसहितको राहदानी","hi":"वीज़ा या निवास परमिट सहित पासपोर्ट"},{"en":"Registration certificate (Meldebescheinigung)","ne":"दर्ता प्रमाणपत्र (Meldebescheinigung)","hi":"पंजीकरण प्रमाणपत्र (Meldebescheinigung)"},{"en":"Enrolment certificate for a student account","ne":"विद्यार्थी खाताका लागि भर्ना प्रमाणपत्र","hi":"छात्र खाते के लिए दाख़िला प्रमाणपत्र"},{"en":"Tax ID (can usually be given later)","ne":"कर आईडी (प्रायः पछि दिन मिल्छ)","hi":"टैक्स आईडी (आमतौर पर बाद में दे सकते हैं)"}],"callouts":[{"kind":"tip","text":{"en":"Every person living legally in the EU has the right to a basic account (Basiskonto). A bank may not refuse it just because you are new or have no credit history.","ne":"EU मा कानुनी रूपमा बस्ने हरेक व्यक्तिलाई आधारभूत खाता (Basiskonto) पाउने अधिकार छ। नयाँ भएको वा क्रेडिट इतिहास नभएको कारणले मात्र बैंकले अस्वीकार गर्न पाउँदैन।","hi":"EU में क़ानूनी रूप से रहने वाले हर व्यक्ति को बेसिक खाते (Basiskonto) का अधिकार है। सिर्फ़ नए होने या क्रेडिट इतिहास न होने पर बैंक मना नहीं कर सकता।"}},{"kind":"mistake","text":{"en":"Check what happens after your student years: some free accounts start charging a monthly fee at 26 or 28.","ne":"विद्यार्थी अवधिपछि के हुन्छ जाँच्नुहोस्: केही निःशुल्क खाताले २६ वा २८ वर्षपछि मासिक शुल्क लिन थाल्छन्।","hi":"छात्र अवधि के बाद क्या होगा, जांचें: कुछ मुफ़्त खाते 26 या 28 की उम्र के बाद मासिक फ़ीस लेने लगते हैं।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"tool","title":{"en":"Compare bank accounts","ne":"बैंक खाताहरू तुलना गर्नुहोस्","hi":"बैंक खातों की तुलना करें"},"href":"/tools/compare/bank-accounts"},{"kind":"guide","title":{"en":"Register your address","ne":"आफ्नो ठेगाना दर्ता गर्नुहोस्","hi":"अपना पता पंजीकृत करें"},"href":"/guides/register-your-address"}],"sources":[{"title":"Sparkasse Leipzig — Offers for students","url":"https://www.sparkasse-leipzig.de/de/home/privatkunden/junge-kunden/studenten.html"},{"title":"N26 — Compare accounts in Germany","url":"https://n26.com/en-de/plans"},{"title":"ING — Conditions for the current account","url":"https://www.ing.de/girokonto/konditionen/"},{"title":"Payment Accounts Act § 31 — Right to a basic account","url":"https://www.gesetze-im-internet.de/zkg/__31.html"}],"compareLink":{"label":{"en":"Compare banks","ne":"बैंकहरू तुलना गर्नुहोस्","hi":"बैंकों की तुलना करें"},"href":"/tools/compare/bank-accounts"}}$seed$::jsonb, 80) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'get-your-tax-id', $seed${"slug":"get-your-tax-id","title":{"en":"Get your tax ID","ne":"आफ्नो कर आईडी लिनुहोस्","hi":"अपनी टैक्स आईडी पाएं"},"term":{"term":"Steuerliche Identifikationsnummer"},"stage":"first30","readingMinutes":3,"lastVerified":"2026-11-05","summary":{"what":{"en":"An 11-digit number for life. Your employer needs it to pay you correctly; banks ask for it too.","ne":"जीवनभरको ११ अङ्कको नम्बर। तपाईंलाई सही तलब दिन रोजगारदातालाई यो चाहिन्छ; बैंकले पनि माग्छ।","hi":"जीवन भर के लिए 11 अंकों का नंबर। आपको सही वेतन देने के लिए नियोक्ता को यह चाहिए; बैंक भी मांगते हैं।"},"when":{"en":"It comes automatically after you register your address.","ne":"ठेगाना दर्ता गरेपछि आफैं आउँछ।","hi":"पता पंजीकृत करने के बाद अपने आप आती है।"},"deadline":{"en":"Before your first job","ne":"पहिलो काम सुरु गर्नुअघि","hi":"पहली नौकरी से पहले"}},"steps":[{"title":{"en":"Register your address","ne":"आफ्नो ठेगाना दर्ता गर्नुहोस्","hi":"अपना पता पंजीकृत करें"},"body":{"en":"You don’t apply for the tax ID. The Federal Central Tax Office (BZSt) sends it by letter after your first registration in Germany.","ne":"कर आईडीका लागि आवेदन दिनु पर्दैन। जर्मनीमा पहिलो पटक दर्ता भएपछि संघीय केन्द्रीय कर कार्यालय (BZSt) ले चिठीबाट पठाउँछ।","hi":"टैक्स आईडी के लिए आवेदन नहीं करना होता। जर्मनी में पहली बार पंजीकरण के बाद संघीय केंद्रीय कर कार्यालय (BZSt) इसे पत्र से भेजता है।"},"wait":{"en":"About 4 weeks","ne":"करिब ४ हप्ता","hi":"लगभग 4 हफ़्ते"}},{"title":{"en":"Put your name on the mailbox","ne":"पत्रपेटिकामा आफ्नो नाम राख्नुहोस्","hi":"लेटरबॉक्स पर अपना नाम लगाएं"},"body":{"en":"Letters without your name on the mailbox often go back. In a shared flat, add your name next to the main tenant’s.","ne":"पत्रपेटिकामा नाम नभए चिठी प्रायः फिर्ता जान्छ। साझा फ्ल्याटमा मुख्य भाडावालको नामछेउ आफ्नो नाम थप्नुहोस्।","hi":"लेटरबॉक्स पर नाम न हो तो पत्र अक्सर वापस चले जाते हैं। साझा फ़्लैट में मुख्य किरायेदार के नाम के साथ अपना नाम जोड़ें।"},"term":{"term":"Briefkasten"}},{"title":{"en":"Nothing came? Request it again","ne":"केही आएन? फेरि माग्नुहोस्","hi":"कुछ नहीं आया? फिर से मांगें"},"body":{"en":"Use the BZSt online form. For data protection, the number is only sent by post to your registered address — never by phone or email.","ne":"BZSt को अनलाइन फारम प्रयोग गर्नुहोस्। तथ्याङ्क सुरक्षाका कारण नम्बर दर्ता भएको ठेगानामा हुलाकबाट मात्र पठाइन्छ — फोन वा इमेलबाट कहिल्यै होइन।","hi":"BZSt का ऑनलाइन फ़ॉर्म इस्तेमाल करें। डेटा सुरक्षा के लिए नंबर केवल आपके पंजीकृत पते पर डाक से भेजा जाता है — फ़ोन या ईमेल से कभी नहीं।"},"cost":{"en":"Free","ne":"निःशुल्क","hi":"मुफ़्त"},"wait":{"en":"About 4 weeks","ne":"करिब ४ हप्ता","hi":"लगभग 4 हफ़्ते"}}],"documents":[{"en":"Registration certificate","ne":"दर्ता प्रमाणपत्र","hi":"पंजीकरण प्रमाणपत्र"}],"callouts":[{"kind":"tip","text":{"en":"Need it urgently for a job? The Bürgerbüro where you registered can often tell you the number when you show your passport.","ne":"कामका लागि तुरुन्तै चाहियो? दर्ता गरेको Bürgerbüro ले राहदानी देखाएपछि प्रायः नम्बर बताउन सक्छ।","hi":"नौकरी के लिए तुरंत चाहिए? जिस Bürgerbüro में पंजीकरण किया था, वह पासपोर्ट दिखाने पर अक्सर नंबर बता सकता है।"}},{"kind":"warning","text":{"en":"Without the tax ID your employer has to deduct more tax. Give it to them as soon as you have it.","ne":"कर आईडी बिना रोजगारदाताले बढी कर काट्नुपर्छ। पाउनेबित्तिकै दिनुहोस्।","hi":"टैक्स आईडी के बिना नियोक्ता को ज़्यादा टैक्स काटना पड़ता है। मिलते ही उन्हें दें।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Student jobs and work limits","ne":"विद्यार्थी काम र कामको सीमा","hi":"छात्र नौकरियां और काम की सीमा"},"href":"/guides/student-jobs"},{"kind":"guide","title":{"en":"File your tax return","ne":"कर विवरण बुझाउनुहोस्","hi":"टैक्स रिटर्न भरें"},"href":"/guides/file-tax-return"}],"actions":[{"label":{"en":"Request your tax ID again","ne":"कर आईडी फेरि माग्नुहोस्","hi":"टैक्स आईडी दोबारा मांगें"},"url":"https://www.bzst.de/SiteGlobals/Kontaktformulare/DE/IdNr/Mitteilung_IdNr/mitteilung_IdNr_node.html"}],"sources":[{"title":"Federal Central Tax Office (BZSt) — Tax identification number","url":"https://www.bzst.de/DE/Privatpersonen/SteuerlicheIdentifikationsnummer/steuerlicheidentifikationsnummer_node.html"},{"title":"BZSt — Questions and answers on the tax ID","url":"https://www.bzst.de/DE/Privatpersonen/SteuerlicheIdentifikationsnummer/FAQ/faq_node.html"},{"title":"BZSt — Request your tax ID again (online form)","url":"https://www.bzst.de/SiteGlobals/Kontaktformulare/DE/IdNr/Mitteilung_IdNr/mitteilung_IdNr_node.html"}]}$seed$::jsonb, 90) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'pay-the-broadcasting-fee', $seed${"slug":"pay-the-broadcasting-fee","title":{"en":"Pay the broadcasting fee","ne":"प्रसारण शुल्क तिर्नुहोस्","hi":"प्रसारण शुल्क भरें"},"term":{"term":"Rundfunkbeitrag"},"stage":"first30","readingMinutes":4,"lastVerified":"2026-11-05","summary":{"what":{"en":"A fee for public TV and radio. It is paid once per flat — not per person — whether or not you own a TV.","ne":"सार्वजनिक टिभी र रेडियोको शुल्क। यो प्रति व्यक्ति होइन, प्रति फ्ल्याट एकपटक तिरिन्छ — टिभी भए पनि नभए पनि।","hi":"सार्वजनिक टीवी और रेडियो का शुल्क। यह प्रति व्यक्ति नहीं, प्रति फ़्लैट एक बार भरा जाता है — टीवी हो या न हो।"},"when":{"en":"From the month you move in.","ne":"सरेको महिनादेखि।","hi":"शिफ़्ट होने वाले महीने से।"},"deadline":{"en":"Register when you move in","ne":"सर्दा दर्ता गर्नुहोस्","hi":"शिफ़्ट होते समय पंजीकरण करें"}},"steps":[{"title":{"en":"Check whether your flat already pays","ne":"फ्ल्याटले पहिले नै तिर्छ कि जाँच्नुहोस्","hi":"जांचें कि फ़्लैट पहले से भरता है या नहीं"},"body":{"en":"In a shared flat, one person pays for everyone. Ask your flatmates for their contribution number and register with it, so you aren’t charged twice. In a dorm, your own room usually counts as a flat.","ne":"साझा फ्ल्याटमा एकजनाले सबैका लागि तिर्छ। दोहोरो शुल्क नलागोस् भनेर साथीहरूसँग योगदान नम्बर लिएर त्यसैसँग दर्ता गर्नुहोस्। छात्रावासमा प्रायः आफ्नै कोठालाई फ्ल्याट मानिन्छ।","hi":"साझा फ़्लैट में एक व्यक्ति सबके लिए भरता है। दोहरा शुल्क न लगे, इसलिए साथियों से उनका योगदान नंबर लेकर उसी से पंजीकरण करें। हॉस्टल में आमतौर पर आपका अपना कमरा फ़्लैट माना जाता है।"},"term":{"term":"Beitragsnummer"}},{"title":{"en":"Register online","ne":"अनलाइन दर्ता गर्नुहोस्","hi":"ऑनलाइन पंजीकरण करें"},"body":{"en":"Register on rundfunkbeitrag.de. You get a contribution number by post.","ne":"rundfunkbeitrag.de मा दर्ता गर्नुहोस्। योगदान नम्बर हुलाकबाट आउँछ।","hi":"rundfunkbeitrag.de पर पंजीकरण करें। योगदान नंबर डाक से आता है।"},"cost":{"en":"€18.36 a month per flat","ne":"प्रति फ्ल्याट महिनाको €१८.३६","hi":"प्रति फ़्लैट हर महीने €18.36"}},{"title":{"en":"Pay every three months","ne":"हरेक तीन महिनामा तिर्नुहोस्","hi":"हर तीन महीने में भरें"},"body":{"en":"The fee is due quarterly (€55.08). A direct debit from your German account is easiest. In a shared flat, split the cost.","ne":"शुल्क हरेक तीन महिनामा (€५५.०८) तिर्नुपर्छ। जर्मन खाताबाट स्वचालित कटौती सबैभन्दा सजिलो हो। साझा फ्ल्याटमा खर्च बाँड्नुहोस्।","hi":"शुल्क हर तिमाही (€55.08) देना होता है। जर्मन खाते से ऑटो डेबिट सबसे आसान है। साझा फ़्लैट में ख़र्च बांटें।"},"term":{"term":"SEPA-Lastschrift"}}],"documents":[{"en":"Your address and moving-in date","ne":"तपाईंको ठेगाना र सरेको मिति","hi":"आपका पता और शिफ़्ट होने की तारीख"},{"en":"Flatmate’s contribution number, if they already pay","ne":"साथीले तिरिरहेको भए उसको योगदान नम्बर","hi":"अगर साथी भरता है तो उसका योगदान नंबर"}],"callouts":[{"kind":"tip","text":{"en":"Students who receive BAföG and don’t live with their parents can apply for an exemption. It is not automatic — you must apply.","ne":"BAföG पाउने र आमाबुबासँग नबस्ने विद्यार्थीले छुटका लागि आवेदन दिन सक्छन्। यो आफैं हुँदैन — आवेदन दिनुपर्छ।","hi":"BAföG पाने वाले और माता-पिता के साथ न रहने वाले छात्र छूट के लिए आवेदन कर सकते हैं। यह अपने आप नहीं होता — आवेदन करना होता है।"}},{"kind":"mistake","text":{"en":"Ignoring the letters doesn’t help: unpaid fees are collected with extra charges.","ne":"चिठी बेवास्ता गर्नु काम लाग्दैन: नतिरेको शुल्क थप शुल्कसहित असुल गरिन्छ।","hi":"पत्रों को अनदेखा करने से कुछ नहीं होता: बकाया शुल्क अतिरिक्त शुल्क के साथ वसूला जाता है।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"tool","title":{"en":"Plan your monthly budget","ne":"मासिक बजेट योजना बनाउनुहोस्","hi":"मासिक बजट की योजना बनाएं"},"href":"/tools/budget"},{"kind":"guide","title":{"en":"Find a room in Leipzig","ne":"लाइपजिगमा कोठा खोज्नुहोस्","hi":"लाइपज़िग में कमरा खोजें"},"href":"/guides/find-housing-leipzig"}],"actions":[{"label":{"en":"Register online","ne":"अनलाइन दर्ता गर्नुहोस्","hi":"ऑनलाइन पंजीकरण करें"},"url":"https://www.rundfunkbeitrag.de/buergerinnen-und-buerger/informationen"}],"sources":[{"title":"Beitragsservice — Information for students","url":"https://www.rundfunkbeitrag.de/buergerinnen_und_buerger/informationen/informationen_fuer_studierende/index_ger.html"},{"title":"Beitragsservice — Payment","url":"https://www.rundfunkbeitrag.de/buergerinnen-und-buerger/informationen/zahlung"},{"title":"Beitragsservice — Information for citizens","url":"https://www.rundfunkbeitrag.de/buergerinnen-und-buerger/informationen"}]}$seed$::jsonb, 100) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'choose-a-phone-plan', $seed${"slug":"choose-a-phone-plan","title":{"en":"Choose a phone plan","ne":"फोन प्लान छान्नुहोस्","hi":"फ़ोन प्लान चुनें"},"term":{"term":"Handyvertrag"},"stage":"first30","readingMinutes":4,"lastVerified":"2026-11-05","summary":{"what":{"en":"A German number for calls, mobile data and the codes that banks and offices send by SMS.","ne":"कल, मोबाइल डाटा र बैंक तथा कार्यालयले SMS बाट पठाउने कोडका लागि जर्मन नम्बर।","hi":"कॉल, मोबाइल डेटा और बैंकों व दफ़्तरों के SMS कोड के लिए जर्मन नंबर।"},"when":{"en":"In your first days.","ne":"सुरुका दिनमै।","hi":"शुरुआती दिनों में।"},"deadline":{"en":"No deadline","ne":"कुनै समयसीमा छैन","hi":"कोई समयसीमा नहीं"}},"steps":[{"title":{"en":"Start with prepaid","ne":"प्रिपेडबाट सुरु गर्नुहोस्","hi":"प्रीपेड से शुरू करें"},"body":{"en":"Prepaid has no contract and no credit check. You top up and can stop any time. It is the easiest start.","ne":"प्रिपेडमा सम्झौता र क्रेडिट जाँच हुँदैन। रिचार्ज गर्नुहुन्छ र जुनसुकै बेला बन्द गर्न सक्नुहुन्छ। सुरुका लागि सबैभन्दा सजिलो।","hi":"प्रीपेड में कोई अनुबंध और क्रेडिट जांच नहीं होती। आप रिचार्ज करते हैं और कभी भी बंद कर सकते हैं। शुरुआत के लिए सबसे आसान।"},"term":{"term":"Prepaid"}},{"title":{"en":"Verify your identity","ne":"आफ्नो पहिचान पुष्टि गर्नुहोस्","hi":"अपनी पहचान सत्यापित करें"},"body":{"en":"By law, every SIM card must be registered with a valid ID. You activate it in a shop or online by video call, with your passport.","ne":"कानुनअनुसार हरेक SIM कार्ड वैध परिचयपत्रसहित दर्ता हुनुपर्छ। पसलमा वा अनलाइन भिडियो कलमार्फत राहदानी देखाएर सक्रिय गर्नुहुन्छ।","hi":"क़ानून के अनुसार हर SIM कार्ड वैध पहचान-पत्र से पंजीकृत होना चाहिए। आप दुकान में या ऑनलाइन वीडियो कॉल से पासपोर्ट दिखाकर इसे सक्रिय करते हैं।"},"term":{"term":"Video-Ident"}},{"title":{"en":"Thinking of a contract? Read the term","ne":"सम्झौता सोच्दै हुनुहुन्छ? अवधि पढ्नुहोस्","hi":"अनुबंध सोच रहे हैं? अवधि पढ़ें"},"body":{"en":"Contracts can run for up to 24 months; providers must also offer a 12-month option. After the minimum term you can cancel with one month’s notice.","ne":"सम्झौता बढीमा २४ महिनासम्म हुन सक्छ; प्रदायकले १२ महिनाको विकल्प पनि दिनैपर्छ। न्यूनतम अवधिपछि एक महिनाको सूचना दिएर रद्द गर्न सकिन्छ।","hi":"अनुबंध ज़्यादा से ज़्यादा 24 महीने का हो सकता है; प्रदाता को 12 महीने का विकल्प भी देना होता है। न्यूनतम अवधि के बाद एक महीने के नोटिस पर रद्द कर सकते हैं।"},"term":{"term":"Mindestvertragslaufzeit"}}],"documents":[{"en":"Passport","ne":"राहदानी","hi":"पासपोर्ट"},{"en":"German address","ne":"जर्मन ठेगाना","hi":"जर्मन पता"},{"en":"German bank account (for contracts)","ne":"जर्मन बैंक खाता (सम्झौताका लागि)","hi":"जर्मन बैंक खाता (अनुबंध के लिए)"}],"callouts":[{"kind":"tip","text":{"en":"Need a number before you arrive? Many providers sell eSIMs online — you still have to verify your identity with your passport before the SIM works.","ne":"आइपुग्नुअघि नै नम्बर चाहियो? धेरै प्रदायकले अनलाइन eSIM बेच्छन् — SIM चल्नुअघि राहदानीसहित पहिचान पुष्टि गर्नैपर्छ।","hi":"पहुंचने से पहले नंबर चाहिए? कई प्रदाता ऑनलाइन eSIM बेचते हैं — SIM चालू होने से पहले पासपोर्ट से पहचान सत्यापित करनी ही होगी।"}},{"kind":"mistake","text":{"en":"Don’t sign a 24-month contract in your first week. Prepaid lets you test the network in your area first.","ne":"पहिलो हप्तामै २४ महिनाको सम्झौतामा हस्ताक्षर नगर्नुहोस्। प्रिपेडले पहिले आफ्नो क्षेत्रमा नेटवर्क जाँच्न दिन्छ।","hi":"पहले हफ़्ते में ही 24 महीने के अनुबंध पर हस्ताक्षर न करें। प्रीपेड से पहले अपने इलाक़े में नेटवर्क जांच सकते हैं।"}},{"kind":"warning","text":{"en":"Avoid SIM cards that are already activated in someone else’s name. The card stays linked to that person’s ID, and you have no rights under the contract.","ne":"अरूकै नाममा पहिले नै सक्रिय गरिएको SIM कार्ड नलिनुहोस्। कार्ड त्यही व्यक्तिको परिचयपत्रसँग जोडिएको रहन्छ, र सम्झौतामा तपाईंको कुनै अधिकार हुँदैन।","hi":"किसी और के नाम पर पहले से सक्रिय SIM कार्ड न लें। कार्ड उसी व्यक्ति की पहचान से जुड़ा रहता है, और अनुबंध में आपका कोई अधिकार नहीं होता।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Open a bank account","ne":"बैंक खाता खोल्नुहोस्","hi":"बैंक खाता खोलें"},"href":"/guides/open-a-bank-account"},{"kind":"tool","title":{"en":"Plan your monthly budget","ne":"मासिक बजेट योजना बनाउनुहोस्","hi":"मासिक बजट की योजना बनाएं"},"href":"/tools/budget"}],"sources":[{"title":"Bundesnetzagentur — Phone and internet contracts","url":"https://www.bundesnetzagentur.de/DE/Vportal/TK/InternetTelefon/Vertrag/start.html"},{"title":"Bundesnetzagentur — Identity checks for prepaid SIM cards (PDF)","url":"https://www.bundesnetzagentur.de/SharedDocs/Downloads/DE/Sachgebiete/Telekommunikation/Unternehmen_Institutionen/Anbieterpflichten/OeffentlicheSicherheit/IdentverfahrenPrepaid/HandreichungStandDezember2021V1.1.pdf?__blob=publicationFile&v=1"},{"title":"Verbraucherzentrale — Prepaid or contract?","url":"https://www.verbraucherzentrale.de/wissen/digitale-welt/mobilfunk-und-festnetz/handytarife-prepaid-oder-laufzeitvertrag-59732"}]}$seed$::jsonb, 110) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'monthly-transit-pass', $seed${"slug":"monthly-transit-pass","title":{"en":"Get a monthly transit pass","ne":"मासिक यातायात पास लिनुहोस्","hi":"मासिक परिवहन पास लें"},"term":{"term":"Deutschlandticket"},"stage":"first30","readingMinutes":3,"lastVerified":"2026-11-05","updatedRecently":true,"summary":{"what":{"en":"One monthly ticket for buses, trams, U-/S-Bahn and regional trains across Germany. Not valid on ICE/IC long-distance trains.","ne":"जर्मनीभरका बस, ट्राम, U-/S-Bahn र क्षेत्रीय रेलका लागि एउटै मासिक टिकट। ICE/IC लामो दूरीका रेलमा मान्य छैन।","hi":"पूरे जर्मनी में बस, ट्राम, U-/S-Bahn और क्षेत्रीय ट्रेनों के लिए एक मासिक टिकट। ICE/IC लंबी दूरी की ट्रेनों में मान्य नहीं।"},"when":{"en":"From your first month — unless your semester ticket already covers you.","ne":"पहिलो महिनादेखि — सेमेस्टर टिकटले पहिले नै कभर गर्दैन भने।","hi":"पहले महीने से — अगर सेमेस्टर टिकट पहले से कवर नहीं करता।"},"deadline":{"en":"Cancel by the 10th for the end of the month","ne":"महिनाको अन्त्यका लागि १० तारिखसम्म रद्द गर्नुहोस्","hi":"महीने के अंत के लिए 10 तारीख तक रद्द करें"}},"steps":[{"title":{"en":"Students: use your semester ticket","ne":"विद्यार्थी: सेमेस्टर टिकट प्रयोग गर्नुहोस्","hi":"छात्र: सेमेस्टर टिकट इस्तेमाल करें"},"body":{"en":"At Leipzig University the Deutschland-Semesterticket is part of your semester fee. Activate it in LeipzigMOVE — don’t buy a second ticket.","ne":"लाइपजिग विश्वविद्यालयमा Deutschland-Semesterticket सेमेस्टर शुल्कमै समावेश छ। LeipzigMOVE मा सक्रिय गर्नुहोस् — अर्को टिकट नकिन्नुहोस्।","hi":"लाइपज़िग विश्वविद्यालय में Deutschland-Semesterticket सेमेस्टर फ़ीस में शामिल है। इसे LeipzigMOVE में सक्रिय करें — दूसरा टिकट न ख़रीदें।"}},{"title":{"en":"Everyone else: subscribe","ne":"अरू सबै: सदस्यता लिनुहोस्","hi":"बाक़ी सब: सदस्यता लें"},"body":{"en":"The Deutschlandticket is a monthly subscription. In Leipzig you can buy it from the local transport companies in the MDV area, or from Deutsche Bahn.","ne":"Deutschlandticket मासिक सदस्यता हो। लाइपजिगमा MDV क्षेत्रका स्थानीय यातायात कम्पनी वा Deutsche Bahn बाट किन्न सकिन्छ।","hi":"Deutschlandticket एक मासिक सदस्यता है। लाइपज़िग में आप इसे MDV क्षेत्र की स्थानीय परिवहन कंपनियों या Deutsche Bahn से ख़रीद सकते हैं।"},"cost":{"en":"€63 a month · €66.80 from January 2027","ne":"महिनाको €६३ · जनवरी २०२७ देखि €६६.८०","hi":"हर महीने €63 · जनवरी 2027 से €66.80"}},{"title":{"en":"Cancel in time","ne":"समयमै रद्द गर्नुहोस्","hi":"समय पर रद्द करें"},"body":{"en":"You can cancel monthly. Cancel by the 10th to stop at the end of that month.","ne":"मासिक रूपमा रद्द गर्न सकिन्छ। त्यही महिनाको अन्त्यमा रोक्न १० तारिखसम्म रद्द गर्नुहोस्।","hi":"आप हर महीने रद्द कर सकते हैं। उसी महीने के अंत में बंद करने के लिए 10 तारीख तक रद्द करें।"}}],"documents":[{"en":"German bank account for the direct debit","ne":"स्वचालित कटौतीका लागि जर्मन बैंक खाता","hi":"ऑटो डेबिट के लिए जर्मन बैंक खाता"}],"callouts":[{"kind":"tip","text":{"en":"Keep the ticket in the app on your phone and carry your ID: inspectors may ask for both.","ne":"टिकट फोनको एपमा राख्नुहोस् र परिचयपत्र साथमा बोक्नुहोस्: जाँचकीले दुवै माग्न सक्छ।","hi":"टिकट फ़ोन के ऐप में रखें और पहचान-पत्र साथ रखें: जांच करने वाले दोनों मांग सकते हैं।"}},{"kind":"warning","text":{"en":"The price rises to €66.80 on 1 January 2027. Your ticket provider will tell you how the change works for your subscription.","ne":"१ जनवरी २०२७ देखि मूल्य €६६.८० हुन्छ। तपाईंको सदस्यतामा परिवर्तन कसरी हुन्छ, टिकट प्रदायकले जानकारी दिन्छ।","hi":"1 जनवरी 2027 से कीमत €66.80 हो जाएगी। आपकी सदस्यता में बदलाव कैसे होगा, टिकट प्रदाता बताएगा।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Enrol at university","ne":"विश्वविद्यालयमा भर्ना हुनुहोस्","hi":"विश्वविद्यालय में दाख़िला लें"},"href":"/guides/enrol-at-university"},{"kind":"tool","title":{"en":"Plan your monthly budget","ne":"मासिक बजेट योजना बनाउनुहोस्","hi":"मासिक बजट की योजना बनाएं"},"href":"/tools/budget"}],"sources":[{"title":"Federal Government — Deutschlandticket questions and answers","url":"https://www.bundesregierung.de/breg-de/aktuelles/deutschlandticket-2134074"},{"title":"Deutsche Bahn — The Deutschland-Ticket (€63, €66.80 from 2027)","url":"https://int.bahn.de/en/offers/regional/deutschland-ticket"},{"title":"MDV — Buying the Deutschlandticket in the Leipzig-Halle area","url":"https://www.mdv.de/tickets-tarif/abos/deutschlandticket"},{"title":"Studentenwerk Leipzig — Price increase for the semester ticket (PDF)","url":"https://www.studentenwerk-leipzig.de/ext/uploads/2026/02/26-02-12-Preiserhoehung-fuer-Deutschland-Semesterticket-und-Co.-%E2%80%93-studentische-Mobilitaet-in-Leipzig-wird-teurer.pdf"}]}$seed$::jsonb, 120) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'find-a-family-doctor', $seed${"slug":"find-a-family-doctor","title":{"en":"Find a family doctor","ne":"पारिवारिक डाक्टर खोज्नुहोस्","hi":"फ़ैमिली डॉक्टर खोजें"},"term":{"term":"Hausarzt"},"stage":"living","readingMinutes":4,"lastVerified":"2026-11-05","summary":{"what":{"en":"A general practitioner who is your first stop when you are ill and who refers you to specialists.","ne":"बिरामी हुँदा पहिलो पटक जाने र विशेषज्ञकहाँ पठाउने सामान्य चिकित्सक।","hi":"एक सामान्य चिकित्सक जो बीमार होने पर आपका पहला पड़ाव है और विशेषज्ञ के पास भेजता है।"},"when":{"en":"Before you get ill — new patients can wait for weeks.","ne":"बिरामी पर्नुअघि नै — नयाँ बिरामीले हप्तौं पर्खनुपर्ने हुन सक्छ।","hi":"बीमार पड़ने से पहले — नए मरीज़ों को हफ़्तों इंतज़ार करना पड़ सकता है।"},"deadline":{"en":"No deadline","ne":"कुनै समयसीमा छैन","hi":"कोई समयसीमा नहीं"}},"steps":[{"title":{"en":"Search on 116117","ne":"116117 मा खोज्नुहोस्","hi":"116117 पर खोजें"},"body":{"en":"The official doctor search on 116117.de (and the 116117 app) lets you filter by distance and by languages the doctor speaks.","ne":"116117.de (र 116117 एप) को आधिकारिक डाक्टर खोजमा दूरी र डाक्टरले बोल्ने भाषाअनुसार छान्न सकिन्छ।","hi":"116117.de (और 116117 ऐप) की आधिकारिक डॉक्टर खोज में दूरी और डॉक्टर की भाषाओं के अनुसार फ़िल्टर कर सकते हैं।"},"term":{"term":"Arztsuche"},"cost":{"en":"Free","ne":"निःशुल्क","hi":"मुफ़्त"}},{"title":{"en":"Call and ask if they take new patients","ne":"फोन गरेर नयाँ बिरामी लिन्छन् कि सोध्नुहोस्","hi":"फ़ोन करके पूछें कि नए मरीज़ लेते हैं या नहीं"},"body":{"en":"Say: “Nehmen Sie neue Patienten auf?” If the practice is full, the 116117 appointment service can help you find one.","ne":"भन्नुहोस्: “Nehmen Sie neue Patienten auf?” क्लिनिक भरिएको छ भने 116117 को अपोइन्टमेन्ट सेवाले खोज्न सहयोग गर्छ।","hi":"कहें: “Nehmen Sie neue Patienten auf?” अगर क्लिनिक भरा है, तो 116117 की अपॉइंटमेंट सेवा मदद कर सकती है।"}},{"title":{"en":"Bring your health card to every visit","ne":"हरेक भेटमा स्वास्थ्य कार्ड लैजानुहोस्","hi":"हर बार हेल्थ कार्ड साथ ले जाएं"},"body":{"en":"With statutory insurance, visits are paid directly by your fund. For prescriptions you usually pay a small share at the pharmacy.","ne":"सरकारी बीमामा डाक्टरको खर्च कोषले सिधै तिर्छ। औषधिको प्रेस्क्रिप्सनमा प्रायः फार्मेसीमा थोरै अंश तिर्नुहुन्छ।","hi":"वैधानिक बीमा में डॉक्टर का ख़र्च कोष सीधे भरता है। दवा के पर्चे पर आमतौर पर फ़ार्मेसी में थोड़ा हिस्सा देना होता है।"},"term":{"term":"Versichertenkarte"}}],"documents":[{"en":"Health card","ne":"स्वास्थ्य कार्ड","hi":"हेल्थ कार्ड"},{"en":"List of your medicines","ne":"तपाईंका औषधिहरूको सूची","hi":"आपकी दवाओं की सूची"}],"callouts":[{"kind":"tip","text":{"en":"Ill at night or at the weekend and it can’t wait? Call 116117 (free, 24/7) for the on-call doctor service.","ne":"राति वा सप्ताहान्तमा बिरामी, पर्खन नमिल्ने? अन-कल डाक्टर सेवाका लागि 116117 (निःशुल्क, २४/७) मा फोन गर्नुहोस्।","hi":"रात में या सप्ताहांत पर बीमार और इंतज़ार नहीं कर सकते? ऑन-कॉल डॉक्टर सेवा के लिए 116117 (मुफ़्त, 24/7) पर कॉल करें।"}},{"kind":"warning","text":{"en":"Life-threatening emergency: call 112.","ne":"ज्यान जोखिमको आपतकाल: ११२ मा फोन गर्नुहोस्।","hi":"जानलेवा आपात स्थिति: 112 पर कॉल करें।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Activate your health insurance","ne":"स्वास्थ्य बीमा सक्रिय गर्नुहोस्","hi":"स्वास्थ्य बीमा सक्रिय करें"},"href":"/guides/activate-health-insurance"},{"kind":"tool","title":{"en":"Safety and emergency numbers","ne":"सुरक्षा र आपतकालीन नम्बर","hi":"सुरक्षा और आपातकालीन नंबर"},"href":"/tools/safety"}],"actions":[{"label":{"en":"Find a doctor on 116117","ne":"116117 मा डाक्टर खोज्नुहोस्","hi":"116117 पर डॉक्टर खोजें"},"url":"https://www.116117.de/de/patientenservice.php"}],"sources":[{"title":"116117 — Patient service","url":"https://www.116117.de/de/patientenservice.php"},{"title":"116117 — On-call medical service","url":"https://www.116117.de/de/aerztlicher-bereitschaftsdienst.php"},{"title":"KBV — The 116117 patient service","url":"https://www.kbv.de/positionen/dossiers/notfallversorgung/patientenservice-116117"}]}$seed$::jsonb, 130) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'student-jobs', $seed${"slug":"student-jobs","title":{"en":"Student jobs and work limits","ne":"विद्यार्थी काम र कामको सीमा","hi":"छात्र नौकरियां और काम की सीमा"},"term":{"term":"Nebenjob"},"stage":"living","readingMinutes":6,"lastVerified":"2026-11-05","summary":{"what":{"en":"With a student residence permit you may work 140 full days or 280 half days a year — or alternatively up to 20 hours a week.","ne":"विद्यार्थी आवास अनुमतिपत्रमा वर्षमा १४० पूरा दिन वा २८० आधा दिन — वा विकल्पमा हप्तामा बढीमा २० घण्टा काम गर्न पाइन्छ।","hi":"छात्र निवास परमिट पर आप साल में 140 पूरे दिन या 280 आधे दिन — या विकल्प के तौर पर हफ़्ते में 20 घंटे तक काम कर सकते हैं।"},"when":{"en":"Before you sign a job contract.","ne":"कामको सम्झौतामा हस्ताक्षर गर्नुअघि।","hi":"नौकरी के अनुबंध पर हस्ताक्षर से पहले।"},"deadline":{"en":"Counts per calendar year","ne":"पात्रो वर्षअनुसार गनिन्छ","hi":"कैलेंडर साल के हिसाब से गिना जाता है"}},"steps":[{"title":{"en":"Count your days","ne":"आफ्ना दिनहरू गन्नुहोस्","hi":"अपने दिन गिनें"},"body":{"en":"A day with more than 4 hours of work counts as a full day; up to 4 hours is a half day. Log every work day — our work-limit tool does it for you.","ne":"४ घण्टाभन्दा बढी काम गरेको दिन पूरा दिन गनिन्छ; ४ घण्टासम्म आधा दिन। हरेक कामको दिन लेख्नुहोस् — हाम्रो कामको सीमा उपकरणले यो गर्छ।","hi":"4 घंटे से ज़्यादा काम वाला दिन पूरा दिन गिना जाता है; 4 घंटे तक आधा दिन। हर काम का दिन लिखें — हमारा काम-सीमा टूल यह करता है।"},"term":{"term":"Arbeitstag"}},{"title":{"en":"Know your pay","ne":"आफ्नो तलब बुझ्नुहोस्","hi":"अपना वेतन समझें"},"body":{"en":"The minimum wage is €13.90 an hour in 2026 (€14.60 from 2027). In a mini-job you may earn up to €603 a month; you pay 3.6% pension contribution unless you opt out.","ne":"२०२६ मा न्यूनतम ज्याला प्रतिघण्टा €१३.९० (२०२७ देखि €१४.६०) छ। मिनी-जबमा महिनामा €६०३ सम्म कमाउन पाइन्छ; छुट नलिएसम्म ३.६% पेन्सन योगदान तिर्नुहुन्छ।","hi":"2026 में न्यूनतम वेतन €13.90 प्रति घंटा (2027 से €14.60) है। मिनी-जॉब में आप हर महीने €603 तक कमा सकते हैं; छूट न लें तो 3.6% पेंशन योगदान देते हैं।"},"term":{"term":"Mindestlohn"}},{"title":{"en":"Working student job","ne":"वर्किङ स्टुडेन्ट काम","hi":"वर्किंग स्टूडेंट नौकरी"},"body":{"en":"Above €603 a month, a job of up to 20 hours a week during lectures is usually a working-student job. You then pay only pension insurance (9.3%) — no health or unemployment insurance.","ne":"महिनामा €६०३ भन्दा बढी भए, कक्षा अवधिमा हप्तामा २० घण्टासम्मको काम प्रायः वर्किङ स्टुडेन्ट काम हुन्छ। त्यसमा पेन्सन बीमा (९.३%) मात्र तिर्नुहुन्छ — स्वास्थ्य वा बेरोजगारी बीमा होइन।","hi":"€603 प्रति माह से ज़्यादा पर, लेक्चर के समय हफ़्ते में 20 घंटे तक का काम आमतौर पर वर्किंग स्टूडेंट नौकरी होता है। तब आप केवल पेंशन बीमा (9.3%) देते हैं — स्वास्थ्य या बेरोज़गारी बीमा नहीं।"},"term":{"term":"Werkstudent"}},{"title":{"en":"Need more? Ask first","ne":"बढी चाहियो? पहिले सोध्नुहोस्","hi":"ज़्यादा चाहिए? पहले पूछें"},"body":{"en":"Working more, or working as a freelancer, needs permission from the foreigners’ office (and often the Federal Employment Agency). Ask before you start.","ne":"बढी काम गर्न वा फ्रिलान्सरका रूपमा काम गर्न विदेशी कार्यालय (र प्रायः संघीय रोजगार एजेन्सी) को अनुमति चाहिन्छ। सुरु गर्नुअघि सोध्नुहोस्।","hi":"ज़्यादा काम करने या फ़्रीलांसर के रूप में काम करने के लिए विदेशी कार्यालय (और अक्सर संघीय रोज़गार एजेंसी) की अनुमति चाहिए। शुरू करने से पहले पूछें।"}}],"documents":[{"en":"Residence permit","ne":"आवास अनुमतिपत्र","hi":"निवास परमिट"},{"en":"Tax ID","ne":"कर आईडी","hi":"टैक्स आईडी"},{"en":"Social security number (your pension insurance sends it)","ne":"सामाजिक सुरक्षा नम्बर (पेन्सन बीमाले पठाउँछ)","hi":"सामाजिक सुरक्षा नंबर (पेंशन बीमा भेजता है)"},{"en":"Enrolment certificate","ne":"भर्ना प्रमाणपत्र","hi":"दाख़िला प्रमाणपत्र"},{"en":"German bank account","ne":"जर्मन बैंक खाता","hi":"जर्मन बैंक खाता"}],"callouts":[{"kind":"warning","text":{"en":"Working more than allowed can cost you your residence permit. Keep your own record of days and hours.","ne":"अनुमतिभन्दा बढी काम गर्दा आवास अनुमतिपत्र गुम्न सक्छ। दिन र घण्टाको आफ्नै अभिलेख राख्नुहोस्।","hi":"अनुमति से ज़्यादा काम करने पर निवास परमिट जा सकता है। दिनों और घंटों का अपना रिकॉर्ड रखें।"}},{"kind":"tip","text":{"en":"Tax was taken from your pay? If you earned less than €12,348 in 2026, a tax return usually gets it back.","ne":"तलबबाट कर काटियो? २०२६ मा €१२,३४८ भन्दा कम कमाउनुभयो भने कर विवरण बुझाउँदा प्रायः फिर्ता पाइन्छ।","hi":"वेतन से टैक्स कटा? अगर 2026 में €12,348 से कम कमाया, तो टैक्स रिटर्न से आमतौर पर वापस मिल जाता है।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"tool","title":{"en":"Work-limit tracker","ne":"कामको सीमा ट्र्याकर","hi":"काम-सीमा ट्रैकर"},"href":"/tools/work-limit"},{"kind":"tool","title":{"en":"Net pay calculator","ne":"खुद तलब क्याल्कुलेटर","hi":"शुद्ध वेतन कैलकुलेटर"},"href":"/tools/net-pay"}],"sources":[{"title":"Make it in Germany — The new Skilled Immigration Act","url":"https://www.make-it-in-germany.com/en/visa-recognition/skilled-immigration-act"},{"title":"DAAD — Side jobs for international students","url":"https://www.daad.de/en/study-and-research-in-germany/first-steps-germany/side-jobs/"},{"title":"Deutsche Rentenversicherung — Mini-job earnings limit rises to €603","url":"https://www.deutsche-rentenversicherung.de/BadenWuerttemberg/DE/Presse/Pressemitteilungen/2025/251222_Minijob.html"},{"title":"Minijob-Zentrale — Students","url":"https://www.minijob-zentrale.de/DE/die-minijobs/studenten/studenten_node.html"},{"title":"Minijob-Zentrale — Pension insurance in a mini job","url":"https://magazin.minijob-zentrale.de/rentenversicherung-befreiung-minijob/"},{"title":"Deutsche Rentenversicherung — Tips for students: studying and working (PDF)","url":"https://www.deutsche-rentenversicherung.de/SharedDocs/Downloads/DE/Broschueren/national/tipps_fuer_studierende.pdf?__blob=publicationFile&v=9"}]}$seed$::jsonb, 140) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'file-tax-return', $seed${"slug":"file-tax-return","title":{"en":"File your tax return","ne":"कर विवरण बुझाउनुहोस्","hi":"टैक्स रिटर्न भरें"},"term":{"term":"Steuererklärung"},"stage":"living","readingMinutes":5,"lastVerified":"2026-11-05","summary":{"what":{"en":"A yearly statement of your income to the tax office. Students with a small job often get withheld tax back.","ne":"कर कार्यालयलाई आफ्नो आम्दानीको वार्षिक विवरण। सानो काम गर्ने विद्यार्थीले प्रायः काटिएको कर फिर्ता पाउँछन्।","hi":"टैक्स कार्यालय को अपनी आय का सालाना विवरण। छोटी नौकरी करने वाले छात्रों को अक्सर कटा हुआ टैक्स वापस मिलता है।"},"when":{"en":"After the end of the year in which you worked.","ne":"काम गरेको वर्ष सकिएपछि।","hi":"जिस साल काम किया, उसके ख़त्म होने के बाद।"},"deadline":{"en":"31 July of the next year, if you must file","ne":"बुझाउनैपर्ने भए अर्को वर्षको ३१ जुलाई","hi":"अगर भरना ज़रूरी है तो अगले साल की 31 जुलाई"}},"steps":[{"title":{"en":"Find out if you must file","ne":"बुझाउनैपर्छ कि पत्ता लगाउनुहोस्","hi":"पता करें कि भरना ज़रूरी है या नहीं"},"body":{"en":"With only one ordinary job you usually don’t have to. Filing voluntarily is still worth it if tax was deducted — you can do it up to 4 years back.","ne":"एउटा सामान्य काम मात्र भए प्रायः बुझाउनु पर्दैन। कर काटिएको भए स्वेच्छाले बुझाउनु फाइदाजनक छ — ४ वर्ष पछाडिसम्म बुझाउन सकिन्छ।","hi":"केवल एक सामान्य नौकरी हो तो आमतौर पर ज़रूरी नहीं। टैक्स कटा हो तो अपनी मर्ज़ी से भरना फ़ायदेमंद है — 4 साल पीछे तक भर सकते हैं।"},"term":{"term":"Pflichtveranlagung"}},{"title":{"en":"Register for ELSTER","ne":"ELSTER मा दर्ता गर्नुहोस्","hi":"ELSTER पर पंजीकरण करें"},"body":{"en":"ELSTER is the tax office’s free online portal. Registering needs your tax ID; an activation code comes by post.","ne":"ELSTER कर कार्यालयको निःशुल्क अनलाइन पोर्टल हो। दर्ताका लागि कर आईडी चाहिन्छ; सक्रियता कोड हुलाकबाट आउँछ।","hi":"ELSTER टैक्स कार्यालय का मुफ़्त ऑनलाइन पोर्टल है। पंजीकरण के लिए टैक्स आईडी चाहिए; सक्रियता कोड डाक से आता है।"},"cost":{"en":"Free","ne":"निःशुल्क","hi":"मुफ़्त"},"wait":{"en":"About 2 weeks for the code","ne":"कोडका लागि करिब २ हप्ता","hi":"कोड के लिए लगभग 2 हफ़्ते"}},{"title":{"en":"Enter your wage statement","ne":"तलब विवरण भर्नुहोस्","hi":"वेतन विवरण भरें"},"body":{"en":"Your employer gives you an annual wage tax statement. ELSTER often fills it in for you. Add costs for work, such as travel to work.","ne":"रोजगारदाताले वार्षिक तलब कर विवरण दिन्छ। ELSTER ले प्रायः आफैं भरिदिन्छ। कामसम्बन्धी खर्च, जस्तै कामसम्मको यात्रा, थप्नुहोस्।","hi":"आपका नियोक्ता सालाना वेतन टैक्स विवरण देता है। ELSTER अक्सर इसे अपने आप भर देता है। काम से जुड़े ख़र्च, जैसे काम पर आने-जाने का ख़र्च, जोड़ें।"},"term":{"term":"Lohnsteuerbescheinigung"}},{"title":{"en":"Wait for the tax assessment","ne":"कर निर्धारण पत्र पर्खनुहोस्","hi":"टैक्स निर्धारण का इंतज़ार करें"},"body":{"en":"The tax office sends a decision. Any refund is paid into your bank account. Check it — you can object within one month.","ne":"कर कार्यालयले निर्णय पठाउँछ। फिर्ता हुने रकम बैंक खातामा आउँछ। जाँच्नुहोस् — एक महिनाभित्र आपत्ति गर्न सकिन्छ।","hi":"टैक्स कार्यालय फ़ैसला भेजता है। रिफ़ंड बैंक खाते में आता है। इसे जांचें — एक महीने के अंदर आपत्ति कर सकते हैं।"},"term":{"term":"Steuerbescheid"}}],"documents":[{"en":"Tax ID","ne":"कर आईडी","hi":"टैक्स आईडी"},{"en":"Annual wage tax statement from each employer","ne":"हरेक रोजगारदाताको वार्षिक तलब कर विवरण","hi":"हर नियोक्ता का सालाना वेतन टैक्स विवरण"},{"en":"Bank account (IBAN)","ne":"बैंक खाता (IBAN)","hi":"बैंक खाता (IBAN)"},{"en":"Receipts for work-related costs","ne":"कामसम्बन्धी खर्चका रसिद","hi":"काम से जुड़े ख़र्चों की रसीदें"}],"callouts":[{"kind":"tip","text":{"en":"In 2026 the first €12,348 of income is tax-free. Many students with a part-time job get all their wage tax back.","ne":"२०२६ मा पहिलो €१२,३४८ आम्दानी करमुक्त छ। आंशिक काम गर्ने धेरै विद्यार्थीले सबै तलब कर फिर्ता पाउँछन्।","hi":"2026 में पहले €12,348 की आय टैक्स-मुक्त है। पार्ट-टाइम नौकरी करने वाले कई छात्रों को पूरा वेतन टैक्स वापस मिलता है।"}},{"kind":"mistake","text":{"en":"If you must file and miss the deadline, the tax office can charge a late fee. When in doubt, ask a free counselling service.","ne":"बुझाउनैपर्ने भएर पनि समयसीमा नाघ्नुभयो भने कर कार्यालयले ढिलाइ शुल्क लिन सक्छ। शंका भए निःशुल्क परामर्श सेवालाई सोध्नुहोस्।","hi":"अगर भरना ज़रूरी है और समयसीमा चूक गए, तो टैक्स कार्यालय देरी शुल्क ले सकता है। शक हो तो मुफ़्त परामर्श सेवा से पूछें।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"tool","title":{"en":"Net pay calculator","ne":"खुद तलब क्याल्कुलेटर","hi":"शुद्ध वेतन कैलकुलेटर"},"href":"/tools/net-pay"},{"kind":"guide","title":{"en":"Get your tax ID","ne":"आफ्नो कर आईडी लिनुहोस्","hi":"अपनी टैक्स आईडी पाएं"},"href":"/guides/get-your-tax-id"}],"actions":[{"label":{"en":"Open ELSTER","ne":"ELSTER खोल्नुहोस्","hi":"ELSTER खोलें"},"url":"https://www.elster.de/eportal/start"}],"sources":[{"title":"ELSTER — official online tax portal","url":"https://www.elster.de/eportal/start"},{"title":"Federal Ministry of Finance — Main tax changes 2026 (basic allowance €12,348)","url":"https://www.bundesfinanzministerium.de/Monatsberichte/Ausgabe/2026/02/Inhalte/Kapitel-2-Analysen/2-5-wichtigste-steuerliche-aenderungen-2026.html"},{"title":"Federal Ministry of Finance — Deadlines for tax returns (AO handbook)","url":"https://ao.bundesfinanzministerium.de/ao/2023/Anhaenge/BMF-Schreiben-und-gleichlautende-Laendererlasse/Anhang-82/anhang-82.html"}]}$seed$::jsonb, 150) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'extend-your-residence-permit', $seed${"slug":"extend-your-residence-permit","title":{"en":"Extend your residence permit","ne":"आवास अनुमतिपत्र नवीकरण गर्नुहोस्","hi":"निवास परमिट बढ़वाएं"},"term":{"term":"Verlängerung"},"stage":"career","city":"leipzig","readingMinutes":5,"lastVerified":"2026-11-05","summary":{"what":{"en":"Your student permit is issued for a limited time. In Leipzig you apply online to extend it while you are still studying.","ne":"विद्यार्थी अनुमतिपत्र सीमित अवधिका लागि दिइन्छ। पढाइ जारी रहँदा लाइपजिगमा अनलाइन आवेदन दिएर नवीकरण गर्नुहुन्छ।","hi":"छात्र परमिट सीमित समय के लिए मिलता है। पढ़ाई जारी रहने पर लाइपज़िग में ऑनलाइन आवेदन करके इसे बढ़वाते हैं।"},"when":{"en":"A few weeks before the date on your card.","ne":"कार्डमा लेखिएको मितिभन्दा केही हप्ताअघि।","hi":"कार्ड पर लिखी तारीख से कुछ हफ़्ते पहले।"},"deadline":{"en":"Before your permit ends","ne":"अनुमतिपत्रको म्याद सकिनुअघि","hi":"परमिट ख़त्म होने से पहले"}},"steps":[{"title":{"en":"Prepare up-to-date documents","ne":"अद्यावधिक कागजात तयार गर्नुहोस्","hi":"ताज़ा दस्तावेज़ तैयार करें"},"body":{"en":"You need a current enrolment certificate, proof of money for the new period and proof of health insurance. The office may ask about your study progress.","ne":"हालको भर्ना प्रमाणपत्र, नयाँ अवधिका लागि पैसाको प्रमाण र स्वास्थ्य बीमाको प्रमाण चाहिन्छ। कार्यालयले पढाइको प्रगतिबारे सोध्न सक्छ।","hi":"आपको ताज़ा दाख़िला प्रमाणपत्र, नई अवधि के लिए पैसे का सबूत और स्वास्थ्य बीमा का सबूत चाहिए। कार्यालय पढ़ाई की प्रगति के बारे में पूछ सकता है।"}},{"title":{"en":"Apply online","ne":"अनलाइन आवेदन दिनुहोस्","hi":"ऑनलाइन आवेदन करें"},"body":{"en":"Use the same online application as for your first permit. Apply before your permit ends — then your stay remains legal while the office decides.","ne":"पहिलो अनुमतिपत्रकै अनलाइन आवेदन प्रयोग गर्नुहोस्। म्याद सकिनुअघि आवेदन दिनुहोस् — त्यसपछि कार्यालयले निर्णय नगरुन्जेल तपाईंको बसाइ कानुनी रहन्छ।","hi":"पहले परमिट वाला ही ऑनलाइन आवेदन इस्तेमाल करें। परमिट ख़त्म होने से पहले आवेदन करें — तब कार्यालय के फ़ैसले तक आपका रहना क़ानूनी रहता है।"},"where":{"en":"Ausländerbehörde Leipzig (online)","ne":"Ausländerbehörde Leipzig (अनलाइन)","hi":"Ausländerbehörde Leipzig (ऑनलाइन)"},"cost":{"en":"€93","ne":"€९३","hi":"€93"}},{"title":{"en":"Give biometrics and collect the card","ne":"बायोमेट्रिक दिनुहोस् र कार्ड लिनुहोस्","hi":"बायोमेट्रिक दें और कार्ड लें"},"body":{"en":"You are invited by email. If the card is not ready before the old one ends, you get a Fiktionsbescheinigung.","ne":"तपाईंलाई इमेलबाट बोलाइन्छ। पुरानो कार्डको म्याद सकिनुअघि नयाँ तयार नभए Fiktionsbescheinigung पाउनुहुन्छ।","hi":"आपको ईमेल से बुलाया जाता है। पुराना कार्ड ख़त्म होने तक नया तैयार न हो तो Fiktionsbescheinigung मिलता है।"},"term":{"term":"Fiktionsbescheinigung"}}],"documents":[{"en":"Passport and current residence permit","ne":"राहदानी र हालको आवास अनुमतिपत्र","hi":"पासपोर्ट और मौजूदा निवास परमिट"},{"en":"Current enrolment certificate","ne":"हालको भर्ना प्रमाणपत्र","hi":"ताज़ा दाख़िला प्रमाणपत्र"},{"en":"Proof of money (€992 a month)","ne":"पैसाको प्रमाण (महिनामा €९९२)","hi":"पैसे का सबूत (हर महीने €992)"},{"en":"Proof of health insurance","ne":"स्वास्थ्य बीमाको प्रमाण","hi":"स्वास्थ्य बीमा का सबूत"},{"en":"Rental contract","ne":"भाडा सम्झौता","hi":"किराया अनुबंध"},{"en":"Transcript of records, if asked","ne":"माग भएमा अङ्कपत्र","hi":"मांगने पर अंकपत्र"}],"callouts":[{"kind":"tip","text":{"en":"Set a reminder about 8 weeks before your permit ends — the Me › Reminders tool can do this for you.","ne":"अनुमतिपत्रको म्याद सकिनुभन्दा करिब ८ हप्ताअघि रिमाइन्डर राख्नुहोस् — Me › Reminders ले यो गर्न सक्छ।","hi":"परमिट ख़त्म होने से लगभग 8 हफ़्ते पहले रिमाइंडर लगाएं — Me › Reminders यह कर सकता है।"}},{"kind":"warning","text":{"en":"Your passport must also be valid. Renew it at your embassy in time — a Nepali passport can take 1–2 months.","ne":"राहदानी पनि वैध हुनुपर्छ। समयमै दूतावासमा नवीकरण गर्नुहोस् — नेपाली राहदानीमा १–२ महिना लाग्न सक्छ।","hi":"पासपोर्ट भी वैध होना चाहिए। समय पर दूतावास में नवीनीकरण कराएं — नेपाली पासपोर्ट में 1–2 महीने लग सकते हैं।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Stay and look for work after graduation","ne":"स्नातकपछि बसेर काम खोज्नुहोस्","hi":"स्नातक के बाद रहकर नौकरी खोजें"},"href":"/guides/job-search-after-graduation"},{"kind":"guide","title":{"en":"Apply for your residence permit","ne":"आवास अनुमतिपत्रका लागि आवेदन दिनुहोस्","hi":"निवास परमिट के लिए आवेदन करें"},"href":"/guides/book-residence-permit-appointment"}],"actions":[{"label":{"en":"Apply online","ne":"अनलाइन आवेदन दिनुहोस्","hi":"ऑनलाइन आवेदन करें"},"url":"https://www.leipzig.de/service-portal/formulare/onlineantrag-aufenthalt-zu-ausbildung-studium-berufsanerkennung"}],"sources":[{"title":"Stadt Leipzig — Aufenthaltserlaubnis zum Studium beantragen","url":"https://www.leipzig.de/service-portal/dienstleistung/aufenthaltserlaubnis-zum-studium-beantragen-5f1ae6c5debf6"},{"title":"Stadt Leipzig — Online application: residence for study and training","url":"https://www.leipzig.de/service-portal/formulare/onlineantrag-aufenthalt-zu-ausbildung-studium-berufsanerkennung"},{"title":"City of Leipzig — Residence permit for a study course","url":"https://english.leipzig.de/youth-family-and-community/foreign-nationals-and-migrants/foreigners-authority/residence-for-training-and-study-purposes/residence-permit-for-a-study-course"},{"title":"Embassy of Nepal, Berlin","url":"https://de.nepalembassy.gov.np/"}]}$seed$::jsonb, 160) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'job-search-after-graduation', $seed${"slug":"job-search-after-graduation","title":{"en":"Stay and look for work after graduation","ne":"स्नातकपछि बसेर काम खोज्नुहोस्","hi":"स्नातक के बाद रहकर नौकरी खोजें"},"term":{"term":"Aufenthaltserlaubnis zur Arbeitsplatzsuche"},"stage":"career","city":"leipzig","readingMinutes":6,"lastVerified":"2026-11-05","summary":{"what":{"en":"After you graduate you can get a residence permit for up to 18 months to look for a job that matches your degree. You may work in any job during that time.","ne":"स्नातकपछि आफ्नो डिग्रीअनुसारको काम खोज्न बढीमा १८ महिनाको आवास अनुमतिपत्र पाउन सक्नुहुन्छ। त्यस बेला जुनसुकै काम गर्न पाइन्छ।","hi":"स्नातक के बाद अपनी डिग्री के अनुरूप नौकरी खोजने के लिए 18 महीने तक का निवास परमिट मिल सकता है। उस दौरान आप कोई भी काम कर सकते हैं।"},"when":{"en":"When you have passed your final exams.","ne":"अन्तिम परीक्षा पास गरेपछि।","hi":"अंतिम परीक्षा पास करने के बाद।"},"deadline":{"en":"Before your student permit ends","ne":"विद्यार्थी अनुमतिपत्रको म्याद सकिनुअघि","hi":"छात्र परमिट ख़त्म होने से पहले"}},"steps":[{"title":{"en":"Get proof that you graduated","ne":"स्नातक भएको प्रमाण लिनुहोस्","hi":"स्नातक होने का सबूत लें"},"body":{"en":"Ask your examination office for a certificate or a confirmation that you have passed, if the diploma isn’t ready yet.","ne":"डिग्री प्रमाणपत्र तयार नभए परीक्षा कार्यालयसँग पास भएको प्रमाणपत्र वा पुष्टि-पत्र माग्नुहोस्।","hi":"अगर डिग्री तैयार नहीं है तो परीक्षा कार्यालय से पास होने का प्रमाणपत्र या पुष्टि-पत्र मांगें।"}},{"title":{"en":"Apply online in Leipzig","ne":"लाइपजिगमा अनलाइन आवेदन दिनुहोस्","hi":"लाइपज़िग में ऑनलाइन आवेदन करें"},"body":{"en":"Apply to the foreigners’ office before your current permit ends. You must show that you can support yourself and are insured.","ne":"हालको अनुमतिपत्रको म्याद सकिनुअघि विदेशी कार्यालयमा आवेदन दिनुहोस्। आफूलाई धान्न सक्ने र बीमित भएको देखाउनुपर्छ।","hi":"मौजूदा परमिट ख़त्म होने से पहले विदेशी कार्यालय में आवेदन करें। आपको दिखाना होगा कि आप अपना ख़र्च उठा सकते हैं और बीमित हैं।"},"cost":{"en":"About €93–100","ne":"करिब €९३–१००","hi":"लगभग €93–100"}},{"title":{"en":"Found a qualified job? Switch your permit","ne":"योग्यताअनुसारको काम पाउनुभयो? अनुमतिपत्र बदल्नुहोस्","hi":"योग्य नौकरी मिली? परमिट बदलें"},"body":{"en":"With a job that matches your degree, you can apply for an EU Blue Card or a residence permit for skilled workers. The 18 months can’t be extended.","ne":"डिग्रीअनुसारको काम पाएपछि EU Blue Card वा दक्ष कामदारको आवास अनुमतिपत्रका लागि आवेदन दिन सक्नुहुन्छ। १८ महिना थप गर्न मिल्दैन।","hi":"डिग्री के अनुरूप नौकरी मिलने पर आप EU Blue Card या कुशल कामगार निवास परमिट के लिए आवेदन कर सकते हैं। 18 महीने बढ़ाए नहीं जा सकते।"},"term":{"term":"Blaue Karte EU"}}],"documents":[{"en":"Passport and current residence permit","ne":"राहदानी र हालको आवास अनुमतिपत्र","hi":"पासपोर्ट और मौजूदा निवास परमिट"},{"en":"Degree certificate or confirmation of passing","ne":"डिग्री प्रमाणपत्र वा पास भएको पुष्टि-पत्र","hi":"डिग्री प्रमाणपत्र या पास होने का पुष्टि-पत्र"},{"en":"Proof of money for the job search","ne":"काम खोज्ने अवधिका लागि पैसाको प्रमाण","hi":"नौकरी खोजने की अवधि के लिए पैसे का सबूत"},{"en":"Proof of health insurance","ne":"स्वास्थ्य बीमाको प्रमाण","hi":"स्वास्थ्य बीमा का सबूत"}],"callouts":[{"kind":"tip","text":{"en":"Once you graduate, student health insurance ends. Tell your fund straight away so your insurance continues without a gap.","ne":"स्नातक भएपछि विद्यार्थी स्वास्थ्य बीमा सकिन्छ। बीमा बीचमा नरोकियोस् भनेर तुरुन्तै कोषलाई जानकारी दिनुहोस्।","hi":"स्नातक होते ही छात्र स्वास्थ्य बीमा ख़त्म हो जाता है। बीमा बिना रुकावट जारी रहे, इसके लिए तुरंत कोष को बताएं।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Extend your residence permit","ne":"आवास अनुमतिपत्र नवीकरण गर्नुहोस्","hi":"निवास परमिट बढ़वाएं"},"href":"/guides/extend-your-residence-permit"},{"kind":"tool","title":{"en":"Net pay calculator","ne":"खुद तलब क्याल्कुलेटर","hi":"शुद्ध वेतन कैलकुलेटर"},"href":"/tools/net-pay"}],"actions":[{"label":{"en":"Apply online","ne":"अनलाइन आवेदन दिनुहोस्","hi":"ऑनलाइन आवेदन करें"},"url":"https://www.leipzig.de/service-portal/formulare/onlineantrag-erwerbstaetigkeit"}],"sources":[{"title":"Stadt Leipzig — Aufenthaltserlaubnis zur Arbeitsplatzsuche für Fachkräfte","url":"https://www.leipzig.de/service-portal/dienstleistung/aufenthaltserlaubnis-zur-arbeitsplatzsuche-fuer-fachkraefte-beantragen-5f2d13e815012"},{"title":"Stadt Leipzig — Online application: residence for employment","url":"https://www.leipzig.de/service-portal/formulare/onlineantrag-erwerbstaetigkeit"},{"title":"BAMF — Skilled workers with an academic education","url":"https://www.bamf.de/EN/Themen/MigrationAufenthalt/ZuwandererDrittstaaten/Arbeit/Hochschulabsolvent/hochschulabsolvent-node.html"},{"title":"Make it in Germany — Staying in Germany after your studies","url":"https://www.make-it-in-germany.com/en/staying-in-germany-after-studies"}]}$seed$::jsonb, 170) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'get-liability-insurance', $seed${"slug":"get-liability-insurance","title":{"en":"Get liability insurance","ne":"दायित्व बीमा लिनुहोस्","hi":"देयता बीमा लें"},"term":{"term":"Privathaftpflichtversicherung"},"stage":"living","readingMinutes":4,"lastVerified":"2026-11-05","summary":{"what":{"en":"Pays when you accidentally damage someone else’s things or hurt someone — for example a flooded flat below yours or a broken laptop. It is not compulsory, but consumer advice centres call it a must.","ne":"तपाईंले गल्तीले अरूको सामान बिगार्दा वा कसैलाई चोट पुर्‍याउँदा तिर्छ — जस्तै तलको फ्ल्याटमा पानी पस्दा वा ल्यापटप फुट्दा। यो अनिवार्य होइन, तर उपभोक्ता परामर्श केन्द्रहरू यसलाई अत्यावश्यक मान्छन्।","hi":"जब आप गलती से किसी और का सामान ख़राब करते हैं या किसी को चोट पहुंचाते हैं, तब यह भुगतान करता है — जैसे नीचे वाले फ़्लैट में पानी भरना या लैपटॉप टूटना। यह अनिवार्य नहीं है, लेकिन उपभोक्ता सलाह केंद्र इसे ज़रूरी मानते हैं।"},"when":{"en":"As soon as you live in your own room or flat.","ne":"आफ्नै कोठा वा फ्ल्याटमा बस्न थालेपछि तुरुन्तै।","hi":"जैसे ही आप अपने कमरे या फ़्लैट में रहने लगें।"},"deadline":{"en":"No deadline — but damage before you are insured is not covered","ne":"कुनै समयसीमा छैन — तर बीमा हुनुअघिको क्षति कभर हुँदैन","hi":"कोई समयसीमा नहीं — लेकिन बीमा से पहले का नुकसान कवर नहीं होता"}},"steps":[{"title":{"en":"Check whether you are already covered","ne":"पहिले नै कभर हुनुहुन्छ कि जाँच्नुहोस्","hi":"जांचें कि आप पहले से कवर हैं या नहीं"},"body":{"en":"Some landlords or rental contracts ask for it. Parents’ policies in Germany can cover children in their first training — but only if your parents have a German policy, which is rare for newcomers.","ne":"केही घरधनी वा भाडा सम्झौताले यो माग्छन्। जर्मनीमा आमाबुबाको बीमाले पहिलो तालिममा रहेका सन्तानलाई कभर गर्न सक्छ — तर आमाबुबासँग जर्मन बीमा भएमा मात्र, जुन नयाँ आउनेहरूमा विरलै हुन्छ।","hi":"कुछ मकान मालिक या किराया अनुबंध इसे मांगते हैं। जर्मनी में माता-पिता की पॉलिसी पहली ट्रेनिंग में बच्चों को कवर कर सकती है — लेकिन तभी जब माता-पिता की जर्मन पॉलिसी हो, जो नए आने वालों में कम होता है।"}},{"title":{"en":"Compare a few offers","ne":"केही प्रस्ताव तुलना गर्नुहोस्","hi":"कुछ ऑफ़र की तुलना करें"},"body":{"en":"A single-person policy is usually enough. Choose cover of at least €10 million (better €50 million). Paying once a year is usually cheaper than monthly.","ne":"एक व्यक्तिको बीमा प्रायः पर्याप्त हुन्छ। कम्तीमा €१ करोड (राम्रो €५ करोड) को कभर छान्नुहोस्। वर्षमा एकपटक तिर्नु प्रायः मासिकभन्दा सस्तो हुन्छ।","hi":"अकेले व्यक्ति की पॉलिसी आमतौर पर काफ़ी है। कम से कम €1 करोड़ (बेहतर €5 करोड़) का कवर चुनें। साल में एक बार भुगतान आमतौर पर मासिक से सस्ता होता है।"},"cost":{"en":"A good basic policy: about €60–80 a year","ne":"राम्रो आधारभूत बीमा: वर्षको करिब €६०–८०","hi":"अच्छी बुनियादी पॉलिसी: साल के लगभग €60–80"}},{"title":{"en":"Sign up online","ne":"अनलाइन दर्ता गर्नुहोस्","hi":"ऑनलाइन साइन अप करें"},"body":{"en":"You need your German address and bank account. Cover starts on the date in your policy — keep the policy document.","ne":"जर्मन ठेगाना र बैंक खाता चाहिन्छ। बीमामा लेखिएको मितिदेखि कभर सुरु हुन्छ — बीमा कागजात राख्नुहोस्।","hi":"आपको जर्मन पता और बैंक खाता चाहिए। कवर पॉलिसी में लिखी तारीख से शुरू होता है — पॉलिसी का दस्तावेज़ रखें।"},"term":{"term":"Versicherungsschein"}}],"documents":[{"en":"Passport","ne":"राहदानी","hi":"पासपोर्ट"},{"en":"German address","ne":"जर्मन ठेगाना","hi":"जर्मन पता"},{"en":"German bank account (IBAN)","ne":"जर्मन बैंक खाता (IBAN)","hi":"जर्मन बैंक खाता (IBAN)"}],"callouts":[{"kind":"tip","text":{"en":"Check that “damage to rented property” (Mietsachschäden) is included — that is the most common case for tenants.","ne":"“भाडाको सम्पत्तिमा क्षति” (Mietsachschäden) समावेश छ कि जाँच्नुहोस् — भाडावालका लागि यो सबैभन्दा सामान्य अवस्था हो।","hi":"जांचें कि “किराए की संपत्ति को नुकसान” (Mietsachschäden) शामिल है — किरायेदारों के लिए यह सबसे आम मामला है।"}},{"kind":"mistake","text":{"en":"Liability insurance doesn’t cover your own things. For theft or fire in your room you need household contents insurance (Hausratversicherung).","ne":"दायित्व बीमाले तपाईंको आफ्नै सामान कभर गर्दैन। कोठामा चोरी वा आगलागीका लागि घरायसी सामान बीमा (Hausratversicherung) चाहिन्छ।","hi":"देयता बीमा आपके अपने सामान को कवर नहीं करता। कमरे में चोरी या आग के लिए घरेलू सामान बीमा (Hausratversicherung) चाहिए।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Find a room in Leipzig","ne":"लाइपजिगमा कोठा खोज्नुहोस्","hi":"लाइपज़िग में कमरा खोजें"},"href":"/guides/find-housing-leipzig"},{"kind":"tool","title":{"en":"Plan your monthly budget","ne":"मासिक बजेट योजना बनाउनुहोस्","hi":"मासिक बजट की योजना बनाएं"},"href":"/tools/budget"}],"sources":[{"title":"Verbraucherzentrale — Private liability insurance: a must for everyone","url":"https://www.verbraucherzentrale.de/wissen/geld-versicherungen/weitere-versicherungen/private-haftpflichtversicherung-ein-absolutes-muss-fuer-alle-13891"},{"title":"Verbraucherzentrale — Insurance for students","url":"https://www.verbraucherzentrale.de/wissen/geld-versicherungen/weitere-versicherungen/versicherungen-fuer-studierende-die-unerlaesslichen-policen-10510"}]}$seed$::jsonb, 180) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'separate-your-waste', $seed${"slug":"separate-your-waste","title":{"en":"Separate your waste","ne":"फोहोर छुट्याउनुहोस्","hi":"कचरा अलग करें"},"term":{"term":"Mülltrennung"},"stage":"living","city":"leipzig","readingMinutes":3,"lastVerified":"2026-11-05","summary":{"what":{"en":"In Germany each kind of waste has its own bin. Neighbours and landlords take it seriously, and wrong sorting can cost your building extra.","ne":"जर्मनीमा हरेक प्रकारको फोहोरको आफ्नै बिन हुन्छ। छिमेकी र घरधनी यसलाई गम्भीर रूपमा लिन्छन्, र गलत छुट्याउँदा भवनलाई थप खर्च लाग्न सक्छ।","hi":"जर्मनी में हर तरह के कचरे का अपना डिब्बा होता है। पड़ोसी और मकान मालिक इसे गंभीरता से लेते हैं, और गलत छंटाई से इमारत पर अतिरिक्त ख़र्च आ सकता है।"},"when":{"en":"From your first day in the flat.","ne":"फ्ल्याटमा पहिलो दिनदेखि।","hi":"फ़्लैट में पहले दिन से।"},"deadline":{"en":"No deadline","ne":"कुनै समयसीमा छैन","hi":"कोई समयसीमा नहीं"}},"steps":[{"title":{"en":"Yellow bin: packaging","ne":"पहेँलो बिन: प्याकेजिङ","hi":"पीला डिब्बा: पैकेजिंग"},"body":{"en":"Plastic, metal and drink cartons — empty, no need to wash. In Leipzig the “Gelbe Tonne PLUS” also takes other items made of plastic or metal. No electrical devices.","ne":"प्लास्टिक, धातु र पेय पदार्थका कार्टुन — खाली गरेर, धुनु पर्दैन। लाइपजिगमा “Gelbe Tonne PLUS” मा प्लास्टिक वा धातुका अन्य सामान पनि हाल्न मिल्छ। बिजुली उपकरण होइन।","hi":"प्लास्टिक, धातु और पेय कार्टन — ख़ाली करके, धोने की ज़रूरत नहीं। लाइपज़िग में “Gelbe Tonne PLUS” में प्लास्टिक या धातु की दूसरी चीज़ें भी डाल सकते हैं। बिजली के उपकरण नहीं।"},"term":{"term":"Gelbe Tonne"}},{"title":{"en":"Blue bin: paper and cardboard","ne":"निलो बिन: कागज र कार्डबोर्ड","hi":"नीला डिब्बा: काग़ज़ और गत्ता"},"body":{"en":"Clean, dry paper and boxes. A pizza box only if it is lightly soiled — otherwise it goes in the general waste.","ne":"सफा, सुक्खा कागज र बाकस। पिज्जा बाकस थोरै फोहोर भए मात्र — नत्र सामान्य फोहोरमा।","hi":"साफ़, सूखा काग़ज़ और डिब्बे। पिज़्ज़ा बॉक्स केवल हल्का गंदा हो तो — वरना सामान्य कचरे में।"},"term":{"term":"Blaue Tonne"}},{"title":{"en":"Brown bin: food waste","ne":"खैरो बिन: खानाको फोहोर","hi":"भूरा डिब्बा: खाने का कचरा"},"body":{"en":"Food leftovers, coffee grounds, tea bags, plant cuttings. No plastic bags — not even “compostable” ones.","ne":"बाँकी खाना, कफीको धुलो, चियाको झोला, बिरुवाका पात। प्लास्टिक झोला होइन — “कम्पोस्ट हुने” भनिएका पनि होइन।","hi":"बचा हुआ खाना, कॉफ़ी का चूरा, टी-बैग, पौधों की कटाई। प्लास्टिक की थैली नहीं — “कम्पोस्ट होने वाली” भी नहीं।"},"term":{"term":"Biotonne"}},{"title":{"en":"Glass containers and general waste","ne":"सिसाको कन्टेनर र सामान्य फोहोर","hi":"कांच के कंटेनर और सामान्य कचरा"},"body":{"en":"Bottles and jars go into the street containers by colour (unclear colours into green). Everything else — hygiene items, vacuum bags, porcelain — into the grey general waste bin.","ne":"बोतल र भाँडा रङअनुसार सडकका कन्टेनरमा (अस्पष्ट रङ हरियोमा)। बाँकी सबै — सरसफाइ सामग्री, भ्याकुम झोला, पोर्सिलेन — खैरो-कालो सामान्य फोहोर बिनमा।","hi":"बोतलें और जार रंग के अनुसार सड़क के कंटेनर में (अस्पष्ट रंग हरे में)। बाक़ी सब — स्वच्छता सामग्री, वैक्यूम बैग, पोर्सिलेन — धूसर सामान्य कचरे के डिब्बे में।"},"term":{"term":"Restabfall"}}],"documents":[{"en":"Nothing needed","ne":"केही चाहिँदैन","hi":"कुछ नहीं चाहिए"}],"callouts":[{"kind":"tip","text":{"en":"Bottles and cans with the “Pfand” logo are worth money: return them at any supermarket machine and get 8–25 cents each.","ne":"“Pfand” चिन्ह भएका बोतल र क्यानको पैसा फिर्ता आउँछ: जुनसुकै सुपरमार्केटको मेसिनमा फिर्ता गर्नुहोस् र प्रत्येकमा ८–२५ सेन्ट पाउनुहोस्।","hi":"“Pfand” निशान वाली बोतलें और कैन पैसे वापस दिलाते हैं: किसी भी सुपरमार्केट की मशीन में लौटाएं और हर एक पर 8–25 सेंट पाएं।"}},{"kind":"mistake","text":{"en":"Old electronics and batteries never go in the household bins. Take them to a recycling centre (Wertstoffhof) or back to the shop.","ne":"पुराना इलेक्ट्रोनिक सामान र ब्याट्री घरायसी बिनमा कहिल्यै नहाल्नुहोस्। पुनःप्रयोग केन्द्र (Wertstoffhof) वा पसलमा फिर्ता लैजानुहोस्।","hi":"पुराने इलेक्ट्रॉनिक सामान और बैटरी कभी घरेलू डिब्बों में न डालें। उन्हें रीसाइक्लिंग केंद्र (Wertstoffhof) या दुकान पर वापस ले जाएं।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Find a room in Leipzig","ne":"लाइपजिगमा कोठा खोज्नुहोस्","hi":"लाइपज़िग में कमरा खोजें"},"href":"/guides/find-housing-leipzig"},{"kind":"guide","title":{"en":"Check your utility bill","ne":"उपयोगिता बिल जाँच्नुहोस्","hi":"उपयोगिता बिल जांचें"},"href":"/guides/check-your-utility-bill"}],"sources":[{"title":"Stadtreinigung Leipzig — What goes in which bin (PDF)","url":"https://stadtreinigung-leipzig.de/upload/files/2021/trennhilfe-was-gehoert-in-welche-tonne.pdf"},{"title":"Stadt Leipzig — How to sort plastic, paper, tea bags and more","url":"https://www.leipzig.de/newsarchiv/news/wie%20plastik,%20papier,%20teebeutel%20und%20co.%20richtig%20zu%20trennen%20sind"}]}$seed$::jsonb, 190) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'learn-german', $seed${"slug":"learn-german","title":{"en":"Learn German","ne":"जर्मन भाषा सिक्नुहोस्","hi":"जर्मन सीखें"},"term":{"term":"Deutschkurs"},"stage":"living","city":"leipzig","readingMinutes":4,"lastVerified":"2026-11-05","summary":{"what":{"en":"German opens doors: student jobs, flats, friends — and later a settlement permit, which needs B1 German.","ne":"जर्मन भाषाले ढोका खोल्छ: विद्यार्थी काम, फ्ल्याट, साथी — र पछि स्थायी बसोबास अनुमति, जसका लागि B1 जर्मन चाहिन्छ।","hi":"जर्मन भाषा दरवाज़े खोलती है: छात्र नौकरी, फ़्लैट, दोस्त — और बाद में स्थायी निवास परमिट, जिसके लिए B1 जर्मन चाहिए।"},"when":{"en":"Start in your first semester — even with an English-taught programme.","ne":"पहिलो सेमेस्टरमै सुरु गर्नुहोस् — अंग्रेजी माध्यमको कार्यक्रम भए पनि।","hi":"पहले सेमेस्टर में शुरू करें — अंग्रेज़ी माध्यम का कोर्स हो तब भी।"},"deadline":{"en":"No deadline","ne":"कुनै समयसीमा छैन","hi":"कोई समयसीमा नहीं"}},"steps":[{"title":{"en":"Take a course at your university","ne":"विश्वविद्यालयमा कक्षा लिनुहोस्","hi":"विश्वविद्यालय में कोर्स करें"},"body":{"en":"Leipzig University offers German courses alongside your studies (Studienkolleg Sachsen) and at the Language Centre. Students often pay reduced prices — check the current fees.","ne":"लाइपजिग विश्वविद्यालयले पढाइसँगै जर्मन कक्षा (Studienkolleg Sachsen) र भाषा केन्द्रमा कक्षा दिन्छ। विद्यार्थीले प्रायः छुट मूल्य तिर्छन् — हालको शुल्क जाँच्नुहोस्।","hi":"लाइपज़िग विश्वविद्यालय पढ़ाई के साथ जर्मन कोर्स (Studienkolleg Sachsen) और भाषा केंद्र में कोर्स देता है। छात्र अक्सर कम कीमत देते हैं — मौजूदा फ़ीस देखें।"}},{"title":{"en":"Need it faster? Take an intensive course","ne":"छिटो चाहियो? गहन कक्षा लिनुहोस्","hi":"जल्दी चाहिए? गहन कोर्स करें"},"body":{"en":"interDaF at Leipzig University runs paid intensive courses from A1 to C1, about two months each.","ne":"लाइपजिग विश्वविद्यालयको interDaF ले A1 देखि C1 सम्म सशुल्क गहन कक्षा चलाउँछ, प्रत्येक करिब दुई महिनाको।","hi":"लाइपज़िग विश्वविद्यालय का interDaF A1 से C1 तक शुल्क वाले गहन कोर्स चलाता है, हर एक लगभग दो महीने का।"}},{"title":{"en":"Practise for free","ne":"निःशुल्क अभ्यास गर्नुहोस्","hi":"मुफ़्त अभ्यास करें"},"body":{"en":"Find a tandem partner at the Language Centre: you teach Nepali, Hindi or English, they teach German. Use the phrasebook in this app for everyday situations.","ne":"भाषा केन्द्रमा ट्यान्डम साथी खोज्नुहोस्: तपाईं नेपाली, हिन्दी वा अंग्रेजी सिकाउनुहुन्छ, उनीहरू जर्मन। दैनिक अवस्थाका लागि यो एपको वाक्यपुस्तिका प्रयोग गर्नुहोस्।","hi":"भाषा केंद्र में टैंडम पार्टनर खोजें: आप नेपाली, हिंदी या अंग्रेज़ी सिखाएं, वे जर्मन। रोज़मर्रा की स्थितियों के लिए इस ऐप की वाक्य-पुस्तिका इस्तेमाल करें।"},"cost":{"en":"Free","ne":"निःशुल्क","hi":"मुफ़्त"},"term":{"term":"Sprachtandem"}},{"title":{"en":"Get a certificate","ne":"प्रमाणपत्र लिनुहोस्","hi":"प्रमाणपत्र लें"},"body":{"en":"For jobs and permits you need proof, for example a Goethe, telc or TestDaF certificate at B1 or higher.","ne":"काम र अनुमतिका लागि प्रमाण चाहिन्छ, जस्तै B1 वा माथिको Goethe, telc वा TestDaF प्रमाणपत्र।","hi":"नौकरी और परमिट के लिए सबूत चाहिए, जैसे B1 या उससे ऊपर का Goethe, telc या TestDaF प्रमाणपत्र।"},"term":{"term":"Sprachzertifikat"}}],"documents":[{"en":"Student ID or enrolment certificate (for student prices)","ne":"विद्यार्थी परिचयपत्र वा भर्ना प्रमाणपत्र (विद्यार्थी मूल्यका लागि)","hi":"छात्र पहचान-पत्र या दाख़िला प्रमाणपत्र (छात्र कीमत के लिए)"},{"en":"Passport","ne":"राहदानी","hi":"पासपोर्ट"}],"callouts":[{"kind":"tip","text":{"en":"Even A2 German makes calls with offices, landlords and doctors much easier.","ne":"A2 जर्मनले पनि कार्यालय, घरधनी र डाक्टरसँगका कुरा धेरै सजिलो बनाउँछ।","hi":"A2 जर्मन से भी दफ़्तरों, मकान मालिकों और डॉक्टरों से बात बहुत आसान हो जाती है।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"tool","title":{"en":"Phrasebook","ne":"वाक्यपुस्तिका","hi":"वाक्य-पुस्तिका"},"href":"/tools/phrasebook"},{"kind":"guide","title":{"en":"Get a settlement permit","ne":"स्थायी बसोबास अनुमति लिनुहोस्","hi":"स्थायी निवास परमिट लें"},"href":"/guides/get-a-settlement-permit"}],"sources":[{"title":"Leipzig University — German alongside your studies (Studienkolleg Sachsen)","url":"https://www.stksachs.uni-leipzig.de/studium/deutsch-im-studium"},{"title":"Leipzig University — Language Centre","url":"https://www.sprachenzentrum.uni-leipzig.de/"},{"title":"Leipzig University — interDaF intensive German courses A1–C1","url":"https://www.interdaf.uni-leipzig.de/intensive-language-courses.html"}]}$seed$::jsonb, 200) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'check-your-utility-bill', $seed${"slug":"check-your-utility-bill","title":{"en":"Check your utility bill","ne":"उपयोगिता बिल जाँच्नुहोस्","hi":"उपयोगिता बिल जांचें"},"term":{"term":"Nebenkostenabrechnung"},"stage":"living","readingMinutes":4,"lastVerified":"2026-11-05","summary":{"what":{"en":"Once a year your landlord settles the advance payments for heating, water and building costs. You either get money back or have to pay extra.","ne":"वर्षमा एकपटक घरधनीले तताउने, पानी र भवन खर्चको अग्रिम भुक्तानी हिसाब मिलाउँछ। तपाईंले पैसा फिर्ता पाउनुहुन्छ वा थप तिर्नुपर्छ।","hi":"साल में एक बार मकान मालिक हीटिंग, पानी और इमारत के ख़र्चों के अग्रिम भुगतान का हिसाब करता है। या तो पैसा वापस मिलता है या ज़्यादा देना पड़ता है।"},"when":{"en":"When the yearly statement arrives.","ne":"वार्षिक हिसाब आएपछि।","hi":"जब सालाना हिसाब आए।"},"deadline":{"en":"Objections within 12 months of receiving it","ne":"पाएको १२ महिनाभित्र आपत्ति","hi":"मिलने के 12 महीने के अंदर आपत्ति"}},"steps":[{"title":{"en":"Check the date","ne":"मिति जाँच्नुहोस्","hi":"तारीख जांचें"},"body":{"en":"The landlord must send the statement within 12 months after the end of the billing period. If it arrives later, they can usually no longer ask you to pay extra.","ne":"घरधनीले बिलिङ अवधि सकिएको १२ महिनाभित्र हिसाब पठाउनुपर्छ। पछि आएमा प्रायः थप रकम माग्न पाउँदैनन्।","hi":"मकान मालिक को बिलिंग अवधि ख़त्म होने के 12 महीने के अंदर हिसाब भेजना होता है। बाद में आए तो आमतौर पर अतिरिक्त भुगतान नहीं मांग सकते।"}},{"title":{"en":"Compare it with your contract","ne":"सम्झौतासँग तुलना गर्नुहोस्","hi":"अनुबंध से तुलना करें"},"body":{"en":"Only costs agreed in your rental contract may be charged. Check how costs are split (by m², people or meter readings) and that the period is right.","ne":"भाडा सम्झौतामा तय भएका खर्च मात्र लिन पाइन्छ। खर्च कसरी बाँडिएको छ (वर्गमिटर, मान्छे वा मिटर रिडिङअनुसार) र अवधि सही छ कि जाँच्नुहोस्।","hi":"केवल किराया अनुबंध में तय ख़र्च ही लिए जा सकते हैं। देखें कि ख़र्च कैसे बांटे गए हैं (वर्ग मीटर, लोग या मीटर रीडिंग से) और अवधि सही है।"}},{"title":{"en":"Ask to see the receipts","ne":"रसिद हेर्न माग्नुहोस्","hi":"रसीदें देखने को कहें"},"body":{"en":"You may look at the bills behind the statement. Write to your landlord if something looks wrong — keep a copy.","ne":"हिसाबपछाडिका बिल हेर्ने अधिकार छ। केही गलत देखिए घरधनीलाई लेखेर पठाउनुहोस् — प्रतिलिपि राख्नुहोस्।","hi":"आप हिसाब के पीछे के बिल देख सकते हैं। कुछ ग़लत लगे तो मकान मालिक को लिखें — एक कॉपी रखें।"},"term":{"term":"Belegeinsicht"}}],"documents":[{"en":"Rental contract","ne":"भाडा सम्झौता","hi":"किराया अनुबंध"},{"en":"The yearly statement","ne":"वार्षिक हिसाब","hi":"सालाना हिसाब"},{"en":"Your own meter readings, if you have them","ne":"आफ्नै मिटर रिडिङ, छ भने","hi":"आपकी अपनी मीटर रीडिंग, अगर हो"}],"callouts":[{"kind":"tip","text":{"en":"Not sure? The Mieterverein checks statements for members — often worth it for one bill alone.","ne":"शंका छ? Mieterverein ले सदस्यका लागि हिसाब जाँच्छ — एउटै बिलका लागि पनि प्रायः फाइदाजनक।","hi":"पक्का नहीं? Mieterverein सदस्यों के लिए हिसाब जांचता है — अक्सर एक ही बिल के लिए भी फ़ायदेमंद।"}},{"kind":"mistake","text":{"en":"Pay an extra amount on time even if you object — otherwise you risk reminders and fees. Your objection still counts.","ne":"आपत्ति गरे पनि थप रकम समयमै तिर्नुहोस् — नत्र रिमाइन्डर र शुल्क लाग्न सक्छ। तपाईंको आपत्ति मान्य रहन्छ।","hi":"आपत्ति करें तब भी अतिरिक्त रकम समय पर भरें — वरना रिमाइंडर और शुल्क लग सकते हैं। आपकी आपत्ति मान्य रहती है।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Find a room in Leipzig","ne":"लाइपजिगमा कोठा खोज्नुहोस्","hi":"लाइपज़िग में कमरा खोजें"},"href":"/guides/find-housing-leipzig"},{"kind":"tool","title":{"en":"Where to get help","ne":"सहयोग कहाँ पाउने","hi":"मदद कहाँ मिलेगी"},"href":"/get-help"}],"sources":[{"title":"German Civil Code § 556 — Service charges and the yearly statement","url":"https://www.gesetze-im-internet.de/bgb/__556.html"},{"title":"Mieterverein Leipzig — Frequently asked questions","url":"https://www.mieterverein-leipzig.de/mitgliedschaft/meistgestellte-fragen/"}]}$seed$::jsonb, 210) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'convert-your-driving-licence', $seed${"slug":"convert-your-driving-licence","title":{"en":"Use or convert your driving licence","ne":"ड्राइभिङ लाइसेन्स प्रयोग वा रूपान्तरण गर्नुहोस्","hi":"ड्राइविंग लाइसेंस इस्तेमाल करें या बदलवाएं"},"term":{"term":"Führerschein umschreiben"},"stage":"living","readingMinutes":4,"lastVerified":"2026-11-05","summary":{"what":{"en":"A licence from Nepal or India is valid in Germany for 6 months after you move here. After that you need a German licence.","ne":"नेपाल वा भारतको लाइसेन्स जर्मनी सरेपछि ६ महिनासम्म मान्य हुन्छ। त्यसपछि जर्मन लाइसेन्स चाहिन्छ।","hi":"नेपाल या भारत का लाइसेंस जर्मनी आने के बाद 6 महीने तक मान्य है। उसके बाद जर्मन लाइसेंस चाहिए।"},"when":{"en":"Only if you want to drive in Germany.","ne":"जर्मनीमा गाडी चलाउन चाहनुहुन्छ भने मात्र।","hi":"केवल अगर आप जर्मनी में गाड़ी चलाना चाहते हैं।"},"deadline":{"en":"6 months after you register your address","ne":"ठेगाना दर्ता गरेको ६ महिनापछि","hi":"पता पंजीकरण के 6 महीने बाद"}},"steps":[{"title":{"en":"Drive with your licence for the first 6 months","ne":"पहिलो ६ महिना आफ्नै लाइसेन्सले चलाउनुहोस्","hi":"पहले 6 महीने अपने लाइसेंस से चलाएं"},"body":{"en":"Carry your original licence and an international driving permit or a German translation.","ne":"सक्कली लाइसेन्स र अन्तर्राष्ट्रिय ड्राइभिङ अनुमति वा जर्मन अनुवाद साथमा राख्नुहोस्।","hi":"असली लाइसेंस और अंतरराष्ट्रीय ड्राइविंग परमिट या जर्मन अनुवाद साथ रखें।"}},{"title":{"en":"Apply at the driving licence office","ne":"ड्राइभिङ लाइसेन्स कार्यालयमा आवेदन दिनुहोस्","hi":"ड्राइविंग लाइसेंस कार्यालय में आवेदन करें"},"body":{"en":"Apply at the Fahrerlaubnisbehörde of your city. Nepal and India are not on the list of countries with simplified conversion, so you usually have to pass the theory and practical test — without the full number of driving lessons.","ne":"आफ्नो सहरको Fahrerlaubnisbehörde मा आवेदन दिनुहोस्। नेपाल र भारत सजिलो रूपान्तरण हुने देशको सूचीमा छैनन्, त्यसैले प्रायः लिखित र व्यावहारिक परीक्षा पास गर्नुपर्छ — तर पूरा ड्राइभिङ कक्षा लिनु पर्दैन।","hi":"अपने शहर के Fahrerlaubnisbehörde में आवेदन करें। नेपाल और भारत आसान रूपांतरण वाले देशों की सूची में नहीं हैं, इसलिए आमतौर पर लिखित और व्यावहारिक परीक्षा पास करनी होती है — पूरी ड्राइविंग क्लास के बिना।"},"term":{"term":"Fahrerlaubnisbehörde"}},{"title":{"en":"Prepare with a driving school","ne":"ड्राइभिङ स्कुलमार्फत तयारी गर्नुहोस्","hi":"ड्राइविंग स्कूल के साथ तैयारी करें"},"body":{"en":"A driving school registers you for the tests. The theory test is available in several languages.","ne":"ड्राइभिङ स्कुलले परीक्षाका लागि दर्ता गराउँछ। लिखित परीक्षा धेरै भाषामा दिन सकिन्छ।","hi":"ड्राइविंग स्कूल आपको परीक्षाओं के लिए पंजीकृत करता है। लिखित परीक्षा कई भाषाओं में उपलब्ध है।"},"term":{"term":"Fahrschule"}}],"documents":[{"en":"Foreign driving licence (original) and translation","ne":"विदेशी ड्राइभिङ लाइसेन्स (सक्कली) र अनुवाद","hi":"विदेशी ड्राइविंग लाइसेंस (असली) और अनुवाद"},{"en":"Passport","ne":"राहदानी","hi":"पासपोर्ट"},{"en":"Registration certificate (date you moved in)","ne":"दर्ता प्रमाणपत्र (सरेको मिति)","hi":"पंजीकरण प्रमाणपत्र (आने की तारीख)"},{"en":"Biometric photo, eye test and first-aid course certificate","ne":"बायोमेट्रिक फोटो, आँखा जाँच र प्राथमिक उपचार तालिम प्रमाणपत्र","hi":"बायोमेट्रिक फ़ोटो, आंखों की जांच और प्राथमिक चिकित्सा कोर्स प्रमाणपत्र"}],"callouts":[{"kind":"warning","text":{"en":"Driving after the 6 months without a German licence counts as driving without a licence.","ne":"६ महिनापछि जर्मन लाइसेन्सबिना गाडी चलाउनु लाइसेन्सविना चलाएको मानिन्छ।","hi":"6 महीने के बाद जर्मन लाइसेंस के बिना गाड़ी चलाना बिना लाइसेंस चलाना माना जाता है।"}},{"kind":"tip","text":{"en":"You may not need a car: the Deutschlandticket and car sharing cover most trips in cities.","ne":"तपाईंलाई कार नचाहिन सक्छ: सहरमा धेरैजसो यात्रा Deutschlandticket र कार सेयरिङले पुग्छ।","hi":"हो सकता है आपको कार की ज़रूरत न हो: शहरों में ज़्यादातर सफ़र Deutschlandticket और कार शेयरिंग से हो जाते हैं।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Get a monthly transit pass","ne":"मासिक यातायात पास लिनुहोस्","hi":"मासिक परिवहन पास लें"},"href":"/guides/monthly-transit-pass"},{"kind":"guide","title":{"en":"Register your address","ne":"आफ्नो ठेगाना दर्ता गर्नुहोस्","hi":"अपना पता पंजीकृत करें"},"href":"/guides/register-your-address"}],"sources":[{"title":"Driving Licence Regulation § 29 — Foreign driving licences","url":"https://www.gesetze-im-internet.de/fev_2010/__29.html"},{"title":"Driving Licence Regulation, Annex 11 — Countries with simplified conversion","url":"https://www.gesetze-im-internet.de/fev_2010/anlage_11.html"},{"title":"ADAC — Converting a driving licence from a non-EU country","url":"https://www.adac.de/infotestrat/ratgeber-verkehr/fuehrerschein/auslaendische-fuehrerscheine/default.aspx"}]}$seed$::jsonb, 220) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'write-a-german-cv', $seed${"slug":"write-a-german-cv","title":{"en":"Write a German CV and application","ne":"जर्मन CV र आवेदन लेख्नुहोस्","hi":"जर्मन CV और आवेदन लिखें"},"term":{"term":"Lebenslauf"},"stage":"career","readingMinutes":6,"lastVerified":"2026-11-05","summary":{"what":{"en":"German employers expect a short, tabular CV and a cover letter written for the job. Most applications are sent online as one PDF.","ne":"जर्मन रोजगारदाताले छोटो, तालिकाबद्ध CV र कामका लागि लेखिएको आवेदन पत्र अपेक्षा गर्छन्। धेरैजसो आवेदन एउटै PDF मा अनलाइन पठाइन्छ।","hi":"जर्मन नियोक्ता एक छोटा, तालिका वाला CV और नौकरी के लिए लिखा कवर लेटर चाहते हैं। ज़्यादातर आवेदन एक PDF में ऑनलाइन भेजे जाते हैं।"},"when":{"en":"Before you apply for student jobs, internships or your first job.","ne":"विद्यार्थी काम, इन्टर्नसिप वा पहिलो कामका लागि आवेदन दिनुअघि।","hi":"छात्र नौकरी, इंटर्नशिप या पहली नौकरी के लिए आवेदन से पहले।"},"deadline":{"en":"Deadline in each job advert","ne":"हरेक विज्ञापनमा लेखिएको समयसीमा","hi":"हर नौकरी विज्ञापन में लिखी समयसीमा"}},"steps":[{"title":{"en":"Build a tabular CV (1–2 pages)","ne":"तालिकाबद्ध CV बनाउनुहोस् (१–२ पाना)","hi":"तालिका वाला CV बनाएं (1–2 पेज)"},"body":{"en":"Newest first: work experience, education, skills (languages with levels such as German B1), IT skills. Use a clear layout without nested tables or graphics — many companies scan CVs automatically.","ne":"नयाँ पहिले: कामको अनुभव, शिक्षा, सीप (जर्मन B1 जस्ता तहसहित भाषा), IT सीप। जटिल तालिका वा ग्राफिक्सबिना सफा ढाँचा प्रयोग गर्नुहोस् — धेरै कम्पनीले CV स्वचालित रूपमा स्क्यान गर्छन्।","hi":"नया पहले: कार्य अनुभव, शिक्षा, कौशल (जर्मन B1 जैसे स्तर के साथ भाषाएं), IT कौशल। जटिल टेबल या ग्राफ़िक्स के बिना साफ़ लेआउट रखें — कई कंपनियां CV अपने आप स्कैन करती हैं।"},"term":{"term":"tabellarischer Lebenslauf"}},{"title":{"en":"Decide about the photo","ne":"फोटोबारे निर्णय गर्नुहोस्","hi":"फ़ोटो के बारे में तय करें"},"body":{"en":"A photo is not required by law. If you add one, use a professional photo — not a selfie. Some employers ask for anonymous CVs without a photo.","ne":"कानुनले फोटो अनिवार्य गर्दैन। राख्नुहुन्छ भने व्यावसायिक फोटो प्रयोग गर्नुहोस् — सेल्फी होइन। केही रोजगारदाताले फोटोबिनाको अज्ञात CV माग्छन्।","hi":"क़ानूनन फ़ोटो ज़रूरी नहीं है। लगाएं तो पेशेवर फ़ोटो लगाएं — सेल्फ़ी नहीं। कुछ नियोक्ता बिना फ़ोटो का गुमनाम CV मांगते हैं।"},"term":{"term":"Bewerbungsfoto"}},{"title":{"en":"Use this structure","ne":"यो ढाँचा प्रयोग गर्नुहोस्","hi":"यह ढांचा इस्तेमाल करें"},"body":{"en":"1. Personal details: name, address in Germany, phone, email (date of birth, nationality and photo are optional). 2. Work experience: month/year – month/year, job title, company, city, 2–3 results. 3. Education: degree, university, city, years, grade or focus. 4. Skills: languages with levels (e.g. German B1, English C1, Nepali/Hindi native), software and tools. 5. Optional: projects, volunteering, interests that fit the job. End with place, date and your name.","ne":"१. व्यक्तिगत विवरण: नाम, जर्मनीको ठेगाना, फोन, इमेल (जन्ममिति, राष्ट्रियता र फोटो ऐच्छिक)। २. कामको अनुभव: महिना/वर्ष – महिना/वर्ष, पद, कम्पनी, सहर, २–३ उपलब्धि। ३. शिक्षा: डिग्री, विश्वविद्यालय, सहर, वर्ष, ग्रेड वा विषय। ४. सीप: तहसहित भाषा (जस्तै जर्मन B1, अंग्रेजी C1, नेपाली/हिन्दी मातृभाषा), सफ्टवेयर र उपकरण। ५. ऐच्छिक: परियोजना, स्वयंसेवा, कामसँग मिल्ने रुचि। अन्त्यमा ठाउँ, मिति र आफ्नो नाम लेख्नुहोस्।","hi":"1. व्यक्तिगत विवरण: नाम, जर्मनी का पता, फ़ोन, ईमेल (जन्मतिथि, राष्ट्रीयता और फ़ोटो वैकल्पिक)। 2. कार्य अनुभव: महीना/साल – महीना/साल, पद, कंपनी, शहर, 2–3 उपलब्धियां। 3. शिक्षा: डिग्री, विश्वविद्यालय, शहर, साल, ग्रेड या विषय। 4. कौशल: स्तर के साथ भाषाएं (जैसे जर्मन B1, अंग्रेज़ी C1, नेपाली/हिंदी मातृभाषा), सॉफ़्टवेयर और टूल। 5. वैकल्पिक: प्रोजेक्ट, स्वयंसेवा, नौकरी से जुड़ी रुचियां। अंत में जगह, तारीख और अपना नाम लिखें।"},"term":{"term":"Aufbau des Lebenslaufs"}},{"title":{"en":"Write a cover letter for this job","ne":"यो कामका लागि आवेदन पत्र लेख्नुहोस्","hi":"इस नौकरी के लिए कवर लेटर लिखें"},"body":{"en":"At most one page. Say why this job and this company, with examples that match the advert. Avoid “würde” and “könnte” — write confidently.","ne":"बढीमा एक पाना। किन यो काम र यो कम्पनी, विज्ञापनसँग मिल्ने उदाहरणसहित लेख्नुहोस्। “würde” र “könnte” नलेख्नुहोस् — आत्मविश्वासका साथ लेख्नुहोस्।","hi":"ज़्यादा से ज़्यादा एक पेज। बताएं कि यही नौकरी और यही कंपनी क्यों, विज्ञापन से मेल खाते उदाहरणों के साथ। “würde” और “könnte” से बचें — आत्मविश्वास से लिखें।"},"term":{"term":"Anschreiben"}},{"title":{"en":"Send one PDF","ne":"एउटै PDF पठाउनुहोस्","hi":"एक PDF भेजें"},"body":{"en":"Combine cover letter, CV, certificates and references (Arbeitszeugnisse) into one PDF, unless the company asks for something else. Follow the company’s instructions exactly.","ne":"कम्पनीले अरू नमागेसम्म आवेदन पत्र, CV, प्रमाणपत्र र कार्य प्रमाणपत्र (Arbeitszeugnisse) एउटै PDF मा राख्नुहोस्। कम्पनीको निर्देशन ठ्याक्कै पालना गर्नुहोस्।","hi":"कंपनी कुछ और न मांगे तो कवर लेटर, CV, प्रमाणपत्र और कार्य प्रमाणपत्र (Arbeitszeugnisse) एक PDF में जोड़ें। कंपनी के निर्देशों का ठीक-ठीक पालन करें।"},"term":{"term":"Bewerbungsunterlagen"}}],"documents":[{"en":"CV (Lebenslauf)","ne":"CV (Lebenslauf)","hi":"CV (Lebenslauf)"},{"en":"Cover letter (Anschreiben)","ne":"आवेदन पत्र (Anschreiben)","hi":"कवर लेटर (Anschreiben)"},{"en":"Degree certificates and transcripts","ne":"डिग्री प्रमाणपत्र र अङ्कपत्र","hi":"डिग्री प्रमाणपत्र और अंकपत्र"},{"en":"Work references and language certificates","ne":"कार्य प्रमाणपत्र र भाषा प्रमाणपत्र","hi":"कार्य प्रमाणपत्र और भाषा प्रमाणपत्र"}],"callouts":[{"kind":"tip","text":{"en":"Your university’s careers service and the Federal Employment Agency check CVs for free.","ne":"विश्वविद्यालयको करियर सेवा र संघीय रोजगार एजेन्सीले निःशुल्क CV जाँच्छन्।","hi":"विश्वविद्यालय की करियर सेवा और संघीय रोज़गार एजेंसी मुफ़्त में CV जांचते हैं।"}},{"kind":"mistake","text":{"en":"Don’t send the same letter to every company. Recruiters notice a generic letter at once.","ne":"हरेक कम्पनीलाई उही पत्र नपठाउनुहोस्। भर्ती गर्नेले सामान्य पत्र तुरुन्तै चिन्छन्।","hi":"हर कंपनी को एक ही पत्र न भेजें। भर्ती करने वाले सामान्य पत्र तुरंत पहचान लेते हैं।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Find an internship","ne":"इन्टर्नसिप खोज्नुहोस्","hi":"इंटर्नशिप खोजें"},"href":"/guides/find-an-internship"},{"kind":"guide","title":{"en":"Get your degree recognised","ne":"डिग्री मान्यता लिनुहोस्","hi":"अपनी डिग्री की मान्यता लें"},"href":"/guides/get-your-degree-recognised"}],"sources":[{"title":"Federal Employment Agency — What goes into a job application","url":"https://www.arbeitsagentur.de/bildung/bewerbung/bewerbungsunterlagen"},{"title":"Federal Employment Agency — Writing an application","url":"https://www.arbeitsagentur.de/arbeitslos-arbeit-finden/bewerbungstraining/bewerbung-schreiben"}]}$seed$::jsonb, 230) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'get-your-degree-recognised', $seed${"slug":"get-your-degree-recognised","title":{"en":"Get your degree recognised","ne":"डिग्री मान्यता लिनुहोस्","hi":"अपनी डिग्री की मान्यता लें"},"term":{"term":"Anerkennung"},"stage":"career","readingMinutes":5,"lastVerified":"2026-11-05","summary":{"what":{"en":"A degree from Nepal or India can be compared with a German one. For regulated jobs (e.g. doctor, nurse, teacher) recognition is required; for most other jobs it helps employers and the immigration office.","ne":"नेपाल वा भारतको डिग्रीलाई जर्मन डिग्रीसँग तुलना गर्न सकिन्छ। नियमित पेशा (जस्तै डाक्टर, नर्स, शिक्षक) का लागि मान्यता अनिवार्य हुन्छ; अन्य धेरैजसो कामका लागि यसले रोजगारदाता र विदेशी कार्यालयलाई सहयोग गर्छ।","hi":"नेपाल या भारत की डिग्री की तुलना जर्मन डिग्री से की जा सकती है। विनियमित पेशों (जैसे डॉक्टर, नर्स, शिक्षक) के लिए मान्यता ज़रूरी है; ज़्यादातर दूसरी नौकरियों में यह नियोक्ताओं और विदेशी कार्यालय की मदद करती है।"},"when":{"en":"Before you apply for a job with a degree from home.","ne":"देशको डिग्रीले काम खोज्नुअघि।","hi":"अपने देश की डिग्री से नौकरी के लिए आवेदन से पहले।"},"deadline":{"en":"Allow up to 3 months","ne":"३ महिनासम्म समय राख्नुहोस्","hi":"3 महीने तक का समय रखें"}},"steps":[{"title":{"en":"Find out whether your job is regulated","ne":"तपाईंको पेशा नियमित हो कि पत्ता लगाउनुहोस्","hi":"पता करें कि आपका पेशा विनियमित है या नहीं"},"body":{"en":"The official “Anerkennungs-Finder” tells you which office is responsible and what you need.","ne":"आधिकारिक “Anerkennungs-Finder” ले कुन कार्यालय जिम्मेवार छ र के चाहिन्छ भन्छ।","hi":"आधिकारिक “Anerkennungs-Finder” बताता है कि कौन-सा कार्यालय ज़िम्मेदार है और क्या चाहिए।"},"cost":{"en":"Free","ne":"निःशुल्क","hi":"मुफ़्त"}},{"title":{"en":"Check anabin first","ne":"पहिले anabin जाँच्नुहोस्","hi":"पहले anabin जांचें"},"body":{"en":"If your university is rated “H+” and your degree is listed in the anabin database, a free printout is often enough for employers.","ne":"तपाईंको विश्वविद्यालय anabin मा “H+” छ र डिग्री सूचीमा छ भने, निःशुल्क प्रिन्टआउट प्रायः रोजगारदाताका लागि पुग्छ।","hi":"अगर आपका विश्वविद्यालय anabin में “H+” है और डिग्री सूची में है, तो मुफ़्त प्रिंटआउट अक्सर नियोक्ताओं के लिए काफ़ी होता है।"},"term":{"term":"anabin"}},{"title":{"en":"Otherwise apply for a Statement of Comparability","ne":"नत्र तुलनात्मक प्रमाणपत्रका लागि आवेदन दिनुहोस्","hi":"वरना तुलनात्मक प्रमाणपत्र के लिए आवेदन करें"},"body":{"en":"The Central Office for Foreign Education (ZAB) issues it online. It describes your degree in German terms.","ne":"विदेशी शिक्षाको केन्द्रीय कार्यालय (ZAB) ले अनलाइन जारी गर्छ। यसले तपाईंको डिग्रीलाई जर्मन सर्तमा वर्णन गर्छ।","hi":"विदेशी शिक्षा का केंद्रीय कार्यालय (ZAB) इसे ऑनलाइन जारी करता है। यह आपकी डिग्री को जर्मन संदर्भ में बताता है।"},"term":{"term":"Zeugnisbewertung"},"cost":{"en":"€208","ne":"€२०८","hi":"€208"},"wait":{"en":"Up to 3 months","ne":"३ महिनासम्म","hi":"3 महीने तक"}}],"documents":[{"en":"Degree certificates and transcripts","ne":"डिग्री प्रमाणपत्र र अङ्कपत्र","hi":"डिग्री प्रमाणपत्र और अंकपत्र"},{"en":"Certified translations (if not in English or German)","ne":"प्रमाणित अनुवाद (अंग्रेजी वा जर्मनमा नभए)","hi":"प्रमाणित अनुवाद (अगर अंग्रेज़ी या जर्मन में न हो)"},{"en":"Passport","ne":"राहदानी","hi":"पासपोर्ट"}],"callouts":[{"kind":"tip","text":{"en":"Graduated from a German university? Then you don’t need recognition for your German degree.","ne":"जर्मन विश्वविद्यालयबाट स्नातक गर्नुभयो? त्यसो भए जर्मन डिग्रीका लागि मान्यता चाहिँदैन।","hi":"जर्मन विश्वविद्यालय से स्नातक हैं? तो आपकी जर्मन डिग्री के लिए मान्यता की ज़रूरत नहीं है।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Write a German CV and application","ne":"जर्मन CV र आवेदन लेख्नुहोस्","hi":"जर्मन CV और आवेदन लिखें"},"href":"/guides/write-a-german-cv"},{"kind":"guide","title":{"en":"Get an EU Blue Card","ne":"EU Blue Card लिनुहोस्","hi":"EU Blue Card लें"},"href":"/guides/get-an-eu-blue-card"}],"sources":[{"title":"Federal Government — Recognition in Germany (Anerkennungs-Finder)","url":"https://www.anerkennung-in-deutschland.de/"},{"title":"ZAB (KMK) — Statement of Comparability: FAQ and fees","url":"https://zab.kmk.org/en/statement-of-comparability/faq"}]}$seed$::jsonb, 240) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'find-an-internship', $seed${"slug":"find-an-internship","title":{"en":"Find an internship","ne":"इन्टर्नसिप खोज्नुहोस्","hi":"इंटर्नशिप खोजें"},"term":{"term":"Praktikum"},"stage":"career","readingMinutes":4,"lastVerified":"2026-11-05","summary":{"what":{"en":"Internships give German work experience for your CV. Whether one counts towards your work limit depends on whether your study programme requires it.","ne":"इन्टर्नसिपले CV का लागि जर्मन कामको अनुभव दिन्छ। यो तपाईंको कामको सीमामा गनिन्छ कि गनिँदैन भन्ने कुरा तपाईंको पढाइ कार्यक्रमले यसलाई अनिवार्य गर्छ कि गर्दैन भन्नेमा भर पर्छ।","hi":"इंटर्नशिप से CV के लिए जर्मन कार्य अनुभव मिलता है। यह आपकी काम की सीमा में गिनी जाएगी या नहीं, यह इस पर निर्भर है कि आपका कोर्स इसे अनिवार्य करता है या नहीं।"},"when":{"en":"From your second or third semester — apply 3–6 months ahead.","ne":"दोस्रो वा तेस्रो सेमेस्टरदेखि — ३–६ महिनाअघि आवेदन दिनुहोस्।","hi":"दूसरे या तीसरे सेमेस्टर से — 3–6 महीने पहले आवेदन करें।"},"deadline":{"en":"Deadline in each advert","ne":"हरेक विज्ञापनमा लेखिएको समयसीमा","hi":"हर विज्ञापन में लिखी समयसीमा"}},"steps":[{"title":{"en":"Check if it is compulsory","ne":"अनिवार्य हो कि जाँच्नुहोस्","hi":"जांचें कि यह अनिवार्य है या नहीं"},"body":{"en":"A compulsory internship in your study regulations does not count towards the 140 full days. A voluntary internship does — even if it is unpaid.","ne":"पढाइको नियममा अनिवार्य इन्टर्नसिप १४० पूरा दिनमा गनिँदैन। स्वैच्छिक इन्टर्नसिप गनिन्छ — निःशुल्क भए पनि।","hi":"पढ़ाई के नियमों में अनिवार्य इंटर्नशिप 140 पूरे दिनों में नहीं गिनी जाती। स्वैच्छिक इंटर्नशिप गिनी जाती है — बिना वेतन हो तब भी।"},"term":{"term":"Pflichtpraktikum"}},{"title":{"en":"Search where companies post","ne":"कम्पनीहरूले राख्ने ठाउँमा खोज्नुहोस्","hi":"जहां कंपनियां पोस्ट करती हैं, वहां खोजें"},"body":{"en":"Your university’s job portal and careers service, the Federal Employment Agency’s job board, and company websites.","ne":"विश्वविद्यालयको जब पोर्टल र करियर सेवा, संघीय रोजगार एजेन्सीको जब बोर्ड, र कम्पनीका वेबसाइट।","hi":"विश्वविद्यालय का जॉब पोर्टल और करियर सेवा, संघीय रोज़गार एजेंसी का जॉब बोर्ड, और कंपनियों की वेबसाइटें।"}},{"title":{"en":"Know your pay rights","ne":"तलबसम्बन्धी अधिकार बुझ्नुहोस्","hi":"वेतन के अधिकार जानें"},"body":{"en":"Voluntary internships longer than three months usually have to pay at least the minimum wage (€13.90 an hour in 2026). Compulsory internships don’t.","ne":"तीन महिनाभन्दा लामो स्वैच्छिक इन्टर्नसिपमा प्रायः कम्तीमा न्यूनतम ज्याला (२०२६ मा प्रतिघण्टा €१३.९०) दिनुपर्छ। अनिवार्यमा पर्दैन।","hi":"तीन महीने से लंबी स्वैच्छिक इंटर्नशिप में आमतौर पर कम से कम न्यूनतम वेतन (2026 में €13.90 प्रति घंटा) देना होता है। अनिवार्य में नहीं।"},"term":{"term":"Mindestlohn"}}],"documents":[{"en":"CV and cover letter","ne":"CV र आवेदन पत्र","hi":"CV और कवर लेटर"},{"en":"Enrolment certificate","ne":"भर्ना प्रमाणपत्र","hi":"दाख़िला प्रमाणपत्र"},{"en":"Study regulations page showing a compulsory internship","ne":"अनिवार्य इन्टर्नसिप देखाउने पढाइ नियमको पाना","hi":"अनिवार्य इंटर्नशिप दिखाने वाला पढ़ाई नियम का पेज"}],"callouts":[{"kind":"warning","text":{"en":"Voluntary internships use up your work days. Log them in the work-limit tool.","ne":"स्वैच्छिक इन्टर्नसिपले तपाईंका कामका दिन खर्च गर्छ। कामको सीमा उपकरणमा लेख्नुहोस्।","hi":"स्वैच्छिक इंटर्नशिप आपके काम के दिन ख़र्च करती है। उन्हें काम-सीमा टूल में दर्ज करें।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"tool","title":{"en":"Work-limit tracker","ne":"कामको सीमा ट्र्याकर","hi":"काम-सीमा ट्रैकर"},"href":"/tools/work-limit"},{"kind":"guide","title":{"en":"Write a German CV and application","ne":"जर्मन CV र आवेदन लेख्नुहोस्","hi":"जर्मन CV और आवेदन लिखें"},"href":"/guides/write-a-german-cv"}],"sources":[{"title":"DAAD — Side jobs for international students","url":"https://www.daad.de/en/study-and-research-in-germany/first-steps-germany/side-jobs/"},{"title":"Deutsche Rentenversicherung — Mini-job earnings limit rises to €603","url":"https://www.deutsche-rentenversicherung.de/BadenWuerttemberg/DE/Presse/Pressemitteilungen/2025/251222_Minijob.html"}]}$seed$::jsonb, 250) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'register-as-job-seeker', $seed${"slug":"register-as-job-seeker","title":{"en":"Register with the employment agency","ne":"रोजगार एजेन्सीमा दर्ता गर्नुहोस्","hi":"रोज़गार एजेंसी में पंजीकरण करें"},"term":{"term":"arbeitsuchend melden"},"stage":"career","readingMinutes":3,"lastVerified":"2026-11-05","summary":{"what":{"en":"The Federal Employment Agency helps you find work for free. If you have a job that is ending, registering in time is required by law.","ne":"संघीय रोजगार एजेन्सीले निःशुल्क काम खोज्न सहयोग गर्छ। तपाईंको काम सकिँदै छ भने समयमै दर्ता गर्नु कानुनी रूपमा अनिवार्य छ।","hi":"संघीय रोज़गार एजेंसी मुफ़्त में नौकरी खोजने में मदद करती है। अगर आपकी नौकरी ख़त्म हो रही है, तो समय पर पंजीकरण क़ानूनन ज़रूरी है।"},"when":{"en":"When you start looking for work — or as soon as you know your job will end.","ne":"काम खोज्न थाल्दा — वा काम सकिने थाहा पाउनेबित्तिकै।","hi":"जब आप नौकरी खोजना शुरू करें — या जैसे ही पता चले कि नौकरी ख़त्म होगी।"},"deadline":{"en":"At least 3 months before a job ends (or within 3 days if you learn later)","ne":"काम सकिनुभन्दा कम्तीमा ३ महिनाअघि (पछि थाहा भए ३ दिनभित्र)","hi":"नौकरी ख़त्म होने से कम से कम 3 महीने पहले (बाद में पता चले तो 3 दिन में)"}},"steps":[{"title":{"en":"Register online or by phone","ne":"अनलाइन वा फोनबाट दर्ता गर्नुहोस्","hi":"ऑनलाइन या फ़ोन से पंजीकरण करें"},"body":{"en":"Register on arbeitsagentur.de or call 0800 4555 500 (free).","ne":"arbeitsagentur.de मा दर्ता गर्नुहोस् वा ०८०० ४५५५ ५०० (निःशुल्क) मा फोन गर्नुहोस्।","hi":"arbeitsagentur.de पर पंजीकरण करें या 0800 4555 500 (मुफ़्त) पर कॉल करें।"},"cost":{"en":"Free","ne":"निःशुल्क","hi":"मुफ़्त"}},{"title":{"en":"Meet your advisor","ne":"आफ्नो सल्लाहकारलाई भेट्नुहोस्","hi":"अपने सलाहकार से मिलें"},"body":{"en":"You get job offers, application checks and information on courses. Bring your CV.","ne":"तपाईंले कामका प्रस्ताव, आवेदन जाँच र तालिमको जानकारी पाउनुहुन्छ। CV लैजानुहोस्।","hi":"आपको नौकरी के ऑफ़र, आवेदन की जांच और कोर्स की जानकारी मिलती है। CV साथ लाएं।"}},{"title":{"en":"Check what the job search means for your permit","ne":"काम खोजले अनुमतिपत्रमा के असर गर्छ जाँच्नुहोस्","hi":"जांचें कि नौकरी खोज का परमिट पर क्या असर है"},"body":{"en":"After graduation you can get a job-search permit for up to 18 months. Tell the foreigners’ office if your job ends.","ne":"स्नातकपछि १८ महिनासम्मको काम खोज अनुमति पाउन सकिन्छ। काम सकिएमा विदेशी कार्यालयलाई जानकारी दिनुहोस्।","hi":"स्नातक के बाद 18 महीने तक का नौकरी खोज परमिट मिल सकता है। नौकरी ख़त्म हो तो विदेशी कार्यालय को बताएं।"}}],"documents":[{"en":"CV","ne":"CV","hi":"CV"},{"en":"Passport and residence permit","ne":"राहदानी र आवास अनुमतिपत्र","hi":"पासपोर्ट और निवास परमिट"},{"en":"Employment contract and notice of termination (if any)","ne":"रोजगार सम्झौता र अन्त्यको सूचना (भए)","hi":"रोज़गार अनुबंध और समाप्ति की सूचना (अगर हो)"}],"callouts":[{"kind":"warning","text":{"en":"Registering too late can mean a blocking period for unemployment benefit.","ne":"ढिलो दर्ता गर्दा बेरोजगारी भत्तामा रोक अवधि लाग्न सक्छ।","hi":"देर से पंजीकरण करने पर बेरोज़गारी भत्ते पर रोक की अवधि लग सकती है।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Stay and look for work after graduation","ne":"स्नातकपछि बसेर काम खोज्नुहोस्","hi":"स्नातक के बाद रहकर नौकरी खोजें"},"href":"/guides/job-search-after-graduation"},{"kind":"guide","title":{"en":"Write a German CV and application","ne":"जर्मन CV र आवेदन लेख्नुहोस्","hi":"जर्मन CV और आवेदन लिखें"},"href":"/guides/write-a-german-cv"}],"sources":[{"title":"Federal Employment Agency — How to register as a job seeker","url":"https://www.arbeitsagentur.de/arbeitslos-arbeit-finden/arbeitslosengeld/ihre-schritte-wenn-sie-arbeitslos-werden/wie-sie-sich-arbeitsuchend-melden"}]}$seed$::jsonb, 260) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'get-an-eu-blue-card', $seed${"slug":"get-an-eu-blue-card","title":{"en":"Get an EU Blue Card","ne":"EU Blue Card लिनुहोस्","hi":"EU Blue Card लें"},"term":{"term":"Blaue Karte EU"},"stage":"career","readingMinutes":5,"lastVerified":"2026-11-05","summary":{"what":{"en":"A residence permit for graduates with a qualified job and a minimum salary. It leads faster to a settlement permit.","ne":"योग्यताअनुसारको काम र न्यूनतम तलब भएका स्नातकका लागि आवास अनुमतिपत्र। यसले छिटो स्थायी बसोबास अनुमतितर्फ लैजान्छ।","hi":"योग्य नौकरी और न्यूनतम वेतन वाले स्नातकों के लिए निवास परमिट। इससे स्थायी निवास परमिट जल्दी मिलता है।"},"when":{"en":"When you have a job offer that matches your degree.","ne":"डिग्रीअनुसारको कामको प्रस्ताव पाएपछि।","hi":"जब डिग्री के अनुरूप नौकरी का ऑफ़र मिले।"},"deadline":{"en":"Before your current permit ends","ne":"हालको अनुमतिपत्रको म्याद सकिनुअघि","hi":"मौजूदा परमिट ख़त्म होने से पहले"}},"steps":[{"title":{"en":"Check the salary threshold","ne":"तलबको सीमा जाँच्नुहोस्","hi":"वेतन सीमा जांचें"},"body":{"en":"2026: at least €50,700 gross a year. €45,934.20 is enough for shortage occupations and for graduates whose degree is less than three years old — then the Federal Employment Agency must agree.","ne":"२०२६: वर्षमा कम्तीमा €५०,७०० कुल तलब। अभाव भएका पेशा र तीन वर्षभन्दा नयाँ डिग्री भएका स्नातकका लागि €४५,९३४.२० पुग्छ — त्यस अवस्थामा संघीय रोजगार एजेन्सीको सहमति चाहिन्छ।","hi":"2026: साल में कम से कम €50,700 सकल वेतन। कमी वाले पेशों और तीन साल से नई डिग्री वाले स्नातकों के लिए €45,934.20 काफ़ी है — तब संघीय रोज़गार एजेंसी की सहमति ज़रूरी है।"}},{"title":{"en":"Get the employer’s documents","ne":"रोजगारदाताका कागजात लिनुहोस्","hi":"नियोक्ता के दस्तावेज़ लें"},"body":{"en":"You need the signed contract or a binding job offer, and often the form “Erklärung zum Beschäftigungsverhältnis” filled in by the employer.","ne":"हस्ताक्षर गरिएको सम्झौता वा बाध्यकारी कामको प्रस्ताव, र प्रायः रोजगारदाताले भरेको “Erklärung zum Beschäftigungsverhältnis” फारम चाहिन्छ।","hi":"आपको हस्ताक्षरित अनुबंध या बाध्यकारी नौकरी ऑफ़र चाहिए, और अक्सर नियोक्ता द्वारा भरा “Erklärung zum Beschäftigungsverhältnis” फ़ॉर्म।"}},{"title":{"en":"Apply at the foreigners’ office","ne":"विदेशी कार्यालयमा आवेदन दिनुहोस्","hi":"विदेशी कार्यालय में आवेदन करें"},"body":{"en":"In Leipzig you apply online for residence for employment. Apply before your current permit ends.","ne":"लाइपजिगमा रोजगारीका लागि आवासको अनलाइन आवेदन दिनुहुन्छ। हालको अनुमतिपत्रको म्याद सकिनुअघि आवेदन दिनुहोस्।","hi":"लाइपज़िग में आप रोज़गार के लिए निवास का ऑनलाइन आवेदन करते हैं। मौजूदा परमिट ख़त्म होने से पहले आवेदन करें।"},"where":{"en":"Ausländerbehörde (online application)","ne":"Ausländerbehörde (अनलाइन आवेदन)","hi":"Ausländerbehörde (ऑनलाइन आवेदन)"}}],"documents":[{"en":"Passport and residence permit","ne":"राहदानी र आवास अनुमतिपत्र","hi":"पासपोर्ट और निवास परमिट"},{"en":"Employment contract or binding job offer","ne":"रोजगार सम्झौता वा बाध्यकारी कामको प्रस्ताव","hi":"रोज़गार अनुबंध या बाध्यकारी नौकरी ऑफ़र"},{"en":"Degree certificates and transcripts","ne":"डिग्री प्रमाणपत्र र अङ्कपत्र","hi":"डिग्री प्रमाणपत्र और अंकपत्र"},{"en":"Proof of health insurance","ne":"स्वास्थ्य बीमाको प्रमाण","hi":"स्वास्थ्य बीमा का सबूत"},{"en":"Rental contract","ne":"भाडा सम्झौता","hi":"किराया अनुबंध"}],"callouts":[{"kind":"tip","text":{"en":"The salary thresholds change every year — check the current figure before you negotiate.","ne":"तलबको सीमा हरेक वर्ष बदलिन्छ — वार्ता गर्नुअघि हालको अंक जाँच्नुहोस्।","hi":"वेतन सीमा हर साल बदलती है — बातचीत से पहले मौजूदा आंकड़ा देखें।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Get a settlement permit","ne":"स्थायी बसोबास अनुमति लिनुहोस्","hi":"स्थायी निवास परमिट लें"},"href":"/guides/get-a-settlement-permit"},{"kind":"tool","title":{"en":"Net pay calculator","ne":"खुद तलब क्याल्कुलेटर","hi":"शुद्ध वेतन कैलकुलेटर"},"href":"/tools/net-pay"}],"sources":[{"title":"Federal Employment Agency — EU Blue Card (2026 salary thresholds)","url":"https://www.arbeitsagentur.de/vor-ort/zav/working-and-living-in-germany/iss-en/issue-03-2026/blue-card"},{"title":"Make it in Germany — EU Blue Card at a glance (PDF)","url":"https://www.make-it-in-germany.com/pdf-blaue-karte-eu"},{"title":"Stadt Leipzig — Online application: residence for employment","url":"https://www.leipzig.de/service-portal/formulare/onlineantrag-erwerbstaetigkeit"}]}$seed$::jsonb, 270) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'get-a-settlement-permit', $seed${"slug":"get-a-settlement-permit","title":{"en":"Get a settlement permit","ne":"स्थायी बसोबास अनुमति लिनुहोस्","hi":"स्थायी निवास परमिट लें"},"term":{"term":"Niederlassungserlaubnis"},"stage":"career","readingMinutes":5,"lastVerified":"2026-11-05","summary":{"what":{"en":"A permanent residence permit: no end date and any job allowed. Graduates of German universities can get it after two years of qualified work.","ne":"स्थायी आवास अनुमति: कुनै म्याद हुँदैन र जुनसुकै काम गर्न पाइन्छ। जर्मन विश्वविद्यालयका स्नातकले योग्यताअनुसारको दुई वर्षको कामपछि पाउन सक्छन्।","hi":"स्थायी निवास परमिट: कोई अंतिम तारीख नहीं और कोई भी नौकरी करने की अनुमति। जर्मन विश्वविद्यालयों के स्नातक दो साल के योग्य काम के बाद इसे पा सकते हैं।"},"when":{"en":"After two years of work with a German degree — earlier with a Blue Card and B1 German.","ne":"जर्मन डिग्रीसहित दुई वर्ष काम गरेपछि — Blue Card र B1 जर्मन भए अझ छिटो।","hi":"जर्मन डिग्री के साथ दो साल काम के बाद — Blue Card और B1 जर्मन से और जल्दी।"},"deadline":{"en":"No deadline","ne":"कुनै समयसीमा छैन","hi":"कोई समयसीमा नहीं"}},"steps":[{"title":{"en":"Check the conditions","ne":"सर्तहरू जाँच्नुहोस्","hi":"शर्तें जांचें"},"body":{"en":"With a German degree: two years with a residence permit for work, 24 months of pension contributions, a job that matches your degree and German at B1. With a Blue Card: after 21 months with B1 German.","ne":"जर्मन डिग्रीसहित: कामका लागि आवास अनुमतिपत्रसहित दुई वर्ष, २४ महिनाको पेन्सन योगदान, डिग्रीअनुसारको काम र B1 जर्मन। Blue Card सहित: B1 जर्मनसहित २१ महिनापछि।","hi":"जर्मन डिग्री के साथ: काम के निवास परमिट के साथ दो साल, 24 महीने का पेंशन योगदान, डिग्री के अनुरूप नौकरी और B1 जर्मन। Blue Card के साथ: B1 जर्मन के साथ 21 महीने बाद।"}},{"title":{"en":"Collect the proofs","ne":"प्रमाणहरू जम्मा गर्नुहोस्","hi":"सबूत इकट्ठा करें"},"body":{"en":"Your pension insurance statement shows the months of contributions. You also need a German B1 certificate and proof of basic knowledge of life in Germany (e.g. the “Leben in Deutschland” test).","ne":"पेन्सन बीमाको विवरणले योगदानका महिना देखाउँछ। B1 जर्मन प्रमाणपत्र र जर्मनीको जीवनबारे आधारभूत ज्ञानको प्रमाण (जस्तै “Leben in Deutschland” परीक्षा) पनि चाहिन्छ।","hi":"पेंशन बीमा का विवरण योगदान के महीने दिखाता है। B1 जर्मन प्रमाणपत्र और जर्मनी में जीवन के बुनियादी ज्ञान का सबूत (जैसे “Leben in Deutschland” टेस्ट) भी चाहिए।"},"term":{"term":"Versicherungsverlauf"}},{"title":{"en":"Apply at the foreigners’ office","ne":"विदेशी कार्यालयमा आवेदन दिनुहोस्","hi":"विदेशी कार्यालय में आवेदन करें"},"body":{"en":"Apply before your current permit ends. If you apply in time, your current permit stays valid while they decide.","ne":"हालको अनुमतिपत्रको म्याद सकिनुअघि आवेदन दिनुहोस्। समयमै आवेदन दिए निर्णय नहुँदासम्म हालको अनुमतिपत्र मान्य रहन्छ।","hi":"मौजूदा परमिट ख़त्म होने से पहले आवेदन करें। समय पर आवेदन करें तो फ़ैसले तक मौजूदा परमिट मान्य रहता है।"}}],"documents":[{"en":"Passport and residence permit","ne":"राहदानी र आवास अनुमतिपत्र","hi":"पासपोर्ट और निवास परमिट"},{"en":"Pension insurance statement","ne":"पेन्सन बीमा विवरण","hi":"पेंशन बीमा विवरण"},{"en":"Employment contract and recent payslips","ne":"रोजगार सम्झौता र हालका तलब पर्ची","hi":"रोज़गार अनुबंध और हाल की वेतन पर्चियां"},{"en":"German B1 certificate","ne":"B1 जर्मन प्रमाणपत्र","hi":"B1 जर्मन प्रमाणपत्र"},{"en":"German degree certificate","ne":"जर्मन डिग्री प्रमाणपत्र","hi":"जर्मन डिग्री प्रमाणपत्र"}],"callouts":[{"kind":"tip","text":{"en":"Start learning German early — B1 is the step most people need the most time for.","ne":"जर्मन चाँडै सिक्न सुरु गर्नुहोस् — धेरैलाई सबैभन्दा बढी समय B1 मा लाग्छ।","hi":"जर्मन जल्दी सीखना शुरू करें — ज़्यादातर लोगों को सबसे ज़्यादा समय B1 में लगता है।"}},{"kind":"legal","text":{"en":"General information, not legal advice. Rules can change — the official source linked below always takes precedence.","ne":"सामान्य जानकारी मात्र, कानुनी सल्लाह होइन। नियम बदलिन सक्छन् — तल दिइएको आधिकारिक स्रोत नै मान्य हुन्छ।","hi":"केवल सामान्य जानकारी, कानूनी सलाह नहीं। नियम बदल सकते हैं — नीचे दिया गया आधिकारिक स्रोत ही मान्य है।"}}],"related":[{"kind":"guide","title":{"en":"Learn German","ne":"जर्मन भाषा सिक्नुहोस्","hi":"जर्मन सीखें"},"href":"/guides/learn-german"},{"kind":"guide","title":{"en":"Get an EU Blue Card","ne":"EU Blue Card लिनुहोस्","hi":"EU Blue Card लें"},"href":"/guides/get-an-eu-blue-card"}],"sources":[{"title":"Make it in Germany — Settlement permit","url":"https://www.make-it-in-germany.com/de/visum-aufenthalt/dauerhaft-in-deutschland/niederlassungserlaubnis"},{"title":"BAMF — Settling permanently in Germany","url":"https://www.bamf.de/DE/Themen/MigrationAufenthalt/ZuwandererDrittstaaten/Migrathek/Niederlassen/niederlassen-node.html"}]}$seed$::jsonb, 280) on conflict (collection, key) do nothing;
