insert into public.content_documents (collection, key, data, sort_order) values ('helpServices', 'welcome', $seed${"id":"welcome","name":"Willkommenszentrum Leipzig","kind":{"en":"City advice for newcomers","ne":"नयाँ आउनेका लागि सहरको सल्लाह","hi":"नए लोगों के लिए शहर की सलाह"},"free":true,"description":{"en":"The City of Leipzig’s Welcome Centre gives first advice on residence, work, language courses and everyday life, and refers you to the right office.","ne":"लाइपजिग सहरको स्वागत केन्द्रले बसाइ, काम, भाषा कक्षा र दैनिक जीवनबारे प्रारम्भिक सल्लाह दिन्छ र सही कार्यालयमा पठाउँछ।","hi":"लाइपज़िग शहर का स्वागत केंद्र निवास, काम, भाषा कोर्स और रोज़मर्रा के जीवन पर शुरुआती सलाह देता है और सही कार्यालय तक भेजता है।"},"phone":"+49 341 1232676","address":"Otto-Schill-Straße 2, 04109 Leipzig","url":"https://english.leipzig.de/youth-family-and-community/foreign-nationals-and-migrants/welcome-centre-leipzig","topics":["visa","work","housing"],"sources":[{"title":"City of Leipzig — Welcome Centre","url":"https://english.leipzig.de/youth-family-and-community/foreign-nationals-and-migrants/welcome-centre-leipzig"},{"title":"Stadt Leipzig — Beratungsangebote im Willkommenszentrum","url":"https://www.leipzig.de/leben-in-leipzig/soziales/migration-und-integration/willkommenszentrum/beratungsangebote-und-informationen"}]}$seed$::jsonb, 0) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('helpServices', 'studentenwerk', $seed${"id":"studentenwerk","name":"Studentenwerk Leipzig — Social counselling","kind":{"en":"For students","ne":"विद्यार्थीका लागि","hi":"छात्रों के लिए"},"free":true,"description":{"en":"Free and confidential counselling for international students in several languages: money problems, jobs, housing, health insurance. Psychosocial counselling is also available.","ne":"अन्तर्राष्ट्रिय विद्यार्थीका लागि धेरै भाषामा निःशुल्क र गोप्य परामर्श: पैसाको समस्या, काम, आवास, स्वास्थ्य बीमा। मनोसामाजिक परामर्श पनि उपलब्ध छ।","hi":"अंतरराष्ट्रीय छात्रों के लिए कई भाषाओं में मुफ़्त और गोपनीय परामर्श: पैसे की समस्या, नौकरी, आवास, स्वास्थ्य बीमा। मनोसामाजिक परामर्श भी उपलब्ध है।"},"email":"sozialberatung@studentenwerk-leipzig.de","url":"https://www.studentenwerk-leipzig.de/en/counselling-social-issues/social-counselling/international-student-support/","topics":["money","housing","work","study","health"],"sources":[{"title":"Studentenwerk Leipzig — International student support","url":"https://www.studentenwerk-leipzig.de/en/counselling-social-issues/social-counselling/international-student-support/"},{"title":"Studentenwerk Leipzig — Social counselling for international students","url":"https://www.studentenwerk-leipzig.de/en/counselling-social-issues/social-counselling/international-students/"}]}$seed$::jsonb, 10) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('helpServices', 'caritas-mbe', $seed${"id":"caritas-mbe","name":"Caritas Leipzig — Migrationsberatung (MBE)","kind":{"en":"Migration counselling, 27+","ne":"आप्रवासन परामर्श, २७+","hi":"प्रवासन परामर्श, 27+"},"free":true,"description":{"en":"Help with residence permits, letters from authorities, work and language courses for adults from about 27 years.","ne":"करिब २७ वर्षमाथिका वयस्कका लागि आवास अनुमतिपत्र, सरकारी चिठी, काम र भाषा कक्षामा सहयोग।","hi":"लगभग 27 साल से ऊपर के वयस्कों के लिए निवास परमिट, सरकारी पत्र, काम और भाषा कोर्स में मदद।"},"phone":"+49 341 9636125","email":"migrantenhilfe@caritas-leipzig.de","address":"Ruth-Pfau-Straße 2, 04107 Leipzig","url":"https://www.caritas-leipzig.de/hilfeundberatung/migrationundintegration/migrationsberatung/migrationsberatung","topics":["visa","work"],"sources":[{"title":"Caritas Leipzig — Migration counselling for adults (MBE)","url":"https://www.caritas-leipzig.de/hilfeundberatung/migrationundintegration/migrationsberatung/migrationsberatung"}]}$seed$::jsonb, 20) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('helpServices', 'naomi-jmd', $seed${"id":"naomi-jmd","name":"Diakonie Leipzig — Jugendmigrationsdienst Naomi","kind":{"en":"Migration counselling, 12–27","ne":"आप्रवासन परामर्श, १२–२७","hi":"प्रवासन परामर्श, 12–27"},"free":true,"description":{"en":"Youth migration service for people aged 12 to 27: residence, studies, training, jobs and everyday questions.","ne":"१२ देखि २७ वर्षका लागि युवा आप्रवासन सेवा: बसाइ, पढाइ, तालिम, काम र दैनिक प्रश्न।","hi":"12 से 27 साल के लोगों के लिए युवा प्रवासन सेवा: निवास, पढ़ाई, प्रशिक्षण, नौकरी और रोज़मर्रा के सवाल।"},"phone":"+49 341 68709124","email":"jmd@diakonie-leipzig.de","address":"Eisenbahnstraße 66, 04315 Leipzig","url":"https://www.diakonie-leipzig.de/hilfe-angebote/beratung-nothilfe/naomi-jugendmigrationsberatung/","topics":["visa","study","work"],"sources":[{"title":"Diakonie Leipzig — Youth migration service Naomi","url":"https://www.diakonie-leipzig.de/hilfe-angebote/beratung-nothilfe/naomi-jugendmigrationsberatung/"}]}$seed$::jsonb, 30) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('helpServices', 'mieterverein', $seed${"id":"mieterverein","name":"Mieterverein Leipzig","kind":{"en":"Tenants’ association","ne":"भाडावाल संघ","hi":"किरायेदार संघ"},"free":false,"cost":{"en":"€84 a year + €10 joining fee · trial: €30 for 3 months","ne":"वर्षको €८४ + €१० प्रवेश शुल्क · परीक्षण: ३ महिनाको €३०","hi":"साल के €84 + €10 सदस्यता शुल्क · ट्रायल: 3 महीने के €30"},"description":{"en":"Checks rental contracts, deposits and service-charge bills, and advises members in disputes with landlords.","ne":"भाडा सम्झौता, धरौटी र सेवा शुल्कको बिल जाँच्छ, र घरधनीसँगको विवादमा सदस्यलाई सल्लाह दिन्छ।","hi":"किराया अनुबंध, जमानत और सेवा शुल्क के बिल जांचता है, और मकान मालिक से विवाद में सदस्यों को सलाह देता है।"},"phone":"+49 341 2131277","url":"https://www.mieterverein-leipzig.de/mitgliedschaft/","topics":["housing"],"sources":[{"title":"Mieterverein Leipzig — Membership","url":"https://www.mieterverein-leipzig.de/mitgliedschaft/"},{"title":"Mieterverein Leipzig — Frequently asked questions","url":"https://www.mieterverein-leipzig.de/mitgliedschaft/meistgestellte-fragen/"}]}$seed$::jsonb, 40) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('helpServices', 'p116117', $seed${"id":"p116117","name":"116117 — Patient service","kind":{"en":"Doctor at night and weekends","ne":"राति र सप्ताहान्तमा डाक्टर","hi":"रात और सप्ताहांत में डॉक्टर"},"free":true,"description":{"en":"Free, 24/7: on-call doctors when your practice is closed, help finding appointments, and a doctor search by language.","ne":"निःशुल्क, २४/७: क्लिनिक बन्द हुँदा अन-कल डाक्टर, अपोइन्टमेन्ट खोज्न सहयोग, र भाषाअनुसार डाक्टर खोज।","hi":"मुफ़्त, 24/7: क्लिनिक बंद होने पर ऑन-कॉल डॉक्टर, अपॉइंटमेंट खोजने में मदद, और भाषा के अनुसार डॉक्टर खोज।"},"phone":"116117","url":"https://www.116117.de/de/patientenservice.php","topics":["health"],"sources":[{"title":"116117 — Patient service","url":"https://www.116117.de/de/patientenservice.php"},{"title":"116117 — On-call medical service","url":"https://www.116117.de/de/aerztlicher-bereitschaftsdienst.php"}]}$seed$::jsonb, 50) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('helpServices', 'seelsorge', $seed${"id":"seelsorge","name":"TelefonSeelsorge","kind":{"en":"Someone to talk to","ne":"कुरा गर्ने कोही","hi":"कोई बात करने वाला"},"free":true,"description":{"en":"Feeling overwhelmed or alone? Talk to someone any time, day or night, anonymously and free of charge.","ne":"धेरै दबाब वा एक्लो महसुस भइरहेको छ? दिन होस् वा रात, जुनसुकै बेला गोप्य र निःशुल्क रूपमा कसैसँग कुरा गर्नुहोस्।","hi":"बहुत दबाव या अकेलापन महसूस हो रहा है? दिन हो या रात, कभी भी गुमनाम और मुफ़्त में किसी से बात करें।"},"phone":"0800 111 0 111","url":"https://www.telefonseelsorge.de/","topics":["health"],"sources":[{"title":"TelefonSeelsorge Deutschland","url":"https://www.telefonseelsorge.de/"}]}$seed$::jsonb, 60) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('scamWarnings', 'rental', $seed${"id":"rental","title":{"en":"A landlord wants money before you see the flat","ne":"फ्ल्याट हेर्नुअघि घरधनीले पैसा माग्छ","hi":"फ़्लैट देखने से पहले मकान मालिक पैसे मांगता है"},"signs":[{"en":"The landlord is “abroad” and will send the keys after you pay","ne":"घरधनी “विदेशमा” छ र पैसा तिरेपछि साँचो पठाउने भन्छ","hi":"मकान मालिक “विदेश में” है और भुगतान के बाद चाबी भेजने की बात करता है"},{"en":"Rent is far below other flats nearby","ne":"भाडा नजिकैका अन्य फ्ल्याटभन्दा धेरै कम छ","hi":"किराया आसपास के दूसरे फ़्लैटों से बहुत कम है"},{"en":"Payment by Western Union, gift cards or to a foreign account","ne":"Western Union, गिफ्ट कार्ड वा विदेशी खातामा भुक्तानी","hi":"Western Union, गिफ़्ट कार्ड या विदेशी खाते में भुगतान"},{"en":"Pressure to decide today","ne":"आजै निर्णय गर्न दबाब","hi":"आज ही फ़ैसला करने का दबाव"}],"actions":[{"en":"Pay nothing before a viewing and a signed contract","ne":"हेर्नु र सम्झौतामा हस्ताक्षर गर्नुअघि केही नतिर्नुहोस्","hi":"देखने और हस्ताक्षरित अनुबंध से पहले कुछ न भरें"},{"en":"Already paid? Ask your bank to recall the transfer immediately","ne":"तिरिसक्नुभयो? तुरुन्तै बैंकलाई ट्रान्सफर फिर्ता गर्न भन्नुहोस्","hi":"भुगतान कर दिया? तुरंत बैंक से ट्रांसफ़र वापस मंगाने को कहें"},{"en":"Report it to the police (online report possible) and keep screenshots","ne":"प्रहरीलाई खबर गर्नुहोस् (अनलाइन उजुरी गर्न मिल्छ) र स्क्रिनसट राख्नुहोस्","hi":"पुलिस में शिकायत करें (ऑनलाइन भी) और स्क्रीनशॉट रखें"}],"sources":[{"title":"Verbraucherzentrale — Spotting fake flat listings","url":"https://www.verbraucherzentrale.de/wissen/vertraege-reklamation/abzocke/fakewohnungen-im-internet-so-erkennen-sie-falsche-immobilienanzeigen-27576"},{"title":"Polizei — Advance-payment fraud online","url":"https://www.polizei-beratung.de/themen-und-tipps/sicher-handeln/onlinebetrug-maschen/vorkassebetrug/"},{"title":"German Civil Code § 551 — Rent deposit","url":"https://www.gesetze-im-internet.de/bgb/__551.html"}]}$seed$::jsonb, 0) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('scamWarnings', 'fake-officials', $seed${"id":"fake-officials","title":{"en":"A caller says they are from the police or an authority","ne":"फोन गर्नेले आफू प्रहरी वा सरकारी निकायबाट भएको भन्छ","hi":"फ़ोन करने वाला ख़ुद को पुलिस या सरकारी विभाग का बताता है"},"signs":[{"en":"They demand money, gift cards or bank details by phone","ne":"उनीहरू फोनमै पैसा, गिफ्ट कार्ड वा बैंक विवरण माग्छन्","hi":"वे फ़ोन पर पैसे, गिफ़्ट कार्ड या बैंक विवरण मांगते हैं"},{"en":"They threaten deportation or arrest if you don’t pay now","ne":"तुरुन्तै नतिरे देश निकाला वा पक्राउ गर्ने धम्की दिन्छन्","hi":"अभी भुगतान न करने पर निर्वासन या गिरफ़्तारी की धमकी देते हैं"},{"en":"“110” or an official number appears on your display","ne":"तपाईंको स्क्रिनमा “110” वा सरकारी नम्बर देखिन्छ","hi":"आपकी स्क्रीन पर “110” या सरकारी नंबर दिखता है"}],"actions":[{"en":"Hang up. The police and authorities never ask for money by phone","ne":"फोन राख्नुहोस्। प्रहरी र सरकारी निकायले फोनमा कहिल्यै पैसा माग्दैनन्","hi":"फ़ोन काट दें। पुलिस और सरकारी विभाग फ़ोन पर कभी पैसे नहीं मांगते"},{"en":"Call 110 yourself — numbers on the display can be faked","ne":"आफैं ११० मा फोन गर्नुहोस् — स्क्रिनमा देखिने नम्बर नक्कली हुन सक्छ","hi":"ख़ुद 110 पर कॉल करें — स्क्रीन पर दिखने वाले नंबर नकली हो सकते हैं"},{"en":"Real letters from the foreigners’ office come by post","ne":"विदेशी कार्यालयका सक्कली चिठी हुलाकबाट आउँछन्","hi":"विदेशी कार्यालय के असली पत्र डाक से आते हैं"}],"sources":[{"title":"Polizei — Fraud by fake police officers","url":"https://www.polizei-beratung.de/themen-und-tipps/betrug/betrug-durch-falsche-polizisten/"},{"title":"Polizei Sachsen — Fake police officers","url":"https://www.polizei.sachsen.de/de/101411.htm"}]}$seed$::jsonb, 10) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('scamWarnings', 'visa-agent', $seed${"id":"visa-agent","title":{"en":"An agent promises a “guaranteed visa” or a faster appointment","ne":"एजेन्टले “ग्यारेन्टी भिसा” वा छिटो अपोइन्टमेन्टको वाचा गर्छ","hi":"एजेंट “पक्का वीज़ा” या जल्दी अपॉइंटमेंट का वादा करता है"},"signs":[{"en":"They charge for appointments, which are free","ne":"निःशुल्क हुने अपोइन्टमेन्टका लागि पैसा लिन्छन्","hi":"मुफ़्त अपॉइंटमेंट के लिए पैसे लेते हैं"},{"en":"They offer to prepare bank statements or documents for you","ne":"तपाईंका लागि बैंक स्टेटमेन्ट वा कागजात बनाइदिने प्रस्ताव गर्छन्","hi":"आपके लिए बैंक स्टेटमेंट या दस्तावेज़ बनाने की पेशकश करते हैं"},{"en":"They claim contacts inside the embassy","ne":"दूतावासभित्र चिनजान भएको दाबी गर्छन्","hi":"दूतावास के अंदर जान-पहचान का दावा करते हैं"}],"actions":[{"en":"Book appointments only on the official embassy or VFS website","ne":"आधिकारिक दूतावास वा VFS वेबसाइटमा मात्र अपोइन्टमेन्ट बुक गर्नुहोस्","hi":"अपॉइंटमेंट केवल आधिकारिक दूतावास या VFS वेबसाइट पर बुक करें"},{"en":"Never submit documents you didn’t get yourself from the issuer","ne":"जारी गर्ने निकायबाट आफैंले नलिएको कागजात कहिल्यै नबुझाउनुहोस्","hi":"जो दस्तावेज़ आपने ख़ुद जारीकर्ता से नहीं लिए, उन्हें कभी जमा न करें"},{"en":"Report fraud attempts to the German embassy","ne":"ठगीको प्रयास जर्मन दूतावासलाई जानकारी गराउनुहोस्","hi":"धोखाधड़ी की कोशिश की सूचना जर्मन दूतावास को दें"}],"sources":[{"title":"German Embassy Kathmandu — Do I need an appointment?","url":"https://kathmandu.diplo.de/np-en/service/01-visaeinreise/2314484-2314484"},{"title":"German Consulate General Mumbai — Beware of fraud","url":"https://india.diplo.de/in-en/ueber-uns/mumbai/beware-of-fraud-1988568"}]}$seed$::jsonb, 20) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('embassies', 'nepal', $seed${"country":"nepal","name":"Embassy of Nepal, Berlin","phone":"+49 30 34359920","url":"https://de.nepalembassy.gov.np/","address":"Guerickestraße 27, 10587 Berlin","email":"eonberlin@mofa.gov.np","note":{"en":"Passports, documents and help in emergencies. A new passport can take 1–2 months — apply in time.","ne":"राहदानी, कागजात र आपतकालमा सहयोग। नयाँ राहदानीमा १–२ महिना लाग्न सक्छ — समयमै आवेदन दिनुहोस्।","hi":"पासपोर्ट, दस्तावेज़ और आपात स्थिति में मदद। नए पासपोर्ट में 1–2 महीने लग सकते हैं — समय पर आवेदन करें।"},"sources":[{"title":"Embassy of Nepal, Berlin","url":"https://de.nepalembassy.gov.np/"},{"title":"Ministry of Foreign Affairs of Nepal — Embassy in Germany","url":"https://nepalembassy.gov.np/embassy_post/germany/"}]}$seed$::jsonb, 0) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('embassies', 'india', $seed${"country":"india","name":"Embassy of India, Berlin","phone":"+49 30 257950","url":"https://indianembassyberlin.gov.in/","address":"Tiergartenstraße 17, 10785 Berlin","note":{"en":"Responsible for Indian citizens in Saxony, including Leipzig. Consular appointments are booked online.","ne":"लाइपजिगसहित सक्सोनीमा बस्ने भारतीय नागरिकका लागि जिम्मेवार। कन्सुलर अपोइन्टमेन्ट अनलाइन बुक गरिन्छ।","hi":"लाइपज़िग सहित सैक्सनी में रहने वाले भारतीय नागरिकों के लिए ज़िम्मेदार। कांसुलर अपॉइंटमेंट ऑनलाइन बुक होते हैं।"},"sources":[{"title":"Embassy of India, Berlin — Consular jurisdiction (PDF)","url":"https://indianembassyberlin.gov.in/pdf/passport_Jurisdiction_Berlin.pdf"},{"title":"Embassy of India, Berlin — Online appointments","url":"https://appointment.indianembassyberlin.gov.in/"}]}$seed$::jsonb, 10) on conflict (collection, key) do nothing;
